     *  мили вплотную» — 2:12 во всех четырёх (стендовый враг бьёт цель с наименьшими хитами). */
    private const val HEALER_W_DAMAGE = 0.05

    /** Штраф лекарю и раненому за клетку вплотную к живому вражескому мили: два с половиной шага пути — шаг прочь,
     *  когда мили подошёл (при равной скорости он бьёт лишь раз; в клетку рядом с врагом лекарь и так не входит). С весом огня 0.005 «только разница» (v9) лекари вставали вплотную к подопечному С ТОЙ СТОРОНЫ, где враг, и
     *  враг бил их первыми — матч 9: два лекаря без HEAL к 140-му тику, а лекари врага в 2–4 клетках за его строем не
     *  получили ни царапины и после боя вернули его армии всё (M8 → M8A8 к 185-му). Лекарь — единственная
     *  невосполнимая потеря: место у подопечного — с дальней от огня стороны (вес огня), от подошедшего мили — прочь. Стенд это правило не любит: его рывок держит лекарей вплотную и по лекарям не бьёт, оттого рубки
     *  sleeper на дебаффах v9 выигрывал вчистую, а v10 — по очкам; живые противники бьют лекарей первыми. */
    private const val HEALER_W_MELEE = 25.0

    /** Вес огня для лекаря, чей подопечный УЖЕ в бою. 0.005 (v9) — только подсказка, лекарь шёл под огонь стрелков в
     *  первый ряд (матч 9); 0.05 (v10a) держал его на кромке огня в 2–3 клетках всегда, и рубки sleeper на дебаффах
     *  0.6–0.75 были проиграны; 0.02 (v10) — клетка вплотную сзади выигрывала у отступа. При паритете (v14) обмен
     *  равных армий решает ВЫЖИВШИЙ лекарь: обе стороны остаются без оружия, и отрастает та, у которой лекари целы —
     *  враг держит своих в 2–4 клетках за строем, наши лечили касанием в первом ряду и были расстреляны (матч 13).
     *  Проверено на восьми боях стенда: 0.05 и 0.02 дали ОДИНАКОВЫЕ исходы до тика — бой решает доля мощи к контакту
     *  (см. PARITY_FLOOR), а не этот вес; оставлен 0.02, строй лекарей вне досягаемости стрелков — открытая находка. */
    private const val HEALER_W_DAMAGE_FIGHT = 0.02

    /** Множитель лечения врага в угрозе при выборе цели. Был 3.0 («убитый лекарь — единственная потеря, которую враг не
     *  вернёт лечением», матч 9) — и v31 снимает его до 1.0 по реплею матча 3 серии v30 (けろびー, обе стороны с
     *  интентами): лекарь у него давал 216 угрозы против 60 у стрелка, и в решающем стрелковом размене (t=80–110) 49 из
     *  77 наших выстрелов ушли в его лекарей, стоящих вплотную друг к другу (147 событий лечения ×72 = 10 584 — почти
     *  весь наш урон за бой, 10 440), а 70 из его 131 — в НАШИХ СТРЕЛКОВ: обезоруженный стрелок — минус 60 в тик
     *  навсегда, лечёный лекарь — ноль. Итог: наши стрелки без оружия 84 крип-тика, его — 8, выстрелов 288 против 174.
     *  Живая отдача лекаря по реплею равна отдаче стрелка (0,68 × 72 ≈ 0,81 × 60 ≈ 49 в тик), а взаимное лечение
     *  лекарей уже стоит в killTicks (healOn): при 1.0 стрелок у фронта (60 / 4,8 тика) выше лекаря в куче
     *  (72 / 7,7 тика), при 3.0 — наоборот. Лекарь без раненого рядом лечит на дистанции (4 за часть против 12) —
     *  треть, см. threatOf. */
    private const val HEALER_VALUE = 1.0

    /** Внутри стольких клеток от цели (Чебышев, сверх standoff) строй не держат: группа уже на месте, а
     *  ожидание «отставших» у самого флага запирало захватчика на тысячу тиков (стенд greedy/grab). */
    private const val ARRIVED_SLACK = 2

    /** Охрана флага: боевые враги в этом радиусе от флага (дальность сближения + выстрел). */
    private const val FLAG_GUARD_RANGE = 11

    /** Враг «рядом» с армией (для отхода): в этих клетках от кого-то из наших; из отхода выходим, когда он
     *  дальше NEAR_RANGE + NEAR_RELEASE (иначе постура прыгала каждый тик на кромке радиуса). */
    private const val NEAR_RANGE = 14
    private const val NEAR_RELEASE = 6

    private const val COHESION_GAP = 8
    private const val COHESION_GAP_MAX = 100
    private const val ENGAGE_COHESION_TICKS = 2
    private const val POST_STANDOFF = 2
    private const val ENGAGE_RANGE = 8
    private const val CLOSE_STANDOFF = 2
    private const val APPROACH_WINDOW = 20
    /** Запаздывание реакции на пошедшего врага: окно темпа плюс период пересчёта (см. exitMargin). */
    private const val REACTION_LAG = APPROACH_WINDOW + EVADE_EVAL_EVERY

    /** Столько тиков без сдвига — враг «стоит» и в стаи по «успеет дойти» не входит (см. packAt). */
    private const val STILL_TICKS = 20

    /** Дальше стольких клеток от авангарда отставший идёт К АВАНГАРДУ, а не к цели, и авангард его ждёт:
     *  сплочение по разнице поля не видит раскола на два обхода препятствия (матч 2 на стенде: две колонны
     *  в 30 клетках друг от друга с равной «отставкой», северная четвёрка легла под двенадцать). */
    private const val RALLY_RANGE = 12

    /** Далёкого напарника медленнее этого (тиков на клетку) авангард не ждёт — калека дойдёт, когда дойдёт. */
    private const val RALLY_MAX_PERIOD = 3

    /** Уже дерущийся выходит из боя только при таком местном соотношении (см. localAggressive в ANNIHILATE). */
    private const val ANNIHILATE_HOLD_RATIO = 0.5
    private const val USE_AVOID = true
    private const val USE_RALLY = true
    private const val USE_LOCAL_ANNIHILATE = true
    private const val USE_WOUNDED = true        // раненые остаются в армии и идут к лекарям (v9)
    private const val USE_HEALER_ADJ = true     // лекарь без штрафа за соседей, вес огня в бою — разница (v9)
    private const val USE_COMPACT_CLOSE = true  // снаружи зоны плотности шаг к центру открыт (v9)

    /** Клетки в такой близости от боевого врага поле «в обход» считает стеной (см. flowAvoiding). */
    private const val AVOID_RANGE = RANGED_RANGE + 1

    /** Вне боя шаг делается только ради заметно лучшей клетки: у поста клетки в зазоре standoff равноценны с
     *  точностью до штрафа за соседа (4), и отряд без порога всё время менялся местами — сотни обменов на сто
     *  тиков в матче 1. Порог меньше выигрыша одной клетки по полю (10) и больше одного соседа. */
    private const val STAY_BIAS = 5.0

    // веса оценки клетки (скопированы из spawn-and-swamp, где обкатаны)
    private const val PAIR_W_DIST = 10.0
    private const val PAIR_W_DAMAGE = 0.3
    private const val PAIR_W_INFLUENCE = 0.1
    private const val PAIR_W_OUTGOING = 30.0
    private const val PAIR_W_MELEE = 50.0
    private const val AGGRO_MELEE_FACTOR = 0.3
    private const val PAIR_W_SPREAD = 4.0
    private const val PAIR_W_SWAMP = 40.0
    private const val SEPARATION_RADIUS = 1
    private const val CROWD_COST = 3

    private const val FIGHTER_PRIORITY = 3
    private const val RUNNER_PRIORITY = 2
    /** Раненый уступает дорогу всем: его место — за лекарями, а не между ними и строем. */
    private const val WOUNDED_PRIORITY = 1

    // ---------- отладка ----------
    // версия играющей сборки — первой строкой лога матча: по ней матч привязывается к коду (см. правила сессий)
    private const val BOT_VERSION = "v70"
    private const val DEBUG_LOG = true
    private const val DEBUG_MAP = true
    /** Выключено: отрисовка влияния — ~57 000 вызовов contribution за тик (13×13 клеток × 12 стрелков × 28 крипов),
     *  первый тик матча 7 вылетел по таймауту именно в drawDebug; журнал даёт всё, что нужно для разбора. */
    private const val DEBUG_VISUALS = false
    private const val LOG_EVERY = 10

    private val DIRECTIONS = listOf(
        0 to 0, -1 to -1, 0 to -1, 1 to -1, -1 to 0, 1 to 0, -1 to 1, 0 to 1, 1 to 1,
    )

    private enum class Posture { HOLD, RETREAT, ANNIHILATE, FLAG, EVADE }

    private var greeted = false
    private var mapMarks: HashMap<Int, Char>? = null   // метки дампа карты, снятые на первом тике
    private var posture = Posture.HOLD
    private var objectiveFlagId: String? = null
    private var postureLogged = ""

    /** Стартовые центры армий — «дома» сторон (спавнов нет): половины карты и точка поста. */
    private var homePos: Position? = null
    private var enemyHomePos: Position? = null

    private val approachingIds = HashSet<String>()
    private val arrivalById = HashMap<String, Int>()
    private val approachHistory = HashMap<String, ArrayDeque<Pair<Int, Int>>>()
    private val enemyPrevCell = HashMap<String, Int>()
    /** id врага -> тик его последнего сдвига (см. stationary). */
    private val enemyLastMove = HashMap<String, Int>()
    /** Центр вооружённой армии и клетки врагов за последние CHASE_WINDOW тиков (см. evasive). */
    private val ourCentroidHist = ArrayDeque<Int>()
    private val enemyCellHist = HashMap<String, ArrayDeque<Int>>()
    /** Кто сейчас идёт к авангарду (гистерезис сбора, см. rallyTo). */
    private val rallyingIds = HashSet<String>()
    private var huntingThreat = false
    /** ДОБИТЬ по перевесу (не по контакту) — только к нему применяется гистерезис PUSH_RELEASE_RATIO. */
    private var pushing = false
    /** Точка отхода — одна на весь отход (см. retreatPoint). */
    private var retreatTarget: Position? = null
    /** Кто на прошлом тике шёл на личную цель (engage): такого не ждут по сплочению. */
    private val engagingIds = HashSet<String>()
    private val holdSince = HashMap<String, Int>()
    private val impatientIds = HashSet<String>()
    private var evadeTarget: Position? = null
    private var evadeEvaluatedAt = -100
    private val escapeFlows = HashMap<Int, IntArray>()
    private val escapeTheirs = HashMap<Int, Int>()
    private val escapeNearest = HashMap<Int, Int>()   // клетка врага, ближайшего к точке
    /** Точка, которую покинули (стояли, счёт места ниже EVADE_SAFE): не цель, пока не прибыли в другую — иначе маятник:
     *  через два шага от неё она уже «не здесь», её счёт (6) выше счёта дома (4), армия возвращается, снова «здесь» —
     *  три качания за 13 тиков съели восемь тиков запаса при погоне на равной скорости (стенд m11 sleeper). */
    private var evadeLeft: Position? = null
    private var escapeAt = -100
    /** Дистанция центра боевых врагов до нашего за последние тики — темп сближения для запаса выхода. */
    private val enemyDistHist = ArrayDeque<Int>()
    private var approachRate = 0.0
    private var unflaggedRushNow = false                  // бросок безфлаговой армии на нас (см. EVADE_EQUAL_RATIO)
    private var fightImminentNow = false                  // сомкнутая армия врага идёт на нас, с флагом или без (см. captureAllowed)
    private var noFireTicks = 0                           // тиков подряд враг с боем рядом и не снял с нас ни хита (см. USE_INTERCEPT)
    private var enemyNotFightingNow = false               // фермер: noFireTicks ≥ STALL_TICKS (см. USE_INTERCEPT)
    private val detachedIds = HashSet<String>()           // отряды: вооружённые, зачисленные в бегуны (см. USE_DETACH)
    private var lastDistanceKeptTick = -1000              // последний тик, когда погоня не сближала (см. USE_DETACH, v57)
    private val enemyCentHist = ArrayDeque<Int>()         // клетка центра его армии по тикам погони (рядом с armyDistHist)
    private var lastHurtTick = 0                          // последний тик, когда враг снял с нас хиты (см. farmer в runArmy)
    private var lastReachTick = -1                        // последний тик с его вооружённым в ENGAGE_RANGE от наших
    private var firstReachTick = -1                       // первый такой тик (см. USE_DETACH, v68: тишина считается от него)
    private var interceptFlagId: String? = null           // флаг, который фермер обязан взять следующим (см. USE_INTERCEPT)
    private var lastOurHits = -1                          // сумма хитов армии на прошлом тике (для noFireTicks)
    /** Тик, с которого строй ждёт готовности (см. FORM_PATIENCE); -1 — не ждёт. */
    private var formWaitSince = -1
    private val aggressiveIds = HashSet<String>()
    private val lastHits = HashMap<String, Int>()
    private val lastCell = HashMap<String, Int>()
    private val ghostLogged = HashMap<String, Int>()
    private class Shooter(val cell: Int, val ranged: Double, val melee: Double)
    private var prevShooters: List<Shooter> = emptyList()

    /** id захватчика -> id флага (липкое назначение). */
    private val runnerFlag = HashMap<String, String>()

    // ---------- счёт ----------
    private var ourScore = 0.0
    private var enemyScore = 0.0
    private var ourRate = 0
    private var enemyRate = 0
    /** По прогнозу (счёт + темп × остаток) мы проигрываем: очки важнее силы (см. captureAllowed). */
    private var behindOnScore = false
    /** Сколько тиков подряд отстаём по прогнозу (см. BEHIND_PATIENCE). */
    private var behindTicks = 0
    private val lastFlagOwner = HashMap<String, Int>()
    private var lastEffectsKey = ""
    private var lastBodiesKey = ""

    // ---------- кэши на тик ----------
    private val flowCache = HashMap<Int, IntArray>()
    private val flowCacheTick = HashMap<Int, Int>()   // тик расчёта поля (см. FLOW_TTL)
    private var flowSig = 0                            // подпись препятствий, при которой считан кэш
    /** Срок жизни поля к неподвижной цели (флаг, дом, угол): препятствия поля — стены, чужие рампарты, спавны,
     *  неподвижные крипы и чужие флаги — меняются редко, а считались поля каждый тик: 21–24 BFS в тик в гуще боя
     *  (семь флагов для выбора цели, девять точек выхода, цели крипов) — и три живых таймаута (матчи 16–18). Поле к
     *  цели-крипу (см. NEAR_FLOW) живёт один тик; смена подписи препятствий сбрасывает весь кэш. */
    private const val FLOW_TTL = 5
    /** Бюджет полных полей в тик (поле «вблизи» — четверть): сверх него устаревшее поле отдаётся как есть, а НОВАЯ
     *  цель получает ограниченное поле (см. NEAR_FLOW) с пометкой «устарело» — полное досчитается следующим тиком в
     *  пределах бюджета. Без этого начало боя (клетки врагов для броска и добычи, точки уклонения, флаги, вычищенные
     *  из кэша за время боя) давало 16–17 полных полей одним тиком (стенд, счётчик bfs). */
    private const val BFS_BUDGET = 8.0
    private const val FLOW_KEEP = 60   // тиков без обращения — запись кэша вычищается (иначе рост на клетках целей)
    private var bfsCost = 0.0
    private var bfsMaxCost = 0.0
    private var bfsThisTick = 0
    private var bfsMaxTick = 0
    /** Предел стоимости пути для поля «вблизи» (см. DistanceMap.flowFieldTo): цели-крипы — лекарь, раненый, бросок,
     *  добыча — в нескольких клетках; крип за пределом получает полное поле. */
    private const val NEAR_FLOW = 24

    // ---------- модель ----------

    /** Флаг очков в этом тике: владелец, тип дебаффа, очки, кто стоит на клетке и чья охрана рядом. */
    private class FlagInfo(val flag: ScoreFlag, val mine: Boolean?, val type: String, val score: Int, val occupant: Creep?, val guards: List<Creep>) {
        val id: String get() = flag.id
        val pos: Position get() = flag
        val ours: Boolean get() = mine == true
        val theirs: Boolean get() = mine == false
        /** Очки в тик, которые даёт захват: чужой флаг — двойной размен (нам плюс, врагу минус). */
        val swing: Double get() = if (theirs) 2.0 * score else score.toDouble()
    }

    private class Ctx(
        val home: Position,
        val enemyHome: Position,
        val myCreeps: List<Creep>,
        val active: List<Creep>,
        val army: List<Creep>,      // с оружием или лечением
        val runners: List<Creep>,   // безоружные и без лечения: захватчики
        val enemyCreeps: List<Creep>,
        val combatEnemies: List<Creep>,
        val blocked: List<Position>,
        /** Опасность (без флагов) — основа для матриц пути. */
        val rawDanger: CostMatrix,
        /** Опасность + НЕ НАШИ флаги как стены: путь без назначения на флаг не ступает. */
        val dangerMatrix: CostMatrix,
        val flags: List<FlagInfo>,
        /** Клетки не наших флагов (x*100+y): захват — только назначенным, см. flagBlocked. */
        val flagCells: Set<Int>,
        val flagBlocked: List<Position>,
        /** Вся боевая армия врага не сделала ни шага PASSIVE_TICKS тиков (порог захвата один, см. captureAllowed). */
        val passiveEnemy: Boolean,
        val ourCentroid: Position,
        val enemyCentroid: Position?,
    )

    fun tick() {
        bfsMaxTick = maxOf(bfsMaxTick, bfsThisTick)
        bfsMaxCost = maxOf(bfsMaxCost, bfsCost)
        bfsThisTick = 0
        bfsCost = 0.0
        val nowT = getTicks()
        val dead = flowCacheTick.filterValues { nowT - it > FLOW_KEEP }.keys.toList()
        for (k in dead) { flowCache.remove(k); flowCacheTick.remove(k) }
        avoidCellsCache = null

        val myCreeps = getObjectsByPrototype(Creep::class).filter { it.my && it.exists }
        val enemyCreeps = getObjectsByPrototype(Creep::class).filter { !it.my && it.exists && !it.spawning }
        val active = myCreeps.filter { !it.spawning }
        val combatEnemies = enemyCreeps.filter { val p = InfluenceMap.profileOf(it); p.melee + p.ranged + p.heal > 0.0 }

        // дома сторон — стартовые центры армий: спавнов на карте нет, половины и пост считаются от них
        if (homePos == null && active.isNotEmpty()) homePos = centroidOf(active)
        if (enemyHomePos == null && enemyCreeps.isNotEmpty()) enemyHomePos = centroidOf(enemyCreeps)
        val home = homePos ?: centroidOf(active) ?: InfluenceMap.cell(50, 50)
        val enemyHome = enemyHomePos ?: InfluenceMap.cell(99 - home.x, 99 - home.y)

        val flags = collectFlags(myCreeps, enemyCreeps, combatEnemies)
        applyEffects(flags, myCreeps, enemyCreeps)
        accountScore(flags)

        if (!greeted) {
            greeted = true
            probe(flags, myCreeps, enemyCreeps, home, enemyHome)
        }
        // дамп карты — четырьмя частями по 25 строк на тиках 3–6 (см. logMap)
        if (DEBUG_MAP && mapMarks == null) captureMapMarks(flags, myCreeps, enemyCreeps)
        if (DEBUG_MAP && getTicks() in 3..6) logMap((getTicks() - 3) * 25)
        logBodies(myCreeps, enemyCreeps)

        // раненый (см. wounded): боец, потерявший всё оружие, остаётся в армии, пока жив хоть один ходячий лекарь —
        // лечение возвращает части (движок: части живы по сумме хитов, лечение идёт с хвоста тела: в матче 8 melee_1
        // из M5 с 416 хитами стал M8A8 к 199-му тику у одного лекаря); прежде он уходил «бегуном» за флагами и гиб
        val healersAlive = active.any { !hasWeapon(it) && hasHeal(it) && canMove(it) }
        fun wounded(c: Creep) = USE_WOUNDED && healersAlive && !hasWeapon(c) && !hasHeal(c) && c.body.any { it.type == ATTACK || it.type == RANGED_ATTACK || it.type == HEAL }
        detachedIds.retainAll { id -> active.any { it.id == id && hasWeapon(it) && canMove(it) } }
        val army = active.filter { (hasWeapon(it) || hasHeal(it) || wounded(it)) && it.id !in detachedIds }
        val runners = active.filter { (!hasWeapon(it) && !hasHeal(it) && !wounded(it)) || it.id in detachedIds }
        val immobile = active.filter { !canMove(it) }

        val walls = getObjectsByPrototype(StructureWall::class).filter { it.exists }
        val ramparts = getObjectsByPrototype(StructureRampart::class).filter { it.exists }
        val spawns = getObjectsByPrototype(StructureSpawn::class).filter { it.exists }
        val blocked: List<Position> = walls + ramparts.filter { it.my != true } + spawns + immobile
        val blockedForEnemy: List<Position> = walls + ramparts.filter { it.my != false } + spawns

        InfluenceMap.setProtectedCells(ramparts.filter { it.my == true }.mapTo(HashSet()) { it.x * 100 + it.y })
        InfluenceMap.setEnemyBlocked(blockedForEnemy.mapTo(HashSet()) { it.x * 100 + it.y })
        val rawDanger = InfluenceMap.dangerCostMatrix(enemyCreeps, blocked)
        // флаг берётся тем, кто на него ВСТАЛ, — и любой шаг армии через чужой флаг был захватом: в матче 3 армия
        // на марше взяла D5 и второй A3 (occupant=none в журнале) и дралась при A×0.6 D×1.1 против врага, с
        // которого сама же сняла дебаффы. Не наш флаг — стена для всех, кроме назначенного на него
        val flagCells = flags.filter { !it.ours }.mapTo(HashSet()) { it.pos.x * 100 + it.pos.y }
        val flagBlocked = flags.filter { !it.ours }.map { it.pos }
        val blockSig = blocked.sumOf { it.x * 100 + it.y + 1 } * 31 + flagBlocked.sumOf { it.x * 100 + it.y + 1 }
        // смена препятствий: поля не удаляются, а помечаются устаревшими — сверх бюджета (см. BFS_BUDGET) идут как есть
        if (blockSig != flowSig) { for (k in flowCacheTick.keys.toList()) flowCacheTick[k] = -1000; flowSig = blockSig }
        val dangerMatrix = rawDanger.clone()
        for (c in flagCells) dangerMatrix.set(c / 100, c % 100, 255)
        val passiveEnemy = combatEnemies.isNotEmpty() && combatEnemies.all { stationaryFor(it) >= PASSIVE_TICKS }

        DistanceMap.syncWalls(walls.size)
        DistanceMap.ensureBuilt(home, enemyHome)

        val ourCentroid = centroidOf(army.ifEmpty { active }) ?: home
        val enemyCentroid = centroidOf(combatEnemies.ifEmpty { enemyCreeps })
        val ctx = Ctx(home, enemyHome, myCreeps, active, army, runners, enemyCreeps, combatEnemies, blocked, rawDanger, dangerMatrix, flags, flagCells, flagBlocked, passiveEnemy, ourCentroid, enemyCentroid)

        enemyArrivalTicks(ctx)
        plannedCaptures.clear()
        // доктрина «первый флаг — их» (см. EVADE_EQUAL_RATIO) — до бегунов: их захват идёт тем же гейтом
        // сомкнутая армия (см. MASS_RANGE): россыпь по флагам и клубок фермера — не бросок, хотя их части тоже идут к нам
        val armedNow = ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }
        val enemyMassed = armedNow.size >= 6 && centroidOf(armedNow)?.let { c -> armedNow.count { getRange(it, c) <= MASS_RANGE } * 3 >= armedNow.size * 2 } == true
        // с гистерезисом: темп сближения ходит вокруг порога (колонна на марше то растягивается шире MASS_RANGE, то
        // замедляется), и без него уклонение сменялось стоянием каждые десять-тридцать тиков, пока враг шёл — матч 32:
        // EVADE 57, HOLD 69 при approach=84, EVADE 94, HOLD 109 при 42, EVADE 117, HOLD 122, контакт на 127-м и 12:0.
        // Начатый бросок кончается, когда враг взял флаг, замер, разошёлся или ушёл дальше EVADE_RANGE и не приближается
        val noEnemyFlag = ctx.flags.none { it.theirs }
        val rushSignal = !ctx.passiveEnemy && noEnemyFlag && approachRate >= APPROACH_RUSH && enemyMassed
        val rushHold = unflaggedRushNow && !ctx.passiveEnemy && noEnemyFlag && armedNow.isNotEmpty() &&
            (approachRate > 0.0 || armedNow.any { getRange(it, ctx.ourCentroid) <= EVADE_RANGE })
        unflaggedRushNow = rushSignal || rushHold
        // бой близко — для ЗАХВАТОВ флаг врага не в счёт: «безфлаговый» бросок кончился на 39-м тике, когда его армия по пути
        // взяла D5, и скаут взял R3 на 42-м (матч 47, пятый бой с けろびー подряд с R×0.8); уклонение по-прежнему только от
        // безфлагового (флагованный слабее — с ним дерёмся), а дебафф перед боем не берём ни от кого
        fightImminentNow = unflaggedRushNow || (!ctx.passiveEnemy && approachRate >= APPROACH_RUSH && enemyMassed)
        // враг рядом, но не воюет: армия с боем в досягаемости броска, и наши хиты не падали STALL_TICKS тиков подряд — фермер
        // (けろびー v5, матчи 51 и 57: шесть флагов к 82-му, 1400 тиков рядом без единого выстрела, 10804:22779 при 12 наших
        // против его 4 к концу); гейты боя в captureAllowed («в контакте», «бой близко») к нему не применяются, паритет —
        // применяется. Атакующий стреляет через несколько тиков после контакта, и счётчик не доходит до STALL_TICKS
        // по ВСЕМ нашим (v56): сумма по армии падала на хиты только что отряжённых в бегуны, «нас ударили» — и отряд распускался
        // на следующий же тик (стенд m28 farm+weak: 6 detached на 100-м, 0 на 101-м с hurt=0, трижды за матч)
        val ourHitsSum = ctx.myCreeps.sumOf { it.hits }
        val hurt = lastOurHits >= 0 && ourHitsSum < lastOurHits
        lastOurHits = ourHitsSum
        val enemyNear = armedNow.any { e -> ctx.army.any { getRange(e, it) <= ENGAGE_RANGE + RANGED_RANGE } }
        noFireTicks = if (enemyNear && !hurt) noFireTicks + 1 else 0
        // фермер — не только «не стреляет», но и «держится дальше броска»: стоящий в 3–6 экран стенда тоже не стрелял, пока
        // мы стояли на своём флаге, и перехват превратил бой, который v38 выигрывала на 439-м, в стояние до конца матча
        // (m31 screen: 16000/16000 у обоих 800 тиков, проигрыш по очкам); враг в ENGAGE_RANGE — это бой, не перехват
        val enemyWithinReach = armedNow.any { e -> ctx.army.any { getRange(e, it) <= ENGAGE_RANGE } }
        enemyNotFightingNow = USE_INTERCEPT && noFireTicks >= STALL_TICKS && !enemyWithinReach
        if (hurt) lastHurtTick = getTicks()
        if (enemyWithinReach) { lastReachTick = getTicks(); if (firstReachTick < 0) firstReachTick = getTicks() }
        runRunners(ctx)
        runArmy(ctx)

        TrafficManager.resolve(active.filter { canMove(it) }, myCreeps + enemyCreeps)
        InfluenceMap.pruneStances(myCreeps.mapTo(HashSet()) { it.id })
        // кто из врагов сдвинулся за тик — для признака «стоит на месте» (см. stationary)
        for (e in enemyCreeps) {
            val cell = e.x * 100 + e.y
            if (enemyPrevCell[e.id] != cell) enemyLastMove[e.id] = getTicks()
        }
        enemyLastMove.keys.retainAll { id -> enemyCreeps.any { it.id == id } }
        enemyPrevCell.clear()
        for (e in enemyCreeps) enemyPrevCell[e.id] = e.x * 100 + e.y
        // история движения — для ловимости (см. evasive)
        val armedCentroid = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army }) ?: ourCentroid
        ourCentroidHist.addLast(armedCentroid.x * 100 + armedCentroid.y)
        while (ourCentroidHist.size > CHASE_WINDOW) ourCentroidHist.removeFirst()
        for (e in enemyCreeps) {
            val h = enemyCellHist.getOrPut(e.id) { ArrayDeque() }
            h.addLast(e.x * 100 + e.y)
            while (h.size > CHASE_WINDOW) h.removeFirst()
        }
        enemyCellHist.keys.retainAll { id -> enemyCreeps.any { it.id == id } }
        if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
            println("bfs t=${getTicks()} max=$bfsMaxTick cost=$bfsMaxCost")
            bfsMaxTick = 0
            bfsMaxCost = 0.0
        }
        if (DEBUG_LOG) logStuck(active, enemyCreeps)
        if (DEBUG_VISUALS) InfluenceMap.drawDebug(army, myCreeps, enemyCreeps)

        if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
            val ours = ourPowerOf(army, combatEnemies)
            val theirs = enemyPowerOf(combatEnemies, army)
            println(
                "t=${getTicks()} army=${army.size} runners=${runners.size}(${detachedIds.size} detached) enemies=${enemyCreeps.size}/${combatEnemies.size} " +
                "reach=${army.count { hasWeapon(it) && hasRanged(it) && combatEnemies.any { e -> getRange(it, e) <= RANGED_RANGE } }}/${army.count { hasWeapon(it) && hasRanged(it) }} " +
                "conc=$concSum/$concTicks " +
                    "score=${ourScore.toInt()}/${enemyScore.toInt()} rate=$ourRate/$enemyRate behind=$behindOnScore passive=$passiveEnemy flags=${flagsSummary(flags)} " +
                    "posture=$posture obj=${objectiveFlagId?.let { id -> flags.firstOrNull { it.id == id }?.let { "(${it.pos.x},${it.pos.y})" } } ?: "-"} hunt=$huntingThreat rush=$unflaggedRushNow " +
                    "our=${ours.toInt()} enemy=${theirs.toInt()} wounded=${army.count { !hasWeapon(it) && !hasHeal(it) }} hits=${army.sumOf { it.hits }}/${army.sumOf { it.hitsMax }} enemyHits=${combatEnemies.sumOf { it.hits }}/${combatEnemies.sumOf { it.hitsMax }} " +
                    "centroid=(${ourCentroid.x},${ourCentroid.y}) enemyCentroid=${enemyCentroid?.let { "(${it.x},${it.y})" } ?: "-"}"
            )
            concSum = 0; concTicks = 0
            if (getTicks() % (LOG_EVERY * 10) == 0) println(TrafficManager.audit())
        }
    }

    // ==================== зонд ====================

    /** Число из константы арены (внешнее объявление может оказаться undefined — тогда запасное). */
    private fun num(v: dynamic, fallback: Double): Double = if (jsTypeOf(v) == "number") v.unsafeCast<Double>() else fallback

    private fun probe(flags: List<FlagInfo>, myCreeps: List<Creep>, enemyCreeps: List<Creep>, home: Position, enemyHome: Position) {
        println(
            "hello season4 pain-and-gain $BOT_VERSION: ${arenaInfo.season} - ${arenaInfo.name} level=${arenaInfo.level} " +
                "ticksLimit=${arenaInfo.ticksLimit} cpu=${arenaInfo.cpuTimeLimit}/${arenaInfo.cpuTimeLimitFirstTick}"
        )
        // подпись сборки: по ней видно, какая версия играет, даже если строку версии забыли поднять
        println(
            "tuning: pushX=$PUSH_EXCHANGE parity=$PARITY_FLOOR/$CAPTURE_FLOOR/$PARITY_FLOOR_STALLED push=$PUSH_RATIO/$PUSH_RATIO_BEHIND " +
                "stall=$STALL_TICKS/$STALL_PICKET/$STALL_DAMAGE/$STALL_COOLDOWN march=$MARCH_STALL_TICKS rush=$APPROACH_RUSH/$EVADE_EQUAL_RATIO " +
                "mass=$MASS_RANGE leash=$LEASH_RANGE meleeHold=$MELEE_HOLD_RANGE press=$PRESS_RANGE/$PRESS_PACK/$PRESS_PATIENCE/$PRESS_CLOSING/$PRESS_GIVEUP healer=$HEALER_VALUE keep=$KEEP_RANGE/$KEEP_PICKET/$KEEP_RELEASE"
        )
        println(
            "pain-and-gain: TICKS_LIMIT=${num(TICKS_LIMIT.asDynamic(), -1.0)} MAX_SCORE_PER_TICK=${num(MAX_SCORE_PER_TICK.asDynamic(), -1.0)} " +
                "FLAG_TYPES=${try { JSON.stringify(FLAG_TYPES) } catch (t: Throwable) { "?" }} " +
                "EFF: attack=$EFF_ATTACK_MODIFIER ranged=$EFF_RANGED_ATTACK_MODIFIER heal=$EFF_HEAL_MODIFIER taken=$EFF_DAMAGE_TAKEN_MODIFIER " +
                "power: R=$RANGED_ATTACK_POWER A=$ATTACK_POWER H=$HEAL_POWER/$RANGED_HEAL_POWER"
        )
        println("flags: " + flags.joinToString(" ") { "(${it.pos.x},${it.pos.y})${typeChar(it.type)}${it.score}my=${it.mine}" })
        println("home=(${home.x},${home.y}) enemyHome=(${enemyHome.x},${enemyHome.y})")
        println("my creeps (${myCreeps.size}): " + myCreeps.joinToString(" ") { "${it.id}(${it.x},${it.y})${bodySummary(it)}${if (it.spawning) "S" else ""}" })
        println("enemy creeps (${enemyCreeps.size}): " + enemyCreeps.joinToString(" ") { "${it.id}(${it.x},${it.y})${bodySummary(it)}" })
        val walls = getObjectsByPrototype(StructureWall::class).size
        val ramparts = getObjectsByPrototype(StructureRampart::class).size
        val spawns = getObjectsByPrototype(StructureSpawn::class).size
        println("structures: walls=$walls ramparts=$ramparts spawns=$spawns")
        // тела целиком (с порядком частей) — по ним видно, что выдано, и что умрёт первым
        for (c in myCreeps) println("body ${c.id}: " + c.body.joinToString("") { partChar(it.type).toString() })
        for (c in enemyCreeps) println("enemy body ${c.id}: " + c.body.joinToString("") { partChar(it.type).toString() })
    }

    private fun partChar(type: BodyPartType): Char = when (type) {
        TOUGH -> 'T'; MOVE -> 'M'; RANGED_ATTACK -> 'R'; ATTACK -> 'A'; HEAL -> 'H'; CARRY -> 'C'; WORK -> 'W'
    }

    private fun typeChar(type: String): Char = when (type) {
        EFF_ATTACK_MODIFIER -> 'A'
        EFF_RANGED_ATTACK_MODIFIER -> 'R'
        EFF_HEAL_MODIFIER -> 'H'
        EFF_DAMAGE_TAKEN_MODIFIER -> 'D'
        else -> '?'
    }

    private fun flagsSummary(flags: List<FlagInfo>): String =
        flags.joinToString(",") { "${typeChar(it.type)}${it.score}${if (it.ours) "+" else if (it.theirs) "-" else "0"}${if (it.occupant != null) (if (it.occupant.my) "s" else "e") else ""}${if (it.guards.isNotEmpty()) "g${it.guards.size}" else ""}" }

    /** Состав армий (живые части) — при каждом изменении: видно потери и покалеченных. */
    private fun logBodies(myCreeps: List<Creep>, enemyCreeps: List<Creep>) {
        if (!DEBUG_LOG) return
        val key = myCreeps.joinToString(",") { bodySummary(it) } + "|" + enemyCreeps.joinToString(",") { bodySummary(it) }
        if (key == lastBodiesKey) return
        lastBodiesKey = key
        println("armies t=${getTicks()}: ours(${myCreeps.size}) " + myCreeps.joinToString(" ") { "${bodySummary(it)}h=${it.hits}" } +
            " | enemy(${enemyCreeps.size}) " + enemyCreeps.joinToString(" ") { "(${it.x},${it.y})${bodySummary(it)}h=${it.hits}" })
    }

    // ==================== флаги и эффекты ====================

    private fun collectFlags(myCreeps: List<Creep>, enemyCreeps: List<Creep>, combatEnemies: List<Creep>): List<FlagInfo> {
        val result = ArrayList<FlagInfo>()
        val all = getObjectsByPrototype(ScoreFlag::class).filter { it.exists }
        for (f in all) {
            val occupant = (myCreeps + enemyCreeps).firstOrNull { !it.spawning && it.x == f.x && it.y == f.y }
            val guards = combatEnemies.filter { getRange(it, f) <= FLAG_GUARD_RANGE }
            result.add(FlagInfo(f, f.my, f.effectType, f.scorePerTick, occupant, guards))
        }
        // журнал захватов: смена владельца и кто стоит на клетке — проверка механики «встал — захватил»
        for (fi in result) {
            val owner = if (fi.ours) 1 else if (fi.theirs) -1 else 0
            val prev = lastFlagOwner[fi.id]
            if (prev != null && prev != owner && DEBUG_LOG) {
                println("flag t=${getTicks()}: (${fi.pos.x},${fi.pos.y})${typeChar(fi.type)}${fi.score} owner ${ownerName(prev)} -> ${ownerName(owner)} occupant=${fi.occupant?.let { "${if (it.my) "my" else "enemy"} ${bodySummary(it)}" } ?: "none"}")
            }
            lastFlagOwner[fi.id] = owner
        }
        return result
    }

    private fun ownerName(code: Int) = when (code) { 1 -> "us"; -1 -> "enemy"; else -> "none" }

    /** Множитель стека по таблице арены: удар/стрельба 0.8 → 0.6, лечение 0.75 → 0.5, входящий 1.1 (флаг один);
     *  дальше — тем же шагом (в матче сверяется с effects крипов). */
    private fun stackMul(type: String, count: Int): Double {
        if (count <= 0) return 1.0
        return when (type) {
            EFF_ATTACK_MODIFIER, EFF_RANGED_ATTACK_MODIFIER -> 1.0 - 0.2 * count
            EFF_HEAL_MODIFIER -> 1.0 - 0.25 * count
            EFF_DAMAGE_TAKEN_MODIFIER -> 1.0 + 0.1 * count
            else -> 1.0
        }.coerceAtLeast(0.0)
    }

    private fun sideModsOf(flags: List<FlagInfo>, mine: Boolean): InfluenceMap.SideMods {
        fun n(type: String) = flags.count { it.mine == mine && it.type == type }
        return InfluenceMap.SideMods(
            attack = stackMul(EFF_ATTACK_MODIFIER, n(EFF_ATTACK_MODIFIER)),
            ranged = stackMul(EFF_RANGED_ATTACK_MODIFIER, n(EFF_RANGED_ATTACK_MODIFIER)),
            heal = stackMul(EFF_HEAL_MODIFIER, n(EFF_HEAL_MODIFIER)),
            taken = stackMul(EFF_DAMAGE_TAKEN_MODIFIER, n(EFF_DAMAGE_TAKEN_MODIFIER)),
        )
    }

    /** Эффекты сторон: по массиву effects крипов, если API его отдаёт, иначе по подсчёту флагов (таблица
     *  арены). Печатает то и другое при изменении — в матче они обязаны совпасть. */
    private fun applyEffects(flags: List<FlagInfo>, myCreeps: List<Creep>, enemyCreeps: List<Creep>) {
        val ours = sideModsOf(flags, true)
        val theirs = sideModsOf(flags, false)
        InfluenceMap.setSideMods(ours, theirs)
        val sample = myCreeps.firstOrNull { InfluenceMap.hasEffectsApi(it) }
        InfluenceMap.setOurTaken(if (sample != null) InfluenceMap.takenOf(sample) else ours.taken)
        if (DEBUG_LOG) {
            val enemySample = enemyCreeps.firstOrNull { InfluenceMap.hasEffectsApi(it) }
            val key = "$ours|$theirs|${sample?.let { JSON.stringify(it.effects) }}|${enemySample?.let { JSON.stringify(it.effects) }}"
            if (key != lastEffectsKey) {
                lastEffectsKey = key
                println("effects t=${getTicks()}: byFlags ours=[$ours] theirs=[$theirs] api ours=${sample?.let { JSON.stringify(it.effects) } ?: "n/a"} theirs=${enemySample?.let { JSON.stringify(it.effects) } ?: "n/a"}")
            }
        }
    }

    private fun accountScore(flags: List<FlagInfo>) {
        val cap = num(MAX_SCORE_PER_TICK.asDynamic(), Double.MAX_VALUE)
        ourRate = minOf(cap, flags.filter { it.ours }.sumOf { it.score }.toDouble()).toInt()
        enemyRate = minOf(cap, flags.filter { it.theirs }.sumOf { it.score }.toDouble()).toInt()
        ourScore += ourRate
        enemyScore += enemyRate
        val remaining = maxOf(0, arenaInfo.ticksLimit - getTicks())
        behindOnScore = ourScore + ourRate * remaining < enemyScore + enemyRate * remaining
        behindTicks = if (behindOnScore) behindTicks + 1 else 0
        if (DEBUG_LOG && getTicks() % 100 == 0) println("score t=${getTicks()}: our=${ourScore.toInt()} (+$ourRate/t) enemy=${enemyScore.toInt()} (+$enemyRate/t) behind=$behindOnScore lead=${(ourScore - enemyScore).toInt()} maxSwing=${(cap * remaining).toInt()}")
    }

    /**
     * Брать ли этот (не наш) флаг сейчас. Свой — да. Врага в поле нет — да. Иначе — по паритету (см. PARITY_FLOOR):
     * армия С ЭТИМ дебаффом не слабее армии врага (CAPTURE_FLOOR), а пока отрыва нет — не меньше PARITY_FLOOR их
     * мощи:
     * маргинальная цена по Ланчестеру с эффектами ОБЕИХ сторон — у флага стрельбы дешевеет только стрелковая
     * часть урона, у флага лечения растёт чистый урон врага по нам, у флага уязвимости тают хиты, а чужой флаг
     * ещё и возвращает врагу то, что снимал с него. Отставание по счёту флагов больше не открывает: оно
     * значит, что враг держит больше и слабее — ответ ему бой (PUSH_RATIO_BEHIND), а не ещё один дебафф
     * (матч 3: «отстаём» на 2 очка при 6:10 разрешило всё подряд). Исключение — последние LAST_CALL_TICKS:
     * бой уже не успеет, и очки решают.
     */
    private fun captureAllowed(ctx: Ctx, f: FlagInfo): Boolean {
        if (f.ours) return true
        if (ctx.combatEnemies.isEmpty()) return true
        // последний зов и при РАВНОМ счёте: ничья 0:0 после уклонения (см. EVADE_EQUAL_RATIO) отдана не будет
        if ((behindOnScore || ourScore <= enemyScore) && arenaInfo.ticksLimit - getTicks() <= LAST_CALL_TICKS) return true
        // во время броска безфлаговой армии (см. unflaggedRushNow — тот же сигнал, что уводит армию в уклонение) флаг не берёт
        // НИКТО: бой через двадцать тиков, и дебафф ложится на него. Скаут брал R3 на 42–43-м тике во всех четырёх боях с
        // けろびー (матчи 38, 43, 44, 45) — −20 % стрелкам в решающем размене, — проходя порог паритета с запасом три очка мощи
        // (3967 против 3964: модель мощи считает мили полными, а их обезоруживают за первые двадцать тиков). Три очка в тик
        // за тридцать тиков против пятой части огня на весь бой
        // флаг перехвата (см. USE_INTERCEPT) открыт и в контакте с фермером, и при «бое близко»; остальные — нет
        val intercept = enemyNotFightingNow && f.id == interceptFlagId
        if (fightImminentNow && !intercept) return false
        // в контакте флаги не берём, пока есть кому драться: дебафф ложится на идущий бой (матч 9: скаут взял R3 на 125-м
        // тике — −20% стрелкам в решающем размене ради трёх очков в тик); без стрелков защищать нечего, а очки — всё,
        // что осталось (стенд m4 sleeper: запрет при охоте за обломками отдал матч по очкам)
        // при бесплодной охоте (см. STALL_TICKS) контакт мнимый — висящие в трёх-шести клетках крипы россыпи мигали
        // контактом, и цель-флаг пропадала через тик после назначения (стенд m19 spread)
        if (!stalledNow && !intercept && ctx.army.any { fullSpeed(it) && hasWeapon(it) } && inContact(ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }, ctx.army)) return false
        // паритет (см. PARITY_FLOOR): не впереди или отрыв не растёт — флаг, оставляющий не меньше PARITY_FLOOR их
        // мощи; впереди с растущим отрывом — только не слабее
        val (ours, theirs) = powerAfter(ctx, f)
        val needed = ourScore <= enemyScore || ourRate <= enemyRate
        // неподвижный враг — тоже армия: «пассивный» порог 0.95 пустил третий флаг против спящего, тот проснулся, и бой
        // при 0.96 был проигран (стенд m6 sleeper); порог один
        // проигранная гонка с тем, кто ни разу не ударил (v63, см. PARITY_FLOOR_LOST)
        val quiet = lastHurtTick == 0 || getTicks() - lastHurtTick >= FARMER_QUIET   // тишина (v65, см. FARMER_QUIET)
        val lostRace = USE_LOST_RACE_CAPTURE && stalemateNow && quiet && ourScore <= enemyScore && ourRate <= enemyRate
        val floor = if (lostRace) PARITY_FLOOR_LOST else if (stalledNow) PARITY_FLOOR_STALLED else if (needed) PARITY_FLOOR else CAPTURE_FLOOR
        return ours >= theirs * floor
    }

    /** Флаги, на которые наши крипы уже шагают в ЭТОТ тик (см. planCapture): два захвата одним тиком — D5 армией и H4
     *  скаутом — каждый в отдельности проходил порог паритета, вместе дали 0.93 и разгром 12:0 (стенд m9 hunter, t=98). */
    private val plannedCaptures = HashSet<String>()
    private val rotatingIds = HashSet<String>()   // бойцы в ротации (см. ROTATE_OUT)
    private val NO_FLOW = IntArray(10000) { -1 }
    private val keeperIds = HashMap<String, String>()   // хранитель флага → id флага (см. KEEP_RANGE)
    private val enemyHitsHist = ArrayDeque<Int>()         // сумма хитов врага за STALL_TICKS тиков (чистый урон)
    private val marchHist = ArrayDeque<Int>()             // клетка центра вооружённой массы за MARCH_STALL_TICKS тиков
    private val armyDistHist = ArrayDeque<Int>()          // дистанция между центрами армий за CHASE_WINDOW тиков (см. третья сетка)
    private val ourHitsHist = ArrayDeque<Int>()           // и наша: бьют только нас — это бой, не простой
    private var preyNearTicks = 0                         // тиков подряд с пикетом (см. STALL_PICKET) в досягаемости
    private var stallUntil = 0
    private var stalledNow = false                        // бесплодная охота (см. STALL_TICKS) — снимает и запрет захвата в контакте
    private var stalemateNow = false                      // отставание с меньшим темпом дольше BEHIND_PATIENCE (см. PARITY_FLOOR_LOST)
    private var standoffTicks = 0                         // тиков подряд стоящей линии врага (см. PRESS_PATIENCE)
    private var pressing = false                          // прижим включён (см. USE_PRESS)
    private val meleeDistHist = ArrayDeque<Int>()         // дистанция их мили до наших вооружённых за окно терпения (см. PRESS_CLOSING)
    private val centreDistHist = ArrayDeque<Int>()        // дистанция между центрами вооружённых армий за то же окно (см. standingNow)
    private val pressChase = HashMap<String, ArrayDeque<Int>>()  // дистанция от наших мили до цели прижима по тикам (см. PRESS_GIVEUP)
    private val lastArmedRange = HashMap<String, Int>()   // враг → дистанция до ближайшего нашего боеспособного тик назад (см. threatOf)
    private val pressGiveUp = HashMap<String, Int>()      // цель прижима, от которой отказались, → тик, до которого
    private val SLOT_ORDER = intArrayOf(0, -1, 1, -2, 2, -3, 3, -4, 4)

    private fun planCapture(ctx: Ctx, step: Position?) {
        if (step == null) return
        ctx.flags.firstOrNull { !it.ours && it.pos.x == step.x && it.pos.y == step.y }?.let { plannedCaptures.add(it.id) }
    }

    /** Мощь сторон, если мы возьмём ещё этот флаг (и те, на которые уже шагаем в этот тик): наша — с их дебаффами;
     *  вражья — без них, если флаги были его. */
    private fun powerAfter(ctx: Ctx, f: FlagInfo): Pair<Double, Double> {
        val taking = HashSet(plannedCaptures); taking.add(f.id)
        fun mods(mine: Boolean): HypoMods {
            fun k(type: String): Double {
                val now = ctx.flags.count { it.mine == mine && it.type == type }
                val after = ctx.flags.count { it.type == type && (if (mine) (it.ours || it.id in taking) else (it.theirs && it.id !in taking)) }
                return stackMul(type, after) / stackMul(type, now).coerceAtLeast(0.01)
            }
            return HypoMods(ranged = k(EFF_RANGED_ATTACK_MODIFIER), melee = k(EFF_ATTACK_MODIFIER), heal = k(EFF_HEAL_MODIFIER), hits = 1.0 / k(EFF_DAMAGE_TAKEN_MODIFIER))
        }
        val ourMods = mods(true)
        val theirMods = mods(false)
        // наша СТОРОНА, не ядро (v59): паритет захвата — страховка от аннигиляции стороны, а отряженные в бегуны (см. USE_DETACH)
        // живы и вооружены. Ядро без пяти отряжённых стояло в паритете (2918 против 2954), захват был запрещён ВСЕМ, и четверо
        // отряжённых 800 тиков стояли POISED в клетке от свободных D5, A3, R3 и H4 — 3174:22931, двенадцатый проигрыш фермеру
        // (матч 139); до отряда, при 1,41, захваты были разрешены и скаутам
        val side = ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) }
        return powerOf(side, ctx.combatEnemies, ourMods, theirMods) to powerOf(ctx.combatEnemies, side, theirMods, ourMods)
    }

    /** Цена флага в силе — доля нашей мощи, которая останется после захвата (1 — бесплатно): флаг лечения
     *  для армии почти без лекарей дёшев, флаг уязвимости стоит всем; дорогие берутся последними. */
    private fun captureCost(ctx: Ctx, f: FlagInfo): Double {
        if (f.ours || ctx.combatEnemies.isEmpty()) return 1.0
        val now = ourPowerOf(ctx.army, ctx.combatEnemies)
        if (now <= 0.0) return 1.0
        return (powerAfter(ctx, f).first / now).coerceIn(0.0, 1.0)
    }

    // ==================== захватчики ====================

    /** Флаг, за которым стоит идти захватчику: не наш и без врага на клетке, или наш пустой (охрана клеткой). */
    private fun wantsRunner(f: FlagInfo): Boolean {
        val occ = f.occupant
        if (occ != null && !occ.my) return false
        return !f.ours || occ == null
    }

    private fun runRunners(ctx: Ctx) {
        val runners = ctx.runners
        if (runners.isEmpty()) { runnerFlag.clear(); return }
        runnerFlag.keys.retainAll { id -> runners.any { it.id == id } }
        val flagById = ctx.flags.associateBy { it.id }
        fun dbg(s: Creep, mode: String, f: FlagInfo?, step: Position? = null) {
            if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
                println("  r${s.id} (${s.x},${s.y}) ${bodySummary(s)} hits=${s.hits} $mode flag=${f?.let { "(${it.pos.x},${it.pos.y})${typeChar(it.type)}${it.score}my=${it.mine}" } ?: "-"} fatigue=${s.fatigue} step=${step?.let { "(${it.x},${it.y})" } ?: "stay"}${if (TrafficManager.isStuck(s.id)) " STUCK" else ""}")
            }
        }
        // назначение — глобальное жадное паросочетание по ценности (лучшая пара «захватчик-флаг» первой),
        // НЕ зависящее от порядка обхода: обход в порядке текущих назначений менял очерёдность от тика к
        // тику, два скаута по очереди отбирали друг у друга центральный флаг и полторы тысячи тиков
        // шагали туда-обратно на одной клетке, ни разу не выйдя за неё (матч 1). Взявший флаг идёт за
        // следующим НЕ НАШИМ; сидеть на своём — когда чужих свободных на всех не хватает
        class Cand(val runner: Creep, val flag: FlagInfo, val value: Double)
        val cands = ArrayList<Cand>()
        for (s in runners) {
            val currentId = runnerFlag[s.id]
            val armedRunner = hasWeapon(s)
            for (f in ctx.flags) {
                val occ = f.occupant
                // занято (чужим — ждём отряд; своим — тот и держит). Вооружённый бегун (отряд, см. USE_DETACH) идёт на флаг с
                // ОДИНОЧНЫМ врагом слабее себя — в матче 126 отряд стоял POISED в клетке от D5, пока на нём сидел его крип
                if (occ != null && occ.id != s.id) {
                    if (!armedRunner || occ.my) continue
                    val e = ctx.enemyCreeps.firstOrNull { it.x == f.pos.x && it.y == f.pos.y } ?: continue
                    if (ctx.enemyCreeps.any { it.id != e.id && getRange(it, f.pos) <= ENGAGE_RANGE }) continue
                    if (ourPowerOf(listOf(s), listOf(e)) <= enemyPowerOf(listOf(e), listOf(s))) continue
                }
                val flow = flowTo(ctx, f.pos)
                val ticks = pathTicks(s, flow, s.x * 100 + s.y)
                if (ticks >= Int.MAX_VALUE / 4) continue
                // стая у флага — охрана рядом И те, кто дойдёт до него раньше нас: скаут шёл к дальнему H4, пока
                // армия врага шла туда же, и вошёл в неё (матч 3, t=70–87); охраны в 11 клетках было мало.
                // Для вооружённого бегуна стая — только та, что сильнее его (v57)
                val pack = packAt(ctx, f.pos, flow, ticks)
                if (pack.isNotEmpty() && (!armedRunner || enemyPowerOf(pack, listOf(s)) >= ourPowerOf(listOf(s), pack))) continue
                // при охотнике (см. escapeFlows) флаг без выхода — карман: три безоружных крипа сидели на угловых флагах,
                // пока армия врага шла к ним, и были добиты по одному — последний на 545-м тике, аннигиляция при +5000
                // очков (матч 13)
                if (escapeFlows.isNotEmpty() && exitMargin(ctx, f.pos, ticks) < 0) continue
                // свой пустой флаг стоит половину — но СИДЯЩИЙ на нём закрывает клетку от чужих бегунов (матч 2:
                // центральный D5 забрал вражеский M1, пока армия уходила за соседним флагом, и вернуть его было
                // некому); чужой — двойной размен; флаг, который порог силы сейчас не разрешает, — пятую часть
                // (ждать у него можно, но сидеть на своём полезнее); дорогой по силе — позже дешёвого (см.
                // captureCost); текущий — с премией
                val value = (if (f.ours) 0.5 * f.score else f.swing) * captureCost(ctx, f) / (ticks + 5) *
                    (if (f.id == currentId) 1.25 else 1.0) * (if (!f.ours && !captureAllowed(ctx, f)) 0.2 else 1.0)
                cands.add(Cand(s, f, value))
            }
        }
        cands.sortByDescending { it.value }
        val assigned = HashSet<String>()
        val taken = HashSet<String>()
        for (c in cands) {
            if (c.runner.id in assigned || c.flag.id in taken) continue
            assigned.add(c.runner.id)
            taken.add(c.flag.id)
            runnerFlag[c.runner.id] = c.flag.id
        }
        for (s in runners) if (s.id !in assigned) runnerFlag.remove(s.id)

        for (s in runners) {
            val f = runnerFlag[s.id]?.let { flagById[it] }
            val onIt = f != null && s.x == f.pos.x && s.y == f.pos.y
            val nearby = ctx.combatEnemies.filter { getRange(s, it) <= RANGED_RANGE + 2 }
            val underFire = InfluenceMap.damageAt(s.x, s.y, ctx.combatEnemies) > 0.0
            // мили-бегун (отряд) рубит вплотную (v57): healAndShoot за бегунов только стреляет, удар мили выдаёт цикл армии
            if (hasMelee(s)) ctx.enemyCreeps.filter { getRange(s, it) <= 1 }.minByOrNull { it.hits }?.let { s.attack(it) }
            // захватчик без замены: от врага «с боем» ближе SCOUT_FLEE_TRIGGER — прочь (пустой MOVE ходит клетку за тик и
            // по болоту, где стрелок вязнет), даже с флага: флаг останется нашим, пока враг сам на него не встанет
            val threats = ctx.combatEnemies.filter { getRange(s, it) <= SCOUT_FLEE_TRIGGER && threatening(it, ctx.enemyCreeps) }
            if (canMove(s) && (underFire || threats.isNotEmpty())) {
                // поиск пути бегства может не дать шага (скаут в матче 3 «бежал» на месте три тика и погиб) —
                // тогда жадно: соседняя клетка подальше от врагов и под меньшим огнём; в опасности шаг делается ВСЕГДА,
                // и на не лучшую клетку тоже: скаут у стены (4,40) «бежал» стоя тридцать тиков рядом с боем и погиб
                // (матч 12) — стоящего враг на равной скорости достаёт следующим тиком, идущего нет
                val foes = threats.ifEmpty { ctx.combatEnemies }
                val danger = underFire || nearby.isNotEmpty()
                val step = fleeStep(s, foes, ctx.dangerMatrix, SCOUT_FLEE_RANGE) ?: greedyFlee(ctx, s, foes, force = danger)
                if (step != null) TrafficManager.request(s, step, RUNNER_PRIORITY)
                dbg(s, "FLEE", f, step)
                continue
            }
            if (f == null) {
                // все флаги при деле: к армии, за её спиной
                val step = if (s.getRangeTo(ctx.ourCentroid) > POST_STANDOFF + 2) pathStep(s, ctx.ourCentroid, POST_STANDOFF + 2, crowdMatrixOf(ctx, -1)) else null
                if (step != null) TrafficManager.request(s, step, RUNNER_PRIORITY)
                dbg(s, "RESERVE", null, step)
                continue
            }
            // выход закрывается (см. exitMargin): с флага — в лучшую точку выхода, пока устье открыто
            if (f != null && escapeFlows.isNotEmpty() && getRange(s, f.pos) <= 2 && exitMargin(ctx, f.pos, 0) < 0) {
                val to = runnerEscape(ctx, s)
                if (to != null) {
                    val step = pathStep(s, to, 1, ctx.dangerMatrix)
                    if (step != null) TrafficManager.request(s, step, RUNNER_PRIORITY)
                    dbg(s, "EXIT", f, step)
                    continue
                }
            }
            if (onIt) {
                dbg(s, if (f.ours) "HOLD" else "HOLD_WAIT", f)
                continue
            }
            // брать ли флаг сейчас (дебафф): нельзя — ждём рядом, шаг на клетку сделаем, когда станет можно
            val allowed = captureAllowed(ctx, f)
            val range = if (allowed) 0 else 1
            // свой назначенный флаг открыт для шага, остальные не наши — стены (см. Ctx.flagCells)
            // при запрете захвата клетка флага — стена и для его же бегуна: путь к «зазору 1» шёл ЧЕРЕЗ флаг, и скаут брал R3
            // на 49-м при уклонении с 3-го (матч 56), как и в четырёх боях с けろびー до правила v34/v35
            val step = if (s.getRangeTo(f.pos) > range) pathStep(s, f.pos, range, crowdMatrixOf(ctx, if (allowed) f.pos.x * 100 + f.pos.y else -1)) else null
            if (step != null) { TrafficManager.request(s, step, RUNNER_PRIORITY); planCapture(ctx, step) }
            dbg(s, if (allowed) "TO_FLAG" else "POISED", f, step)
        }
    }

    // ==================== армия ====================

    /** Поле к цели; не наши флаги — стены (кроме самой цели: flowFieldTo всегда открывает целевую клетку). */
    private fun flowTo(ctx: Ctx, target: Position, avoid: Boolean = false, near: Boolean = false): IntArray {
        val key = target.x * 100 + target.y + (if (avoid) 10000 else 0) + (if (near) 20000 else 0)
        val now = getTicks()
        val hit = flowCache[key]
        val at = flowCacheTick[key]
        if (hit != null && at != null && now - at < (if (near) 1 else FLOW_TTL)) return hit
        if (hit != null && bfsCost >= BFS_BUDGET) return hit   // сверх бюджета — устаревшее поле
        val bounded = near || bfsCost >= BFS_BUDGET            // сверх бюджета новая цель — ограниченное поле
        bfsThisTick++
        bfsCost += if (bounded) 0.25 else 1.0
        val f = DistanceMap.flowFieldTo(target, ctx.flagBlocked + (if (avoid) ctx.blocked + avoidCells(ctx) else ctx.blocked),
            maxDist = if (bounded) NEAR_FLOW else Int.MAX_VALUE)
        flowCache[key] = f
        flowCacheTick[key] = if (bounded && !near) -1000 else now
        return f
    }

    /** Клетки в AVOID_RANGE от СТОЯЩИХ боевых врагов — поле «в обход» ведёт мимо лагеря, а не сквозь него.
     *  Идущий враг не обходится: обход идущего навстречу разводил строй с поста в стороны за тик до
     *  столкновения, и рывок врага, прежде отбитый к 212-му тику, стал разгромом (стенд rush). */
    private var avoidCellsCache: List<Position>? = null
    private fun avoidCells(ctx: Ctx): List<Position> = avoidCellsCache ?: run {
        val seen = HashSet<Int>()
        val out = ArrayList<Position>()
        for (e in ctx.combatEnemies) for (dx in -AVOID_RANGE..AVOID_RANGE) for (dy in -AVOID_RANGE..AVOID_RANGE) {
            if (!stationary(e)) continue
            val x = e.x + dx; val y = e.y + dy
            if (x < 0 || y < 0 || x > 99 || y > 99) continue
            if (seen.add(x * 100 + y)) out.add(InfluenceMap.cell(x, y))
        }
        avoidCellsCache = out
        out
    }

    /** Поле к НЕ-вражеской цели (флаг, пост, сбор, отход): в обход врагов, если оттуда, где стоит крип, такой
     *  путь есть, иначе обычное (матч 2 на стенде: маршрут к дальнему флагу вёл через стоящий отряд врага). */
    private fun flowAvoiding(ctx: Ctx, target: Position, creep: Creep, near: Boolean = false): IntArray {
        if (!USE_AVOID) return flowTo(ctx, target, near = near)
        val f = flowTo(ctx, target, true, near)
        return if (f[creep.x * 100 + creep.y] >= 0) f else flowTo(ctx, target, near = near)
    }

    /** Стая у цели: боевые враги рядом с ней и те, кто дойдёт до неё (своим телом по полю) не позже нас —
     *  из ХОДЯЧИХ: стоящий на месте STILL_TICKS тиков в стаю по «успеет дойти» не зачисляется (матч 1:
     *  армия врага не сделала ни шага за 1570 тиков, а «успевала» к каждому флагу, и армия простояла на посту). */
    private fun packAt(ctx: Ctx, pos: Position, flow: IntArray, ourTravel: Int): List<Creep> =
        ctx.combatEnemies.filter { getRange(it, pos) <= FLAG_GUARD_RANGE || (!stationary(it) && pathTicks(it, flow, it.x * 100 + it.y) <= ourTravel) }

    /** Сколько тиков враг не двигался (новый враг считается идущим). */
    private fun stationaryFor(e: Creep): Int = getTicks() - (enemyLastMove[e.id] ?: getTicks())

    /** Враг не двигался последние STILL_TICKS тиков. */
    private fun stationary(e: Creep): Boolean = stationaryFor(e) >= STILL_TICKS

    private class Objective(val flag: FlagInfo, val pack: List<Creep>, val value: Double, val travel: Int)

    /**
     * Флаг-цель армии: не наш, разрешённый к захвату; со стаей — по перевесу Ланчестера (ratio) и цене боя в
     * запасе хода группы (или в контакте); без стаи — просто идём. Ценность — очки размена за тик пути.
     * Текущая цель держится, пока проходит по мягкому порогу (гистерезис).
     */
    /** Враг, с которым есть бой: с уроном, либо лекарь, у которого рядом (в дальности лечения плюс шаг) свой с оружием
     *  в теле, живым или мёртвым (см. armedEnemies). */
    private fun threatening(e: Creep, enemyCreeps: List<Creep>): Boolean {
        val q = InfluenceMap.profileOf(e)
        return q.melee + q.ranged > 0.0 || enemyCreeps.any { w -> w.id != e.id && getRange(w, e) <= HEAL_RANGE + 1 && w.body.any { it.type == ATTACK || it.type == RANGED_ATTACK } }
    }

    private fun chooseFlagObjective(ctx: Ctx, group: List<Creep>, pushRatio: Double, escapeNeeded: Boolean = false): Objective? {
        if (group.isEmpty()) return null
        var best: Objective? = null
        for (f in ctx.flags) {
            if (f.ours) continue
            if (!captureAllowed(ctx, f)) continue
            val flow = flowTo(ctx, f.pos)
            val travel = group.maxOf { pathTicks(it, flow, it.x * 100 + it.y) }
            if (travel >= Int.MAX_VALUE / 4) continue
            if (escapeNeeded) {
                // покинутую точку уклонения армия не идёт «захватывать»: у R3 (13,49) счёт места упал, точка покинута — и
                // тут же выбрана целью в шести тиках, навстречу врагу (матч 12, t=188)
                val left = evadeLeft
                if (left != null && left.x == f.pos.x && left.y == f.pos.y) continue
                // только флаг с выходом (см. ESCAPE_MARGIN, REACTION_LAG): за H4 в угол (8,90) армия шла 52 тика, пока
                // враг шёл на неё с 80 клеток (матч 11); за R3 (13,49) — 41 тик вдоль западного края при спящем враге,
                // и тот пошёл на полпути (матч 12)
                if (exitMargin(ctx, f.pos, travel) < ESCAPE_MARGIN) continue
            }
            // ⚠️ ПРОБОВАНО И ОТВЕРГНУТО (матч 23): запрет марша длиннее, чем врагу дойти до нашей армии, когда мы впереди
            // с растущим отрывом. Ни одного проигрыша стенда он не предотвращает, а бот становится пассивен всякий раз,
            // когда ведёт: m23 rush 23279→21496, m22 wing 23180→21362, m17 wing 23638→21510, m7 sleeper 22462→20033.
            // Растянутую колонну чинит масса (см. MASS_RANGE), а не отказ от цели
            // стая без урона ничего не охраняет: три лекаря врага, лечащие друг друга, делали цену боя бесконечной для
            // ослабленной армии, и она 1500 тиков держала пост при шести свободных флагах (стенд m2 rush)
            val pack = packAt(ctx, f.pos, flow, travel).filter { threatening(it, ctx.enemyCreeps) }
            val current = f.id == objectiveFlagId
            val ratio = if (current) LOCAL_ENTER_RATIO else pushRatio
            // цена боя — гейт на ВХОД к охраняемому флагу (лазейка «уже в контакте» отправила армию к дальнему
            // флагу с девятью охранниками сквозь наступающую армию — стенд rush, t=61)
            val ok = pack.isEmpty() || (ourPowerOf(group, pack) >= enemyPowerOf(pack, group) * ratio &&
                fightCost(pack, group) <= group.maxOf { speedSlack(it) })
            if (!ok) continue
            // гистерезис: текущая цель ценнее на четверть, чтобы не прыгать между равными; дорогой по силе — позже
            val value = f.swing * captureCost(ctx, f) / (travel + 10) * (if (current) 1.25 else 1.0)
            if (best == null || value > best.value) best = Objective(f, pack, value, travel)
        }
        return best
    }

    /** Точка отхода: дом и углы НАШЕЙ половины — достижимая и самая дальняя от центра армии врага (отход в
     *  дальний угол через всю карту вёл сквозь врага, и армию добивали по одному — стенд rush). */
    /** Враг уходит: за CHASE_WINDOW тиков отдалился от ТОГДАШНЕГО центра нашей армии больше чем на клетку. Кайтер
     *  держит дистанцию, и «дистанция до нас не растёт» его не выдаёт — выдаёт движение прочь от места, где мы были.
     *  Порог делает уходящим и блоб, шагнувший назад на две клетки: все двенадцать «неловимы» восемь тиков, huntable 0/12,
     *  наступление снято, армия к посту (матч 70, t=196–207, 223, 234, 554). ОТВЕРГНУТО стендом: порог «больше половины окна»
     *  (уходил дольше, чем стоял) — 66 строк хуже / 44 лучше: кайтеры добиваются медленнее на десятке карт (за ними гонятся
     *  дольше), россыпи m12/m19/m24/m29/m30 spread и m29/m30 farm из победы в проигрыш; гистерезис в самом наступлении —
     *  тоже (см. pushing). Открытая находка. */
    private fun evasive(e: Creep): Boolean {
        val h = enemyCellHist[e.id] ?: return false
        if (h.size < CHASE_WINDOW || ourCentroidHist.size < CHASE_WINDOW) return false
        val c0 = ourCentroidHist.first()
        val old = h.first()
        val cPos = InfluenceMap.cell(c0 / 100, c0 % 100)
        val oldPos = InfluenceMap.cell(old / 100, old % 100)
        return getRange(e, cPos) > getRange(oldPos, cPos) + 1
    }

    /** Ловим ли враг: вплотную к нашему вооружённому (MELEE_KEEP_RANGE), медленнее нашего самого быстрого или не
     *  уходит (см. evasive). Только за ловимым идут стая, охота, добивание и местный бросок (см. CHASE_WINDOW). */
    private fun catchable(e: Creep, armed: List<Creep>): Boolean =
        armed.any { getRange(e, it) <= MELEE_KEEP_RANGE } ||
            // медленнее нас ТАМ, ГДЕ СТОИТ (v48): период на его клетке — в болоте тело с половиной MOVE ходит клетку в пять
            // тиков, и застрявший в болоте ловим, хотя на равнине он равен нам (матч 90, см. InfluenceMap.enemyOrigins)
            periodAt(e, e.x, e.y) > (armed.minOfOrNull { plainPeriod(it) } ?: 1) ||
            !evasive(e)

    private fun retreatPoint(ctx: Ctx): Position {
        val enemy = ctx.enemyCentroid ?: return ctx.home
        // точка одна на весь отход, пока враг не ближе к ней, чем мы: смена точки на ходу ((3,96), потом (96,96))
        // развела армию по трём углам карты, и погоня добила всех поодиночке (матч 4)
        retreatTarget?.let { t -> if (getRange(t, enemy) > getRange(t, ctx.ourCentroid)) return t }
        val corners = listOf(InfluenceMap.cell(3, 3), InfluenceMap.cell(3, 96), InfluenceMap.cell(96, 3), InfluenceMap.cell(96, 96))
        // дом, пока враг не ближе к нему, чем мы; угол — только тогда: «выигрышный по дистанции» угол (3,96) в
        // матче 5 был ловушкой — армия отошла в него от кайтеров и была расстреляна, не имея куда шагнуть
        val enemyBetween = getRange(enemy, ctx.home) < getRange(ctx.ourCentroid, ctx.home)
        val candidates = if (enemyBetween) listOf(ctx.home) + corners.filter { DistanceMap.inOurHalf(it.x, it.y) } else listOf(ctx.home)
        var best = ctx.home
        var bestScore = Int.MIN_VALUE
        for (c in candidates) {
            val flow = flowTo(ctx, c)
            val reach = ctx.army.count { flow[it.x * 100 + it.y] >= 0 }
            if (reach == 0) continue
            // выигрыш дистанции от врага НА КЛЕТКУ ПУТИ: «самая дальняя от врага» точка (3,96) лежала за его
            // флангом — 66 клеток пути ради 62 дистанции, мимо его строя; дом в 17 клетках даёт 22
            val score = getRange(c, enemy) - getRange(c, ctx.ourCentroid)
            if (score > bestScore) { bestScore = score; best = c }
        }
        retreatTarget = best
        return best
    }

    /** Точки выхода: семь флагов и оба дома (углы — карманы, их нет; см. EVADE_SAFE). */
    /** Точки выхода: флаги, оба дома и ЧЕТЫРЕ угла карты. Флаги стоят между домами — на оси подхода врага, и с одними
     *  флагами «прочь» не существовало: уклонение от броска шло к R3 навстречу врагу 30 клеток и было поймано у флага
     *  (матч 34, t=3–57). Углы — то, что всегда лежит в стороне от оси. */
    private fun escapeCandidates(ctx: Ctx): List<Position> =
        ctx.flags.map { it.pos } + listOf(ctx.home, ctx.enemyHome) +
            // углы — только при броске: как постоянные кандидаты они меняли всякое уклонение (102 сценария в одну сторону,
            // 105 в другую, потеря армии m9 sleeper), а нужны они там, где флаги лежат на оси подхода
            (if (unflaggedRushNow) listOf(InfluenceMap.cell(3, 3), InfluenceMap.cell(3, 96), InfluenceMap.cell(96, 3), InfluenceMap.cell(96, 96)).map { passableNear(it) } else emptyList())

    /** Поля потока к точкам выхода и ход врага до каждой — раз в EVADE_EVAL_EVERY тиков (девять полей). */
    private fun refreshEscape(ctx: Ctx, armed: List<Creep>) {
        val now = getTicks()
        if (now - escapeAt < EVADE_EVAL_EVERY && escapeFlows.isNotEmpty()) return
        escapeAt = now
        escapeFlows.clear(); escapeTheirs.clear(); escapeNearest.clear()
        for (c in escapeCandidates(ctx)) {
            val key = c.x * 100 + c.y
            val flow = flowTo(ctx, c)
            escapeFlows[key] = flow
            var bestTicks = Int.MAX_VALUE / 4
            var bestCell = -1
            for (e in armed) {
                val t = pathTicks(e, flow, e.x * 100 + e.y)
                if (t < bestTicks) { bestTicks = t; bestCell = e.x * 100 + e.y }
            }
            escapeTheirs[key] = bestTicks
            escapeNearest[key] = bestCell
        }
    }

    /** Клетка после ticks шагов спуска по полю от start (враг идёт за нами к цели поля). */
    private fun projectAlong(flow: IntArray, start: Int, ticks: Int): Int {
        var cell = start
        var left = ticks
        while (left > 0 && flow[cell] > 0) {
            val cx = cell / 100; val cy = cell % 100
            var next = -1; var nv = flow[cell]
            for ((dx, dy) in DIRECTIONS) {
                val x = cx + dx; val y = cy + dy
                if (x < 0 || y < 0 || x > 99 || y > 99) continue
                val v = flow[x * 100 + y]
                if (v in 0 until nv) { nv = v; next = x * 100 + y }
            }
            if (next < 0) break
            cell = next; left--
        }
        return cell
    }

    /** Запас выхода из точки c при нашем прибытии туда через arrive тиков. Преследователь идёт ЗА НАМИ, к c, а не к
     *  выходам: ближайший к c враг проецируется по полю к c на approachRate × arrive шагов, и от этой клетки считается
     *  его путь к каждому другому выходу минус наш путь от c туда; лучший из них — запас. Фора «идёт к выходу
     *  мгновенно» браковала всякую цель при идущем на нас враге, и армия сидела дома до боя в кармане (стенд m10
     *  hunter, m8 army); без выхода точка — карман (матч 11). */
    private fun exitMargin(ctx: Ctx, c: Position, arrive: Int): Int {
        val ckey = c.x * 100 + c.y
        val flowC = escapeFlows[ckey] ?: return Int.MIN_VALUE / 2
        val start = escapeNearest[ckey] ?: return Int.MIN_VALUE / 2
        val theirsC = escapeTheirs[ckey] ?: return Int.MIN_VALUE / 2
        if (theirsC >= Int.MAX_VALUE / 4) return Int.MIN_VALUE / 2   // его путь неизвестен — выход не подтверждён (v54)
        // при броске (см. EVADE_EQUAL_RATIO) преследователь идёт за нами на ПОЛНОЙ скорости: проекция по замеренному
        // темпу (0.42 в паузе колонны) считала дом безопасным выходом, и армия ушла в свой угол под удар (матч 32)
        val rate = if (unflaggedRushNow) 1.0 else approachRate
        val pursuer = if (start < 0) -1 else projectAlong(flowC, start, minOf(theirsC, (rate * arrive).toInt() + REACTION_LAG))
        var best = Int.MIN_VALUE / 2
        for (d in escapeCandidates(ctx)) {
            if (d.x == c.x && d.y == c.y) continue
            val flow = escapeFlows[d.x * 100 + d.y] ?: continue
            val step = flowNear(flow, c)
            if (step < 0) continue
            val theirs = if (pursuer < 0) Int.MAX_VALUE / 4 else flowNear(flow, InfluenceMap.cell(pursuer / 100, pursuer % 100)).let { if (it < 0) Int.MAX_VALUE / 4 else it }
            best = maxOf(best, theirs - step)
        }
        return best
    }

    /** Значение поля в клетке или, если она закрыта (чужой флаг — препятствие в полях потока), в лучшей соседней плюс
     *  шаг: запас выхода читался в клетке чужого флага и был «нет пути» для всякого флага-цели (стенд m1 scouts). */
    private fun flowNear(flow: IntArray, p: Position): Int {
        val here = flow[p.x * 100 + p.y]
        if (here >= 0) return here
        var best = -1
        for ((dx, dy) in DIRECTIONS) {
            if (dx == 0 && dy == 0) continue
            val x = p.x + dx; val y = p.y + dy
            if (x < 0 || y < 0 || x > 99 || y > 99) continue
            val v = flow[x * 100 + y]
            if (v >= 0 && (best < 0 || v + 1 < best)) best = v + 1
        }
        return best
    }

    /** Точка уклонения (см. EVADE_SAFE): из точек выхода — с наибольшим счётом (меньший из запасов прибытия и выхода);
     *  где стоим — только пока счёт не меньше EVADE_SAFE; прежняя держится, пока не хуже лучшей на EVADE_HYSTERESIS;
     *  null — карман, уходить некуда. */
    /** Точка выхода для одиночного бегуна: лучшая по меньшему из запасов прибытия и выхода на ЕГО пути, не та, где он
     *  стоит (см. evadePoint для армии). */
    private fun runnerEscape(ctx: Ctx, s: Creep): Position? {
        var best: Position? = null
        var bestScore = Int.MIN_VALUE
        for (c in escapeCandidates(ctx)) {
            if (getRange(c, s) <= 2) continue
            val key = c.x * 100 + c.y
            val flow = escapeFlows[key] ?: continue
            val theirs = escapeTheirs[key] ?: continue
            val ticks = pathTicks(s, flow, s.x * 100 + s.y)
            if (ticks >= Int.MAX_VALUE / 4) continue
            val score = minOf(theirs - ticks, exitMargin(ctx, c, ticks))
            if (best == null || score > bestScore) { bestScore = score; best = c }
        }
        return best
    }

    private fun evadePoint(ctx: Ctx, armed: List<Creep>, strikers: List<Creep>): Position? {
        val now = getTicks()
        val cur = evadeTarget
        val arrived = cur != null && getRange(ctx.ourCentroid, cur) <= EVADE_ARRIVED
        if (cur != null && !arrived && now - evadeEvaluatedAt < EVADE_EVAL_EVERY) return cur
        evadeEvaluatedAt = now
        // прибыли в другую точку — покинутая снова допустима (см. evadeLeft)
        evadeLeft?.let { l -> if (arrived && cur != null && (cur.x != l.x || cur.y != l.y)) evadeLeft = null }
        val left = evadeLeft
        var best: Position? = null
        var bestScore = Int.MIN_VALUE
        var bestArrive = 0
        var bestExit = 0
        var curScore = Int.MIN_VALUE
        // при броске (см. EVADE_EQUAL_RATIO) выход обязан быть ПРОЧЬ: не ближе к центру вражеской армии, чем мы сейчас.
        // Запас «мы придём первыми» считал R3 на оси подхода безопасным, и армия шла врагу навстречу (матч 34)
        val enemyCentre = if (unflaggedRushNow) centroidOf(armed) else null
        for (c in escapeCandidates(ctx)) {
            if (left != null && c.x == left.x && c.y == left.y) continue
            if (enemyCentre != null && getRange(c, enemyCentre) <= getRange(ctx.ourCentroid, enemyCentre)) continue
            val key = c.x * 100 + c.y
            val flow = escapeFlows[key] ?: continue
            val theirs = escapeTheirs[key] ?: continue
            // «ему не дойти» — это НЕИЗВЕСТНОСТЬ, не безопасность (v54): поле за бюджетом BFS даёт Int.MAX_VALUE / 4, и точка
            // получала запас 536870903 — армия ушла в угол (96,3) при его армии в 75 клетках к югу и была там стёрта (матч 114,
            // Coldkimchi, t=333); бегство вбок (v53) не включилось, потому что «лучшая точка» была положительной
            if (theirs >= Int.MAX_VALUE / 4) continue
            val ourTicks = strikers.maxOfOrNull { pathTicks(it, flow, it.x * 100 + it.y) } ?: continue
            if (ourTicks >= Int.MAX_VALUE / 4) continue
            val exit = exitMargin(ctx, c, ourTicks)
            val score = minOf(theirs - ourTicks, exit)
            if (getRange(c, ctx.ourCentroid) <= EVADE_ARRIVED && score < EVADE_SAFE) { evadeLeft = c; continue }
            if (cur != null && c.x == cur.x && c.y == cur.y) curScore = score
            if (best == null || score > bestScore) { bestScore = score; best = c; bestArrive = theirs - ourTicks; bestExit = exit }
        }
        if (cur != null && !arrived && curScore >= bestScore - EVADE_HYSTERESIS && curScore > 0) return cur
        // ни одной точки с запасом — бегство направлением (см. fleePoint); точка с нулевым или отрицательным запасом — это шаг
        // сквозь преследователя или в угол (матч 80: (3,3) −40, дом 0, (96,96) 0)
        if (USE_FLEE_DIRECTION && (best == null || bestScore <= 0)) {
            val flee = fleePoint(ctx, armed)
            if (flee != null) {
                if (cur == null || cur.x != flee.x || cur.y != flee.y)
                    println("evade: t=$now flee=(${flee.x},${flee.y}) best=${best?.let { "(${it.x},${it.y})" } ?: "-"} score=$bestScore from=(${ctx.ourCentroid.x},${ctx.ourCentroid.y}) approach=${(approachRate * 100).toInt()}")
                evadeTarget = flee
                return flee
            }
        }
        if (best == null) { evadeTarget = null; return null }
        if (cur == null || cur.x != best.x || cur.y != best.y)
            println("evade: t=$now to=(${best.x},${best.y}) score=$bestScore arrive=$bestArrive exit=$bestExit from=(${ctx.ourCentroid.x},${ctx.ourCentroid.y}) approach=${(approachRate * 100).toInt()}")
        evadeTarget = best
        return best
    }

    /** Пост: центр наших флагов (их и держим), без флагов — дом; и НЕ БЛИЖЕ EVADE_RANGE к краю карты (v46). Матчи 78 и 80
     *  (Coldkimchi, стоячая линия при паритете, из контакта отхода нет): единственный наш флаг — угловой H4 (90,8), пост на
     *  нём, армия стояла в углу; когда он пошёл на нас, ни одна точка уклонения не имела запаса (лог evade: (96,3) 13, дальше
     *  (3,3) −40 сквозь него, дом с выходом 0, угол (96,96) с выходом 0) — контакт на 319-м и 510-м, армия стёрта при его
     *  16000/16000. Флаг остаётся нашим, пока на него не встанет чужой (хранитель встаёт, когда враг подходит, см. KEEP_RANGE);
     *  стоять на нём армии незачем, а угол — ловушка для равного по скорости. */
    private fun postPoint(ctx: Ctx): Position {
        val c = centroidOf(ctx.flags.filter { it.ours }.map { it.pos }) ?: ctx.home
        return if (!USE_POST_INSIDE) passableNear(c) else passableNear(InfluenceMap.cell(c.x.coerceIn(EVADE_RANGE, 99 - EVADE_RANGE), c.y.coerceIn(EVADE_RANGE, 99 - EVADE_RANGE)))
    }

    /** Бегство направлением (v46): когда ни одна точка выхода не даёт запаса (см. evadePoint), цель — клетка в EVADE_RANGE от
     *  нашего центра в том из восьми направлений, где после шага центр вооружённого врага дальше всего, среди направлений,
     *  чья клетка не ближе EVADE_RANGE к краю (у края направлений вдвое меньше, в углу — вчетверо: матчи 78, 80). Точки
     *  выхода (флаги, дом, углы) при равной скорости преследователя все «за ним» или без выхода, и армия шла в наименее
     *  плохую — в угол. */
    private fun fleePoint(ctx: Ctx, armed: List<Creep>): Position? {
        val ec = centroidOf(armed) ?: return null
        val oc = ctx.ourCentroid
        // отступ от края — не больше нынешнего: у края все направления вдоль края запрещались, оставались только внутрь, и
        // армия с (29,6) пошла на (52,32) наискосок МИМО его центра (30,30) — перехвачена на 69-м, стёрта к 120-му (матч 83,
        // けろびー боевой, которого v45 била). Направление обязано уводить: скалярное произведение с вектором «от него к нам»
        // положительно; из допустимых — то, где его центр после шага дальше всего
        val margin = minOf(EVADE_RANGE, oc.x, oc.y, 99 - oc.x, 99 - oc.y).coerceAtLeast(0)
        val ax = oc.x - ec.x; val ay = oc.y - ec.y
        // ВБОК, когда «прочь» некуда (v53): из домашнего угла каждое направление прочь от его центра уводит за карту — матч 110,
        // бросок боевого けろびー с 3-го тика, уклонение из угла в угол, контакт у (79,81)–(93,93), армия стёрта к 150-му; тот же
        // бой в открытом поле выигран пять раз. Направление допустимо, если конец шага не ближе EVADE_RANGE к его центру:
        // сначала уводящие (скалярное произведение > 0), затем боковые; бой, если придёт, придёт в поле.
        // НАХОДКА (матч 115, не исправлено): у верхнего края при враге точно к югу «прочь» — за картой, и знак крошечного
        // бокового смещения его центра решал запад/восток: (5,3) на 56-м, (3,3) на 61-м, (50,6) на 71-м, (57,6) на 76-м —
        // центр армии за 20 тиков (30,3)→(28,3)→(25,3)→(27,3)→(30,3), контакт на 77-м. Ранжирование по расстоянию с
        // гистерезисом (v55-опыт) гейт прошло, но 25 строк хуже / 29 лучше — то же дрожание было во всех девятнадцати
        // победах над тем же соперником, решил не отход, а бой (см. covered)
        fun pick(away: Boolean): Position? {
            var best: Position? = null
            var bestD = -1
            for ((dx, dy) in DIRECTIONS) {
                if (dx == 0 && dy == 0) continue
                val dot = dx * ax + dy * ay
                if (if (away) dot <= 0 else dot < 0) continue
                val x = oc.x + dx * EVADE_RANGE; val y = oc.y + dy * EVADE_RANGE
                if (x < margin || y < margin || x > 99 - margin || y > 99 - margin) continue
                val c = passableNear(InfluenceMap.cell(x, y))
                val d = getRange(c, ec)
                if (d > bestD) { bestD = d; best = c }
            }
            return best?.takeIf { getRange(it, ec) >= (if (away) getRange(oc, ec) + 1 else EVADE_RANGE) }
        }
        return pick(true) ?: pick(false)
    }

    /** Ближайшая проходимая клетка: центр наших флагов попал в стенной блок, поле к нему было пустым (flow=-1), и
     *  армия стояла на месте, пока враг подходил (матч 11, t=90–103). */
    private fun passableNear(p: Position): Position {
        if (!DistanceMap.isTerrainWall(p.x, p.y)) return p
        for (r in 1..30) for (dx in -r..r) for (dy in -r..r) {
            if (maxOf(abs(dx), abs(dy)) != r) continue
            val x = p.x + dx; val y = p.y + dy
            if (x in 0..99 && y in 0..99 && !DistanceMap.isTerrainWall(x, y)) return InfluenceMap.cell(x, y)
        }
        return p
    }

    private fun runArmy(ctx: Ctx) {
        val army = ctx.army
        if (army.isEmpty()) return
        val allies = ctx.myCreeps
        val enemyCreeps = ctx.enemyCreeps
        val combatEnemies = ctx.combatEnemies
        updateKeepers(ctx, army)

        val strikers = army.filter { fullSpeed(it) && hasWeapon(it) && it.id !in keeperIds }
        // враги, с которыми есть бой: с уроном — и лекари, у которых рядом (в дальности лечения плюс шаг) есть свой с
        // оружием в теле, живым или мёртвым: такого лекарь вернёт в строй за шесть тиков (стенд m2 rush: армия ушла за
        // флагами от лекарей с обломками, и через сто тиков те вернулись в полном теле). Стая из одних лекарей при
        // скаутах (сила 0) не повод для боя: два уцелевших лекаря врага кайтили в четырёх клетках 1700 тиков, армия
        // в ДОБИТЬ то гналась, то сбивалась в кучу и не шла за флагами, пока скауты врага брали пять (m7 rush)
        val armedEnemies = combatEnemies.filter { threatening(it, enemyCreeps) }
        // чистый урон врагу за окно: сумма его хитов ниже, чем STALL_TICKS тиков назад (попадание с полным лечением в тот же
        // тик — не прогресс: стрелок россыпи с трёх клеток попадал, лечился, и «обмен уронами» сбрасывал простой);
        // простой — только когда добыча в досягаемости броска, а прогресса нет (на марше к врагу за 20+ клеток простоя
        // нет — стенд m3 army: пауза на подходе выключала давление, и обе армии простояли до конца)
        val now = getTicks()
        val enemyHitsNow = enemyCreeps.sumOf { it.hits }
        val ourHitsNow = army.sumOf { it.hits }
        enemyHitsHist.addLast(enemyHitsNow); ourHitsHist.addLast(ourHitsNow)
        while (enemyHitsHist.size > STALL_TICKS) enemyHitsHist.removeFirst()
        while (ourHitsHist.size > STALL_TICKS) ourHitsHist.removeFirst()
        // наступление окупается (см. PUSH_EXCHANGE); без окна — да (нечего мерить)
        val exchangePaying = ourHitsHist.size < STALL_TICKS ||
            (enemyHitsHist.first() - enemyHitsNow) >= (ourHitsHist.first() - ourHitsNow) * PUSH_EXCHANGE
        val mobileArmy = army.filter { canMove(it) && it.id !in keeperIds }
        val chasers = strikers.ifEmpty { mobileArmy }
        // кого вообще можно догнать (см. catchable): добивание по перевесу идёт только за ними, и по ним же считается
        // пикет простоя — поэтому охота посчитана здесь, до простоя
        val huntable = armedEnemies.filter { catchable(it, chasers) }
        // с обеих сторон: бьют только нас — бой, не простой (матч 20, t=117)
        val netDamage = enemyHitsHist.size == STALL_TICKS &&
            (enemyHitsHist.first() - enemyHitsNow >= STALL_DAMAGE || ourHitsHist.first() - ourHitsNow >= STALL_DAMAGE)
        if (netDamage) stallUntil = 0
        // пикет в досягаемости броска все STALL_TICKS подряд (см. STALL_PICKET): армия, только что вошедшая в
        // досягаемость, простоя не даёт (матч 20, t=64). Считается пикет по ДОГОНЯЕМЫМ (см. catchable): прежде
        // «не больше STALL_PICKET вооружённых» отделяло пикет от армии по ЧИСЛУ, и блоб, который от нас уклоняется и
        // не дерётся, одним своим числом отменял простой — армия гналась за ним весь матч. Живой матч 26: huntable=0/8,
        // 902 хита урона за 1500 тиков с обеих сторон, ни одной смерти, проигрыш 12721:23408; стенд farm на карте 21:
        // три флага на одиннадцать очков в тик простояли ничьими 1500 тиков. Кого можем догнать — драка; кто
        // уклоняется — не повод стоять
        val nearArmed = armedEnemies.count { e -> strikers.any { getRange(it, e) <= ENGAGE_RANGE } }
        val nearCatchable = huntable.count { e -> strikers.any { getRange(it, e) <= ENGAGE_RANGE } }
        // пикет — МЕНЬШИНСТВО его вооружённых (v50, оператор по матчу 101: «загоняем врага в угол, а потом разворачиваемся и
        // уходим в центр, не добив»): загнанный в угол остаток из трёх-четырёх вооружённых с лекарями четыре раза за матч
        // считался пикетом («picket of 3 armed in reach for 20 ticks — flags until +300», t=161, 547, 895, 1256), и армия на
        // триста тиков уходила за флагами. Когда в досягаемости не меньше половины его вооружённых, это его армия, а не пикет
        val picket = nearArmed >= 1 && nearCatchable <= STALL_PICKET && nearArmed * 2 < armedEnemies.size
        preyNearTicks = if (picket) preyNearTicks + 1 else 0
        // ВТОРОЙ вид простоя — марш, который не идёт. Пикет ловит бесплодную погоню, только пока добыча ближе
        // ENGAGE_RANGE; за этой чертой армия «гналась» и стояла, а простой не считался ни разу. Идущая погоня обязана
        // двигать центр вооружённой массы: за MARCH_STALL_TICKS тиков он не сдвинулся НИ НА КЛЕТКУ — это не марш.
        // Матч 25: добыча стояла в 11 клетках, ближе никого, армия 990 тиков дёргалась на месте у (46,34); за весь
        // матч ни одного урона ни с одной стороны, и проигрыш по очкам 19927:24205 при 12 против 13 в тик
        val marchCell = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army })?.let { it.x * 100 + it.y } ?: -1
        marchHist.addLast(marchCell)
        // ТРЕТИЙ вид простоя — враг, который держит дистанцию: в добивании без контакта дистанция между центрами армий за
        // CHASE_WINDOW тиков не сократилась, и враг дальше броска. Матч 48 (けろびー v5, фермер): он взял шесть флагов к 80-му
        // (сам на 0,75 мощи), парил в 10–28 клетках от нас и не дрался — за 1600 тиков ни одного выстрела с нашей стороны;
        // пикет не срабатывал (враг дальше ENGAGE_RANGE), марш не «стоял» (армия за ним ходила), и ANNIHILATE держал армию
        // лицом к нему на двух-трёх флагах против его пяти: 8 в тик против 17, проигрыш 15652:22950 при 16000/16000 у обоих
        val armyDist = ctx.enemyCentroid?.let { getRange(centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army }) ?: it, it) } ?: -1
        if (posture == Posture.ANNIHILATE && !inContact(armedEnemies, army) && armyDist >= 0) {
            armyDistHist.addLast(armyDist)
            // центр ВООРУЖЁННЫХ (v58): центр всех его крипов двигали два бегающих скаута, и стоящий на D5 лагерь «уходил» —
            // отряд на 566-м при his_moved=0 по реплею (матч 133, одиннадцатый проигрыш фермеру-лагерю 8346:22771)
            enemyCentHist.addLast(centroidOf(armedEnemies)?.let { it.x * 100 + it.y } ?: -1)
        } else { armyDistHist.clear(); enemyCentHist.clear() }
        while (armyDistHist.size > DETACH_WINDOW + 1) armyDistHist.removeFirst()
        while (enemyCentHist.size > DETACH_WINDOW + 1) enemyCentHist.removeFirst()
        // ...и это ОН уходит (v57): центр его вооружённых за окно сместился не меньше чем на четверть окна — стоячий лагерь, у
        // которого замираем мы, дистанцию не «держит». Окно отряда — DETACH_WINDOW (v59): по восьми тикам (CHASE_WINDOW) отряд
        // собрался на 207-м тике матча 139, когда дистанция за сто тиков сократилась с 40 до 12 — армия почти догнала, а
        // восьмитиковое окно поймало паузу; ядро без пяти встало, он ушёл и запарковался (3174:22931)
        fun kept(window: Int): Boolean {
            if (armyDistHist.size <= window || enemyCentHist.size <= window) return false
            val d0 = armyDistHist.elementAt(armyDistHist.size - 1 - window)
            val a = enemyCentHist.elementAt(enemyCentHist.size - 1 - window); val b = enemyCentHist.last()
            if (a < 0 || b < 0) return false
            val moved = maxOf(abs(a / 100 - b / 100), abs(a % 100 - b % 100))
            return armyDistHist.last() >= d0 && armyDistHist.last() > ENGAGE_RANGE && moved >= window / 4
        }
        val distanceKept = combatEnemies.isNotEmpty() && kept(DETACH_WINDOW)
        if (distanceKept) lastDistanceKeptTick = now
        val keepsDistance = USE_KEEPS_DISTANCE_STALL && combatEnemies.isNotEmpty() && kept(CHASE_WINDOW)
        while (marchHist.size > MARCH_STALL_TICKS) marchHist.removeFirst()
        // в контакте стоять — законно (строй рубится на месте), и полное взаимное лечение даёт нулевой чистый урон
        val marchStalled = pushing && marchCell >= 0 && marchHist.size == MARCH_STALL_TICKS &&
            marchHist.all { it == marchCell } && !inContact(armedEnemies, army)
        // в любой постуре, кроме отхода и уклонения: в ПОСТУ с висящим рядом врагом «держим линию» без простоя длилось до
        // конца матча (стенд m19 spread, t=600–1600)
        // боевые враги нужны ПИКЕТУ (он из них и состоит), а простою марша — нет: зачистка идёт ровно тогда, когда
        // боевых не осталось, и там сетка не сработала ни разу (стенд m18 roost: 1500 тиков погони за двумя скаутами)
        if (posture != Posture.RETREAT && posture != Posture.EVADE && !netDamage && now >= stallUntil &&
            ((combatEnemies.isNotEmpty() && preyNearTicks >= STALL_TICKS) || marchStalled || keepsDistance)) {
            stallUntil = now + STALL_COOLDOWN
            if (DEBUG_LOG) println("stall t=$now: ${if (marchStalled) "the march has not moved a cell for $MARCH_STALL_TICKS ticks" else if (keepsDistance) "the enemy keeps its distance (${armyDistHist.first()} -> ${armyDistHist.last()} over $CHASE_WINDOW ticks)" else "picket of $nearArmed armed in reach for $preyNearTicks ticks"} without damage either way — flags until $stallUntil")
        }
        val stalled = now < stallUntil
        stalledNow = stalled

        // ---- постура ----
        val ours = ourPowerOf(army, combatEnemies)
        val theirs = enemyPowerOf(combatEnemies, army)
        val nearRange = if (posture == Posture.RETREAT) NEAR_RANGE + NEAR_RELEASE else NEAR_RANGE
        // ОТВЕРГНУТО стендом: «враг рядом — рядом с МАССОЙ армии, а не с любым нашим крипом» (хранители стоят по
        // одному на разных концах карты, и висящий у хранителя враг россыпи отменяет цель-флаг у всей армии).
        // Целевой сценарий m22 spread не сдвинулся вовсе (16622:24323), а m20 spread перешёл из победы в проигрыш
        // (24337:21666 -> 19400:24328) и m19 block из уничтожения армии врага на 389-м в победу по очкам на 1142-м;
        // выиграли только россыпи на 12, 19 и 21. Мигание постуры на россыпи — открытая находка
        val enemyNear = armedEnemies.any { e -> army.any { getRange(e, it) <= nearRange } }
        // контакт решает сам: пассивного поста в контакте нет — он отдаёт армию по одному (стенд rush: десять
        // за двоих). Отход из контакта возможен, только если он не бегство: никто из врагов-мили не вплотную
        // и наш строй не медленнее их самого быстрого — при равной скорости преследователь стреляет в спину
        // каждый тик, а обездвиженные остаются врагу (стенд rush: отход при 1250 против 1619 отдал ещё
        // шестерых). Иначе в контакте — бой всем составом, даже слабее: рубка с фокусом лучше разгрома
        // контакт армии — контакт её МАССЫ (см. MASS_RANGE): один оторвавшийся не переводит армию в бой
        val massCentroid = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army }) ?: ctx.ourCentroid
        val massArmy = army.filter { getRange(it, massCentroid) <= MASS_RANGE }.ifEmpty { army }
        val contact = inContact(armedEnemies, massArmy)
        val meleeAdjacent = combatEnemies.any { e -> hasMelee(e) && army.any { getRange(e, it) <= 1 } }
        val ourPeriod = mobileArmy.maxOfOrNull { plainPeriod(it) } ?: 1
        val theirPeriod = combatEnemies.filter { canMove(it) }.minOfOrNull { plainPeriod(it) } ?: Int.MAX_VALUE / 4
        // при РАВНОЙ скорости отход из контакта без мили вплотную — размен выстрелами в обе стороны, не бегство; из
        // точки отхода, куда уже пришли, отходить некуда — бой (матч 5: семеро в углу (3,96) при «отходе» не
        // шевелились и не били, пока их расстреливали с трёх клеток)
        val atRetreatPoint = retreatTarget?.let { getRange(ctx.ourCentroid, it) <= POST_STANDOFF + ARRIVED_SLACK } ?: false
        // из контакта отхода нет: «отход, пока мили не вплотную» мигал ДОБИТЬ/ОТХОД через тик и отдавал армию по одному
        // в матчах 4, 6 и 7 (в седьмом — при 1.53, без единой потери у врага); при равной скорости из контакта не
        // уйти, и единственный способ его кончить — бой строем
        // без стрелков строя нет — лекарей и раненых травят, и «в контакте держим строй» держало их у поста, где
        // стоял враг (стенд m7 sleeper: три лекаря с flee=true разбежались по карте и были добиты поодиночке)
        val retreatFeasible = (!contact || strikers.isEmpty()) && !atRetreatPoint
        val weaker = theirs >= ours * (if (posture == Posture.RETREAT) RETREAT_RELEASE_RATIO else RETREAT_RATIO)
        // из идущего боя (см. RETREAT_CONTACT_RATIO) — только при явном проигрыше
        val weakerContact = theirs >= ours * (if (posture == Posture.ANNIHILATE) RETREAT_CONTACT_RATIO else if (posture == Posture.RETREAT) RETREAT_RELEASE_RATIO else RETREAT_RATIO)
        // ДОБИТЬ по перевесу — с гистерезисом; по контакту — пока контакт есть (без гистерезиса: см. PUSH_RELEASE_RATIO)
        val stalemate = behindTicks >= BEHIND_PATIENCE
        stalemateNow = stalemate
        val pushRatio = if (stalemate) PUSH_RATIO_STALEMATE else if (behindOnScore) PUSH_RATIO_BEHIND else PUSH_RATIO
        val pushRelease = if (stalemate) PUSH_RELEASE_RATIO_STALEMATE else if (behindOnScore) PUSH_RELEASE_RATIO_BEHIND else PUSH_RELEASE_RATIO
        // зачистка: у врага не осталось никого с боем, а мы позади по очкам — аннигиляция единственная победа, и остаток
        // (скауты, обломки) добивается без оглядки на «ловимость» (матч 19: последний M1 с 28 хитами сидел у нашего R3
        // пятьсот тиков, армия ходила за флагами и проиграла по очкам)
        val sweep = combatEnemies.isEmpty() && enemyCreeps.isNotEmpty() && strikers.isNotEmpty() && behindOnScore
        // и зачистка уступает простою: она стояла ВНЕ него, поэтому замерший на месте «дожим» не выключался ничем
        // перехват (см. USE_INTERCEPT): ближайший к центру фермера флаг не из его — туда; свой — пост (см. post ниже); считается до наступления — см. chaseVeto, иначе — цель
        val interceptFlag: FlagInfo? = if (!enemyNotFightingNow || armedEnemies.isEmpty()) null else ctx.enemyCentroid?.let { ec ->
            val group = strikers.ifEmpty { mobileArmy }
            // липкий: выбранный держим, пока он не его
            interceptFlagId?.let { id -> ctx.flags.firstOrNull { it.id == id && !it.theirs } }
                ?: ctx.flags.filter { !it.theirs }.sortedBy { getRange(it.pos, ec) }.firstOrNull { f ->
                    val flow = flowTo(ctx, f.pos)
                    val ours = group.maxOfOrNull { pathTicks(it, flow, it.x * 100 + it.y) } ?: 0
                    ours < Int.MAX_VALUE / 4 && ours + INTERCEPT_MARGIN <= getRange(f.pos, ec)
                }
        }
        interceptFlagId = interceptFlag?.id
        // перехват снимает наступление, только пока есть ЧТО перехватывать — флаг не наш, за которым фермер придёт; когда все
        // флаги его, «перехват» — пост у своего флага, а за ним он не придёт при 22 очках в тик. Матч 70 (けろびー v5): он сел
        // на D5 двенадцатью при 0,6 мощи (2954 против наших 4179), и армия 1000 тиков дёргалась в 10–13 клетках от него между
        // ДОБИТЬ и постом в 35 клетках позади (noFire ≥ 20 и «в досягаемости броска» мигали на границе 8 клеток, поза
        // переключалась каждые 1–4 тика) — 3174:22934 без единого выстрела с обеих сторон. Позади по очкам против врага,
        // который не дерётся и которому нечего перехватывать, стоять — проиграть наверняка; впереди — стоять верно (v42)
        // отряды (см. USE_DETACH): решение на следующий тик — Ctx строится до мощей
        if (USE_DETACH) {
            // фермер: сто тиков (PASSIVE_TICKS) без единого снятого с нас хита с тех пор, как он последний раз был в досягаемости
            // броска, и был в ней не дальше ста тиков назад. Счётчик «рядом и не стреляет» по тикам (noFireTicks) сбрасывался
            // всякий раз, когда блоб отходил дальше NEAR_RANGE, и за 1800 тиков матча 108 не дошёл до ста ни разу (0 detached)
            // погоня без сближения (v57, см. lastDistanceKeptTick) не дальше PASSIVE_TICKS назад — вход; собранный отряд держится,
            // пока его вооружённые есть. Фермер — тот, кто НИ РАЗУ не ударил (lastHurtTick == 0): «сто тиков без удара» пускало
            // отряд против кайтера стенда, который бил на 76–84-м приманкой и вернулся за разделённым ядром — m31 kite 1817:23890,
            // армия стёрта к 400-му (ядро без четырёх стрелков против пяти его стрелков с лекарями: урон мили, которых кайтер не
            // подпускает, в паритете по Ланчестеру считается полностью), m28 kite при наборе из мили — 4970:23907. Живой фермер
            // (матчи 119, 126) не ударил ни разу за 1300–1600 тиков. Первый удар отзывает отряд навсегда
            val chaseDry = now - lastDistanceKeptTick <= PASSIVE_TICKS
            val quiet = lastHurtTick == 0 || now - lastHurtTick >= FARMER_QUIET   // тишина (v65, см. FARMER_QUIET)
            // второй вход (v68): противник тих FARMER_QUIET с ПЕРВОЙ досягаемости (бросок на сотом тике — не фермер) и гонка проиграна
            // (отстаём с меньшим темпом) — отряд собирается без сухой погони. Матч 161 (шестнадцатый проигрыш фермеру 19771:23843):
            // отряд вышел на 806-м, когда толчок наконец не сближал, и с 900-го мы вели 14 против 11 в тик, а 800 тиков до того
            // были проиграны 3–13 против 12–22 — качели «взяли флаги → слабее → уклонение → потеряли → сильнее → толчок»
            val quietSinceFirstReach = firstReachTick >= 0 && now - firstReachTick >= FARMER_QUIET
            val lostRaceNow = behindOnScore && ourRate <= enemyRate
            val farmer = armedEnemies.isNotEmpty() && quiet && lastReachTick >= 0 &&
                (chaseDry || detachedIds.isNotEmpty() || (quietSinceFirstReach && lostRaceNow))
            val detachedBefore = detachedIds.size
            if (!farmer) detachedIds.clear()
            else if (!contact) {
                val armed = army.filter { hasWeapon(it) && fullSpeed(it) && it.id !in keeperIds && it.id !in rotatingIds }
                val unmanned = ctx.flags.count { f -> f.occupant?.my != true }
                val pool = armed.sortedBy { ourPowerOf(listOf(it), emptyList()) }
                var remaining = army.filter { it.id !in detachedIds }
                for (c in pool) {
                    if (detachedIds.size >= unmanned) break
                    val without = remaining.filter { it.id != c.id }
                    if (without.none { hasWeapon(it) } || ourPowerOf(without, combatEnemies) < theirs * PARITY_FLOOR) break
                    detachedIds.add(c.id)
                    remaining = without
                }
            }
            if (DEBUG_LOG && detachedIds.size != detachedBefore)
                println("detach t=$now: ${detachedIds.size} detached (was $detachedBefore) farmer=$farmer dry=${now - lastDistanceKeptTick} hurt=${now - lastHurtTick} reach=${now - lastReachTick} contact=$contact theirs=${theirs.toInt()}")
        } else detachedIds.clear()
        val interceptDenies = interceptFlag != null && !interceptFlag.ours
        val chaseVeto = enemyNotFightingNow && (interceptDenies || !behindOnScore)
        // ОТКРЫТАЯ НАХОДКА (матч 70): второй источник мигания — «ловимых нет»: блоб, шагнувший назад на две клетки, делает
        // «уходящими» всех двенадцать на восемь тиков (см. evasive), и наступление снимается на эти тики, армия к посту.
        // Два устранения ОТВЕРГНУТЫ стендом: гистерезис по ловимости (наступление снимается лишь после целого CHASE_WINDOW без
        // ловимых) — 51 хуже / 51 лучше, гейтовые m28 farm+weak и m30 camp красные, кайтеры добиваются позже на десятке карт,
        // m16 kite проигран; порог evasive «больше половины окна» — 66 хуже / 44 лучше. Быстрое снятие наступления, когда
        // ловимых нет, — то, чем армия не гонится за кайтером; цена — эти тики против блоба, который отступает и возвращается
        pushing = !stalled && (sweep || (exchangePaying && !chaseVeto && huntable.isNotEmpty() && strikers.isNotEmpty() && ours >= theirs * (if (pushing) pushRelease else pushRatio)))
        // бой по контакту — пока отход невозможен: мили врага вплотную. Решение ТИК ЗА ТИКОМ, и это не дрожание, а
        // кайт погони: слабее — отходим, стреляя и рубя на ходу (strike/shoot идут в любой постуре); догнал мили —
        // вся армия разворачивается на него (авангард погони один против всех), отстал — снова отход. На стенде
        // sleeper при 0.83 это 10:0; «поймали — деремся до конца контакта» дало 2:11, «слабее — только отход» 2:6
        val contactFight = !stalled && armedEnemies.isNotEmpty() && strikers.isNotEmpty() && contact && !(retreatFeasible && weakerContact)
        val annihilate = pushing || contactFight
        // непобедимая армия (см. EVADE_SAFE): с ней не деремся — флаг-цель только с выходом, иначе уклонение на любой
        // дистанции: держимся там, откуда есть выход, и уходим, когда она подходит
        // уклонение — только от ЯВНО сильнейшей армии (см. RETREAT_RATIO): при паритете флагов (v14) бой равный, и бежать
        // от него на равной скорости — быть пойманным с растянутым хвостом (матчи 11–12); прежнее «не сильнее для
        // добивания» уводило и от равной армии. Поля выхода нужны и бегунам без армии (см. runnerEscape)
        // от безфлагового броска (см. EVADE_EQUAL_RATIO) уклоняемся уже при равной силе
        val hunted = armedEnemies.isNotEmpty() && strikers.isNotEmpty() &&
            (theirs >= ours * RETREAT_RATIO || (unflaggedRushNow && theirs >= ours * EVADE_EQUAL_RATIO))
        val escapeNeeded = hunted || (armedEnemies.isNotEmpty() && strikers.isEmpty())
        // темп сближения врага (0 — стоит, 1 — идёт на нас): запас выхода даёт ему фору только в этом темпе — фора «идёт
        // к выходу мгновенно» отвергала всякую цель при враге, стоящем дома, и армия весь матч сидела дома (стенд m1 scouts)
        run {
            val ec = centroidOf(armedEnemies)
            if (ec != null) { enemyDistHist.addLast(getRange(ec, ctx.ourCentroid)); while (enemyDistHist.size > APPROACH_WINDOW) enemyDistHist.removeFirst() } else enemyDistHist.clear()
            approachRate = if (enemyDistHist.size >= 2) ((enemyDistHist.first() - enemyDistHist.last()).toDouble() / (enemyDistHist.size - 1)).coerceIn(0.0, 1.0) else 0.0
        }
        if (escapeNeeded) refreshEscape(ctx, armedEnemies) else { escapeFlows.clear(); escapeTheirs.clear(); escapeNearest.clear(); evadeLeft = null }
        // враг близко (см. EVADE_RANGE) — уклонение раньше целей; далеко — цели с выходом, иначе безопасная точка
        val enemyClose = hunted && armedEnemies.any { getRange(it, ctx.ourCentroid) <= EVADE_RANGE }
        val evadeFirst = if (enemyClose && !annihilate && !contact) evadePoint(ctx, armedEnemies, strikers) else null
        // враг рядом (см. NEAR_RANGE) без нашего перевеса — не цель, а строй: армия, пошедшая за угловым флагом при
        // подходящем враге, была поймана колонной на марше (стенд m3 sleeper, t=529–540); флаги в это время — скаутам
        val holdLine = enemyNear && !pushing && !annihilate && !stalled
        val interceptObjective: Objective? = interceptFlag?.takeIf { !it.ours && captureAllowed(ctx, it) }?.let { f ->
            val group = strikers.ifEmpty { mobileArmy }
            val flow = flowTo(ctx, f.pos)
            Objective(f, emptyList(), 1.0, group.maxOfOrNull { pathTicks(it, flow, it.x * 100 + it.y) } ?: 0)
        }
        val objective = if (annihilate || evadeFirst != null || (holdLine && interceptObjective == null)) null else interceptObjective ?: chooseFlagObjective(ctx, strikers.ifEmpty { mobileArmy }, pushRatio, hunted)
        val evadeTo = evadeFirst ?: (if (hunted && !annihilate && !contact && objective == null) evadePoint(ctx, armedEnemies, strikers) else null)
        val evade = evadeTo != null
        if (!evade) evadeTarget = null
        val retreat = armedEnemies.isNotEmpty() && !annihilate && objective == null && !evade && enemyNear && weaker && retreatFeasible
        // ОТВЕРГНУТО стендом (v58-опыт): снимать простой, когда паритет не пускает ни к одному флагу (матч 133: «марш не сдвинулся —
        // флаги до 479» при 1,32 к лагерю на D5, obj=- все 300 тиков, 18 против 7 в тик). На стенде m31 camp снятый на 536-м простой
        // дал 700 тиков ANNIHILATE pushing при 3679 против 1209 без единого убитого (центры армий в одной клетке, reach 0/5) —
        // 17133:23618 вместо «стёрт на 776-м», где к нему армию довела ЦЕЛЬ-ФЛАГ D5 (412–536). Толчок к стоящему блобу не
        // сближается — открытая находка матчей 70 и 133
        val newPosture = when {
            annihilate -> Posture.ANNIHILATE
            objective != null -> Posture.FLAG
            evade -> Posture.EVADE
            retreat -> Posture.RETREAT
            else -> Posture.HOLD
        }
        objectiveFlagId = objective?.flag?.id
        if (newPosture != Posture.RETREAT) retreatTarget = null
        val retreatTo = if (newPosture == Posture.RETREAT) retreatPoint(ctx) else null
        // ДЕРЖИ, ЧТО ДЕРЖИШЬ (v66): армия, стоящая на своём флаге при враге рядом, постом считает этот флаг, а не дальний пост.
        // Матч 159 (けろびー, пятнадцатый проигрыш фермеру 12009:24099): он кайтит вокруг D5 при 4075 против 3084, при huntable 0
        // армия уходила в HOLD к посту (11,68) за сорок клеток, он возвращался на D5; на 800-м и 1000-м мы стояли на D5 (хранитель
        // melee_1 на 1009-м снят на 1011-м — девять его вооружённых в десяти клетках не пикет) и снова уходили. «Держать линию,
        // где стоит» стенд отверг (v42: 58 хуже / 48 лучше — возврат к посту добивает отбитый рывок); здесь — только свой флаг под
        // ногами
        val standingFlag = if (USE_HOLD_OWN_FLAG && enemyNear) ctx.flags.firstOrNull { it.ours && getRange(it.pos, ctx.ourCentroid) <= POST_STANDOFF } else null
        val post = standingFlag?.pos ?: if (interceptFlag?.ours == true) interceptFlag.pos else postPoint(ctx)
        val postureKey = "$newPosture:${objectiveFlagId ?: ""}"
        if (DEBUG_LOG && (postureKey != postureLogged || getTicks() % (LOG_EVERY * 10) == 0)) {
            postureLogged = postureKey
            println("posture: $newPosture t=${getTicks()} our=${ours.toInt()} enemy=${theirs.toInt()} near=$enemyNear contact=$contact pushing=$pushing huntable=${huntable.size}/${combatEnemies.size} retreatFeasible=$retreatFeasible strikers=${strikers.size}/${army.size} " +
                "obj=${objective?.let { "(${it.flag.pos.x},${it.flag.pos.y})${typeChar(it.flag.type)}${it.flag.score} pack=${it.pack.size} travel=${it.travel} v=${(it.value * 100).toInt()}" } ?: "-"} " +
                "retreatTo=${retreatTo?.let { "(${it.x},${it.y})" } ?: "-"} evadeTo=${evadeTo?.let { "(${it.x},${it.y})" } ?: "-"} approach=${(approachRate * 100).toInt()} post=(${post.x},${post.y}) behind=$behindOnScore/$behindTicks hunt=$huntingThreat")
        }
        posture = newPosture

        // ---- общие цели ----
        val centroid = ctx.ourCentroid
        val ourHalfCombat = armedEnemies.filter { DistanceMap.inOurHalf(it.x, it.y) }
        val ourHalfSoft = enemyCreeps.filter { c -> combatEnemies.none { it.id == c.id } && DistanceMap.inOurHalf(c.x, c.y) }
        fun arrivalOf(c: Creep) = arrivalById[c.id] ?: Int.MAX_VALUE / 2
        val threat = ourHalfCombat.filter { catchable(it, chasers) }.minWithOrNull(compareBy<Creep>({ arrivalOf(it) }, { getRange(it, centroid) }))
        // рейдер: чужой безоружный на нашей половине — тот, что ближе к нашему флагу (захватчик идёт к нему); гонимся,
        // только если стрелки бьют стаю вокруг него: без этой проверки армия гналась за безоружным остовом к
        // стоявшей за ним армии врага и вошла в бой при 0.77 (матч 3, t=100)
        val raider = ourHalfSoft.minByOrNull { r -> minOf(getRange(r, centroid), ctx.flags.filter { !it.theirs }.minOfOrNull { getRange(r, it.pos) } ?: 99) }
            ?.takeIf { r ->
                // стая рейдера — и те, кто дойдёт до него не позже нас: скаут в 12 клетках впереди своей армии был
                // «без охраны», и армия вышла из дома ему навстречу — прямо под удар всей армии врага (матч 6, t=50)
                val field = flowTo(ctx, r)
                val ourTravel = chasers.map { pathTicks(it, field, it.x * 100 + it.y) }.filter { it < Int.MAX_VALUE / 4 }.maxOrNull() ?: Int.MAX_VALUE / 4
                val pack = packAt(ctx, r, field, ourTravel)
                catchable(r, chasers) && (pack.isEmpty() || (strikers.isNotEmpty() && ourPowerOf(strikers, pack) >= enemyPowerOf(pack, strikers) * PUSH_RATIO))
            }
        // охота на угрозу на нашей половине — решение группы с гистерезисом: стрелки против всей стаи у угрозы
        huntingThreat = posture != Posture.RETREAT && posture != Posture.EVADE && threat != null && strikers.isNotEmpty() && run {
            val field = flowTo(ctx, threat)
            val ourTravel = strikers.map { pathTicks(it, field, it.x * 100 + it.y) }.filter { it < Int.MAX_VALUE / 4 }.maxOrNull() ?: Int.MAX_VALUE / 4
            val pack = combatEnemies.filter { getRange(it, threat) <= ENGAGE_RANGE + RANGED_RANGE || (!stationary(it) && pathTicks(it, field, it.x * 100 + it.y) <= ourTravel) }
            val o = ourPowerOf(strikers, pack)
            val t = enemyPowerOf(pack, strikers)
            o >= t * (if (huntingThreat) PUSH_RELEASE_RATIO else PUSH_RATIO) &&
                (fightCost(pack, strikers) <= (strikers.maxOfOrNull { speedSlack(it) } ?: 0) || inContact(pack, strikers))
        }
        aggressiveIds.retainAll { id -> army.any { it.id == id } }
        rallyingIds.retainAll { id -> army.any { it.id == id } }
        engagingIds.retainAll { id -> army.any { it.id == id } }
        holdSince.keys.retainAll { id -> army.any { it.id == id } }
        impatientIds.retainAll { id -> army.any { it.id == id } }
        lastHits.keys.retainAll { id -> army.any { it.id == id } }
        lastCell.keys.retainAll { id -> army.any { it.id == id } }

        val enemyPositions = enemyCreeps.mapTo(HashSet()) { it.x * 100 + it.y }
        val blockedSet: Set<Int> = ctx.blocked.mapTo(HashSet()) { it.x * 100 + it.y } + ctx.flagCells
        val meleeEnemies = enemyCreeps.filter { InfluenceMap.profileOf(it).melee > 0.0 }
        // боеспособные: вооружённые и лекари — фокус, контакт и местные группы считаются по ним, раненые не в счёт
        val combatArmy = army.filter { hasWeapon(it) || hasHeal(it) }

        // фокус-файр: добиваемые за тик -> наибольшая угроза на хит (урон, который враг СЕЙЧАС наносит нам, плюс
        // его лечение, делённые на его хиты: мили вплотную за 1000 хитов снимает 90, стрелок за 800 — 40, лекарь
        // за 600 — 36; «лекари первыми» без учёта хитов вело огонь мимо мили, который резал наш строй)
        val inFireRange = enemyCreeps.filter { e -> combatArmy.any { it.getRangeTo(e) <= RANGED_RANGE } }
        // остовы (без оружия и лечения) — вне пула, пока есть боевые. Матч 22: разоружённый M6 с 542 хитами простоял
        // 25 тиков в 2–4 клетках от наших стрелков необстрелянным и был вылечен обратно в M8A8, пока пять его стрелков
        // добивали наших. ДВА способа перенести на него огонь ОТВЕРГНУТЫ стендом: «отрастающая угроза» (мёртвые части
        // оружия × 0.5 в угрозе любой цели) проиграла m9 hunter, m3 army и все рубки sleeper; «остов, добиваемый за
        // два залпа, — сразу после добиваемых за тик» проиграла m3 army, рубки sleeper и m18 spread. Огонь по живой
        // угрозе, а не по раненым, — то, на чём стенд стоит; остов на лечении врага — открытая находка
        val focusPool = inFireRange.filter { e -> combatEnemies.any { it.id == e.id } }.ifEmpty { inFireRange }
        fun fireAvailableAt(e: Creep) = army.filter { it.getRangeTo(e) <= RANGED_RANGE }.sumOf { InfluenceMap.profileOf(it).ranged } +
            army.filter { it.getRangeTo(e) <= 1 }.sumOf { InfluenceMap.profileOf(it).melee }
        // лечение, которое враг получит на этой цели: вплотную — полное, на дистанции — треть (rangedHeal 4 против 12)
        fun healOn(e: Creep) = enemyCreeps.filter { h -> h.id != e.id && getRange(h, e) <= HEAL_RANGE }.sumOf { h -> val q = InfluenceMap.profileOf(h); if (getRange(h, e) <= 1) q.heal else q.heal / 3.0 }
        // дистанция каждого врага до ближайшего нашего боеспособного сейчас и тик назад — «идёт ли» (см. threatOf)
        val prevArmedRange = HashMap(lastArmedRange)
        lastArmedRange.clear()
        for (e in enemyCreeps) lastArmedRange[e.id] = combatArmy.minOfOrNull { getRange(e, it) } ?: 99
        fun threatOf(e: Creep): Double {
            val p = InfluenceMap.profileOf(e)
            // мили — полная угроза ВПЛОТНУЮ к нашему или в двух, когда ИДЁТ на нас (v41: дистанция до наших боеспособных
            // меньше, чем тик назад). В двух он считался живым на все 240 (в четыре стрелка) всегда, и в
            // стоячей линии наш огонь шёл в него: по реплеям трёх проигрышей при его вооружённом стрелке в трёх наши выстрелы
            // уходили в стрелка на 39 / 36 / 46 % (матчи 67, 53, 43), остальное в мили и лекарей; его — в наших стрелков на
            // 65 / 70 / 62 %. Его мили в 2–3 от наших за бой махнули 56 раз на четверых (0,06 в тик — 13 урона), его стрелки
            // дали 480 выстрелов (34 в тик на каждого); мили лечился и вставал обратно в строй, а стрелки жили вооружёнными
            // 875 крип-тиков против наших 413 — и выстрелов 535 против 258 при равной дисциплине (цель в трёх 67 % против
            // 55 %, фокус 0,73 против 0,72). Вошедший вплотную мили — 240 в тот же тик (фокус считается каждый тик), а в
            // двух он — скидка кайта, как и в трёх. Чистая скидка в двух (без «идёт») на гейте: линии (wing) лучше на
            // 1,4–9,9 тыс. очков, но против атакующих пять уничтожений стали лидерством (rush/nine/fourteen/block, m5 army):
            // идущий мили в двух вплотную уже в следующий тик, и тик его огня без фокуса — цена, которую стенд заметил
            val r = lastArmedRange[e.id] ?: 99
            val meleeLive = p.melee > 0.0 && (r <= 1 || (r <= MELEE_KEEP_RANGE && (prevArmedRange[e.id] ?: 99) > r))
            val rangedLive = p.ranged > 0.0 && combatArmy.any { getRange(e, it) <= RANGED_RANGE }
            // лекарь в угрозе — треть лечения ВСЕГДА (24 против 60 у стрелка): «живой» лекарь при раненом соседе весил 72 и
            // собирал четверть-треть нашего огня (матч 44: 66 из 192, матч 45: 46 из 175, при HEALER_VALUE 1.0), пока けろびー
            // тратил на лекарей 6–15 % и снимал наших стрелков (96 выстрелов по ним против наших 24 по его). Лекаря бьют,
            // когда его добить за тик (первый ярус фокуса) или когда в дальности нет вооружённых (focusOrder)
            return (if (meleeLive) p.melee else p.melee * MELEE_KITE_DISCOUNT) + (if (rangedLive) p.ranged else p.ranged * 0.5) +
                p.heal / 3.0 * HEALER_VALUE
        }
        // тики до убийства нашим огнём в дальности за вычетом их лечения на цели; бесконечность — цель не убиваема
        fun killTicks(e: Creep): Double {
            val net = fireAvailableAt(e) * InfluenceMap.takenOf(e) - healOn(e)
            return if (net <= 0.0) Double.POSITIVE_INFINITY else e.hits / net
        }
        // фокус: добиваемые за тик, затем наибольшая угроза, снимаемая за тик боя (угроза / тики до убийства), и лишь
        // потом угроза на хит — «угроза на хит» слала огонь в лекарей врага за строем, которых лечили друг друга
        // быстрее, чем мы били (стенд m2 rush: выигранный без потерь рывок стал разгромом)
        fun armedRanged(e: Creep?) = e != null && InfluenceMap.profileOf(e).ranged > 0.0
        // стволов, достающих цель (v70, см. USE_FOCUS_GUNS)
        fun gunsAt(e: Creep?) = if (e == null) 0 else combatArmy.count { hasRanged(it) && it.getRangeTo(e) <= RANGED_RANGE }
        val focusCmp = compareBy<Creep> { if (it.hits <= fireAvailableAt(it) * InfluenceMap.takenOf(it)) 1 else 0 }
            // стрелки первыми (v60, см. USE_FOCUS_RANGED_FIRST)
            .thenBy { if (USE_FOCUS_RANGED_FIRST && armedRanged(it)) 1 else 0 }
            // больше стволов (v70)
            .thenBy { if (USE_FOCUS_GUNS) gunsAt(it) else 0 }
            .thenBy { val t = killTicks(it); if (t.isInfinite()) 0.0 else threatOf(it) / t }
            // чистый урон по цели: наш огонь в дальности минус её лечение (вплотную — полное, на дистанции — треть). Когда
            // никого не убить (лечение везде не меньше огня), «угроза на хит» слала огонь в того, кого лечат три лекаря
            // вплотную; выше — цель, к которой лекари ДАЛЕКО (оператор, 05.09.2026: «лекари к ней далеки — не вылечат
            // близким хилом и потеряют ход») и которую достают больше наших стволов
            .thenBy { if (USE_FOCUS_NET) fireAvailableAt(it) * InfluenceMap.takenOf(it) - healOn(it) else 0.0 }
            .thenBy { threatOf(it) / it.hits.coerceAtLeast(1) }
            .thenByDescending { it.hits }
            .thenByDescending { getRange(it, centroid) }
        val focusBest = focusPool.maxWithOrNull(focusCmp)
        // ЛИПКИЙ фокус (v45): цель держится, пока жива с оружием или лечением и в шаге от досягаемости хоть одного нашего стрелка;
        // сменяется на ту, что добивается за тик. Замер по реплеям (матчи 78, 73, 67): наибольшее число наших выстрелов в ОДНУ
        // цель за тик — 1 в 57 тиках из 111, 2 в 42, 3 в 10, четыре и больше в 2 (1 %); у Coldkimchi 4+ в 11 % тиков, у けろびー
        // в 14 %. При 216 лечения в тик пробивают только четыре-пять стволов в одну цель — мы этого не делали почти никогда:
        // цель фокуса менялась, ряд стоял поперёк оси, каждый стрелок доставал своего (оператор: «нет фокус-файра — каждый
        // рэндж стреляет в своего соперника»)
        val focusPrev = focusId?.let { id -> focusPool.firstOrNull { it.id == id } }
        val killableNow = focusBest != null && focusBest.hits <= fireAvailableAt(focusBest) * InfluenceMap.takenOf(focusBest)
        // …и не к мили, чья угроза схлопнулась (v49): матч 91 (Coldkimchi, 430 тиков боя) — его мили тычет вплотную (угроза 240,
        // фокус на нём), отходит к лекарям, и фокус на нём держится: 395 выстрелов в мили под 727 его лечений вплотную, 101 в
        // стрелков (35 % при стрелке в трёх, у него 71 %). Мили держится, пока вплотную или идёт (см. threatOf); «отпускать
        // всякую неубиваемую цель, пока есть убиваемая» ОТВЕРГНУТО стендом — фокус перескакивал при каждом шаге его лекаря
        // (125/125, но 19 хуже / 12 лучше: screen+flagless m32 −16145, block+flagless m32 −7640, camp m34 −9294, кайтеры медленнее ×7)
        val prevDead = USE_FOCUS_RELEASE && focusPrev != null && InfluenceMap.profileOf(focusPrev).let { it.melee > 0.0 && it.ranged == 0.0 } &&
            (lastArmedRange[focusPrev.id] ?: 99).let { r -> r > 1 && !(r <= MELEE_KEEP_RANGE && (prevArmedRange[focusPrev.id] ?: 99) > r) }
        // липкость уступает стрелку (v60): прежняя цель не стрелок, а лучшая — вооружённый стрелок
        val rangedNow = USE_FOCUS_RANGED_FIRST && armedRanged(focusBest) && !armedRanged(focusPrev)
        // липкость уступает цели, которую достают на FOCUS_GUNS_SWITCH стволов больше (v70)
        val moreGuns = USE_FOCUS_GUNS && focusBest != null && focusPrev != null && gunsAt(focusBest) >= gunsAt(focusPrev) + FOCUS_GUNS_SWITCH
        val focusTarget = if (USE_FOCUS_STICKY && focusPrev != null && !killableNow && !prevDead && !rangedNow && !moreGuns && InfluenceMap.profileOf(focusPrev).let { it.melee + it.ranged + it.heal > 0.0 } &&
            combatArmy.any { hasRanged(it) && getRange(it, focusPrev) <= RANGED_RANGE + 1 }) focusPrev else focusBest
        focusId = focusTarget?.id
        // ранжир для бойца, у которого цель фокуса вне дальности: ПЕРВАЯ по ранжиру цель в его дальности, а не «самый раненый в
        // дальности» — тот размазывал огонь: 1.91 цели в тик, 66 из 192 выстрелов в лекарей при HEALER_VALUE 1.0 (матч 44)
        val focusOrder = focusPool.sortedWith(focusCmp.reversed())
        val occupantAt = HashMap<Int, Creep>()
        for (c in ctx.active) occupantAt[c.x * 100 + c.y] = c
        // добить: цель армии — ближайший к центру армии боевой враг (по пути); в бою ПО КОНТАКТУ (без перевеса) —
        // только враг, который УЖЕ у нас в руках (в RANGED_RANGE + 2 от своих): стая «в 11 клетках» включала основную
        // массу врага, и контакт с одним забредшим мили увёл армию с дома на неё — бой при 0.97 проигран 12:1 (матч 13)
        val contactPack = combatEnemies.filter { e -> combatArmy.any { getRange(e, it) <= RANGED_RANGE + 2 } }
        // расстояние до КАЖДОГО кандидата в добычу мерилось своим полем BFS, а поля считаются под бюджетом
        // (см. BFS_BUDGET): сверх него кандидат получает ограниченное (NEAR_FLOW) или устаревшее поле, и «до него
        // неизвестно» читается как «бесконечно далеко». Сравнения кандидатов при этом нет вовсе — есть сравнение
        // качества полей. Стенд m18 roost: два скаута по разным углам карты, цель армии мигала (13,49)/(90,8) КАЖДЫЙ
        // ТИК, армия шагала туда-сюда и простояла так до конца матча — армия врага перебита к 203-му, а матч проигран
        // по очкам 17683:24331; в живом матче 25 армия ровно так же простояла 990 тиков при добыче в 11 клетках.
        // ОДНО поле от центра армии меряет всех кандидатов в одних единицах и в один тик — и стоит дешевле, чем поле
        // на каждого кандидата
        val preyField by lazy { flowTo(ctx, centroid) }
        // враг НА клетке вражеского флага недостижим по полю (такая клетка в нём стена) — читаем по соседней: нам
        // нужно дойти ДО него, а не встать на него
        fun travelTo(e: Creep): Int {
            var best = -1
            for (dx in -1..1) for (dy in -1..1) {
                val x = e.x + dx; val y = e.y + dy
                if (x !in 0..99 || y !in 0..99) continue
                val d = preyField[x * 100 + y]
                if (d >= 0 && (best < 0 || d < best)) best = d
            }
            return if (best < 0) Int.MAX_VALUE / 2 else best
        }
        // за недостижимым не гонимся: прежде «недостижим» и «очень далеко» были одним числом, и армия шла на цель,
        // до которой нет пути
        fun nearestPrey(list: List<Creep>): Creep? =
            list.filter { travelTo(it) < Int.MAX_VALUE / 4 }.minByOrNull { travelTo(it) }
        val prey = when {
            posture != Posture.ANNIHILATE -> null
            sweep -> nearestPrey(enemyCreeps)
            pushing -> nearestPrey(huntable)
            else -> nearestPrey(contactPack.filter { catchable(it, chasers) })
        }
        val armedCentroid = centroidOf(mobileArmy.filter { hasWeapon(it) }.ifEmpty { army }) ?: centroid
        // захватчик флага-цели — ближайший к флагу ВООРУЖЁННЫЙ член группы (одной клетки на всех не хватит; лекарь
        // ходит за подопечным, и назначенный захватчиком лекарь тысячу тиков стоял рядом с флагом — стенд greedy)
        val objectiveCapturer = objective?.let { o -> mobileArmy.filter { hasWeapon(it) }.ifEmpty { mobileArmy }.minByOrNull { getRange(it, o.flag.pos) }?.id }
        // флаг рядом (не наш, свободный, без врага в дальности, разрешён) — на него шагает ближайший из наших
        val grabberOf = HashMap<String, String>()
        for (f in ctx.flags) {
            if (f.ours || f.occupant != null || f.id == objectiveFlagId) continue
            if (combatEnemies.any { getRange(it, f.pos) <= RANGED_RANGE + 1 }) continue
            if (!captureAllowed(ctx, f)) continue
            val near = mobileArmy.filter { getRange(it, f.pos) <= 3 }.minByOrNull { getRange(it, f.pos) } ?: continue
            grabberOf[near.id] = f.id
        }

        // построение перед контактом (см. FORM_RANGE): авангард — ближайший к врагу ходячий вооружённый; готовность —
        // доля вооружённых в RALLY_RANGE от него, собравшихся в FORM_RANGE; клетки под огнём — в дальности стрелка
        // враг здесь — С БОЕМ (см. threatening): построение собирается перед огнём, а у одинокого лекаря огня нет. Уцелевший
        // лекарь врага шёл за армией в семи клетках, «авангардом» становился ЗАДНИЙ боец, и построение тянуло армию назад,
        // а цель — вперёд: шаг туда, шаг обратно 140 тиков у (20,21) при флаге-цели в 30 (стенд m13 rush, v30)
        val formers = mobileArmy.filter { hasWeapon(it) }
        // авангард — только из массы (см. MASS_RANGE): оторвавшийся крип не точка сбора
        val formMass = formers.filter { getRange(it, armedCentroid) <= MASS_RANGE }.ifEmpty { formers }
        // авангард есть, только пока враг с боем в досягаемости броска от кого-то из строя: авангард «против врага где-то на
        // карте» при одиноком лекаре врага в одиннадцати клетках давал построение, которому не собраться (штраф за соседей
        // отталкивал мили от авангарда в блобе) и не дождаться терпения (оно считается по врагу с боем) — армия простояла
        // тысячу тиков в 25 клетках от флага-цели (стенд m30 block, v30)
        val formVan = if (armedEnemies.none { e -> formers.any { getRange(e, it) <= ENGAGE_RANGE + RANGED_RANGE } }) null
            else formMass.minWithOrNull(compareBy<Creep>({ f -> armedEnemies.minOf { getRange(f, it) } }, { it.id }))
        val formationGathered = formVan == null || run {
            val near = formers.filter { getRange(it, formVan) <= RALLY_RANGE }
            val needed = maxOf(2, ceil(FORM_SHARE * near.size).toInt())
            near.count { getRange(it, formVan) <= FORM_RANGE } >= needed
        }
        val formWaiting = formVan != null && !formationGathered && armedEnemies.any { e -> formers.any { getRange(e, it) <= ENGAGE_RANGE + RANGED_RANGE } }
        if (!formWaiting) formWaitSince = -1 else if (formWaitSince < 0) formWaitSince = getTicks()
        val formationReady = formationGathered || (formWaitSince >= 0 && getTicks() - formWaitSince >= FORM_PATIENCE)
        // досягаемость врага для лекаря и раненого (см. reachCells): стрелок бьёт на 3, мили шагнёт и ударит на 2. Тело
        // лекаря HHHHHHMMMMMM — лечение впереди, и первое же попадание снимает 12 лечения в тик навсегда; наши лекари
        // входили в зону огня к подопечному и к 130-му были M6H4/M6H2, лекари врага за строем не получили ни царапины
        // и отрастили ему армию (матчи 14–15). Лекарь в зону не входит, изнутри уходит; раненые приходят к нему сами.
        val reachCells = HashSet<Int>()
        for (e in combatEnemies) {
            val q = InfluenceMap.profileOf(e)
            val r = if (q.ranged > 0.0) RANGED_RANGE else if (q.melee > 0.0) 2 else 0
            if (r == 0) continue
            for (dx in -r..r) for (dy in -r..r) {
                val x = e.x + dx; val y = e.y + dy
                if (x in 0..99 && y in 0..99) reachCells.add(x * 100 + y)
            }
        }
        // в контактном бою лекарь избегает только мили (2 клетки): «вне досягаемости стрелков» выкидывало слот тыла из
        // ряда back+1, лекари стояли в 4–6 клетках за фронтом, и мили гибли без лечения, пока лекари врага стояли у своей
        // линии под нашим огнём (матч 21, t=68–84: четыре мили за шестнадцать тиков, ни одного лечения)
        // только вплотную к мили (клетка в 2 — это ряд сразу за нашим фронтом, свой мили между ними)
        val meleeReachCells = HashSet<Int>()
        for (e in combatEnemies) {
            if (InfluenceMap.profileOf(e).melee <= 0.0) continue
            for (dx in -1..1) for (dy in -1..1) {
                val x = e.x + dx; val y = e.y + dy
                if (x in 0..99 && y in 0..99) meleeReachCells.add(x * 100 + y)
            }
        }
        val reachNow = if (contact) meleeReachCells else reachCells
        val fireCells = HashSet<Int>()
        for (e in combatEnemies) for (dx in -RANGED_RANGE..RANGED_RANGE) for (dy in -RANGED_RANGE..RANGED_RANGE) {
            val x = e.x + dx; val y = e.y + dy
            if (x in 0..99 && y in 0..99) fireCells.add(x * 100 + y)
        }

        val healersAlive = army.any { !hasWeapon(it) && hasHeal(it) && canMove(it) }
        // строй рядами в бою по контакту (см. USE_BLOCK); при перевесе (добивание) — прежняя охота
        val slotOf = HashMap<String, Position>()
        val blockOn = USE_BLOCK && posture == Posture.ANNIHILATE && !pushing && combatEnemies.isNotEmpty() && strikers.isNotEmpty()
        // прижим (см. USE_PRESS, PRESS_PATIENCE): линия врага стоит — контакт, его огонь достаёт наших, и ни один его мили не
        // в MELEE_HOLD_RANGE + 1 от наших вооружённых; включившись, держится, пока есть контакт и строй
        // «их мили в бою» — только ВПЛОТНУЮ к нашему вооружённому: в 2–3 клетках это экран, не атака. Матч 43 (けろびー v2):
        // его мили сорок тиков стояли в двух-трёх от наших и не били (вплотную 7 % крип-тиков, 8 ударов за бой), его стрелки в
        // трёх снимали наших мили по одному (r→melee 132 из 180), а прижим считал «мили в трёх» атакой и молчал до 104-го
        val theirMeleeIn = combatEnemies.any { e -> InfluenceMap.profileOf(e).melee > 0.0 && combatArmy.any { hasWeapon(it) && getRange(e, it) <= 1 } }
        val underTheirFire = combatArmy.any { InfluenceMap.damageAt(it.x, it.y, combatEnemies) > 0.0 }
        // «их мили идут» (см. PRESS_CLOSING): дистанция их мили до наших вооружённых за окно терпения
        val theirMeleeDist = combatEnemies.filter { InfluenceMap.profileOf(it).melee > 0.0 }
            .minOfOrNull { e -> combatArmy.filter { hasWeapon(it) }.minOfOrNull { getRange(e, it) } ?: 99 } ?: 99
        if (contact) meleeDistHist.addLast(theirMeleeDist) else meleeDistHist.clear()
        while (meleeDistHist.size > PRESS_PATIENCE + 1) meleeDistHist.removeFirst()
        val theirMeleeClosing = meleeDistHist.size > PRESS_PATIENCE && meleeDistHist.first() - meleeDistHist.last() >= PRESS_CLOSING
        // «армии сближаются» (v47, оператор: «признак по сближению центров армий»): дистанция между центрами ВООРУЖЁННЫХ
        // армий за окно терпения сократилась не меньше PRESS_CLOSING — атака; стоит — стоячий бой (см. standingNow). Признак
        // «его мили не вплотную» выключал расстановку ровно в боях с Coldkimchi (его мили лезут вплотную к стрелкам), а
        // «его мили не идут» (v43f) брал и остановившуюся атаку — центры армий отличают одно от другого
        val ourArmedC = centroidOf(combatArmy.filter { hasWeapon(it) }.map { InfluenceMap.cell(it.x, it.y) })
        val theirArmedC = centroidOf(armedEnemies.map { InfluenceMap.cell(it.x, it.y) })
        if (contact && ourArmedC != null && theirArmedC != null) centreDistHist.addLast(getRange(ourArmedC, theirArmedC)) else centreDistHist.clear()
        while (centreDistHist.size > PRESS_PATIENCE + 1) centreDistHist.removeFirst()
        val armiesClosing = centreDistHist.size > PRESS_PATIENCE && centreDistHist.first() - centreDistHist.last() >= PRESS_CLOSING
        // их мили на подходе — в (MELEE_HOLD_RANGE + 2 .. ENGAGE_RANGE] от наших вооружённых — это не стоячая линия и не пустое
        // место: матч 56 (G1N6ERbreadMan) — прижим на 115-м при его мили в 4–7, через три тика они вошли в нашу пачку у своих же
        // стрелков (его 51 удар против наших 24, a→ranged 31), пять наших потеряны за двадцать тиков. Прижим — линии, чьи мили
        // либо у неё (Kero v2, Coldkimchi: в 2–3 и не бьют), либо далеко; подходящих строй ждёт — они входят в его фокус сами
        val theirMeleeMid = combatEnemies.any { e ->
            InfluenceMap.profileOf(e).melee > 0.0 &&
                (combatArmy.filter { hasWeapon(it) }.minOfOrNull { getRange(e, it) } ?: 99).let { it > MELEE_HOLD_RANGE + 2 && it <= ENGAGE_RANGE }
        }
        standoffTicks = if (contact && underTheirFire && !theirMeleeIn && !theirMeleeClosing && !theirMeleeMid) standoffTicks + 1 else 0
        pressing = USE_PRESS && blockOn && contact && (standoffTicks >= PRESS_PATIENCE || pressing)
        val pressOn = pressing
        // «цель уходит» (см. PRESS_GIVEUP): за два тика прижима дистанция от наших мили до неё не сократилась
        if (blockOn) {
            val ourMelee = combatArmy.filter { isMelee(it) && !hasRanged(it) && hasMelee(it) }
            for (e in combatEnemies) {
                val d = ourMelee.minOfOrNull { getRange(e, it) } ?: continue
                if (d > PRESS_RANGE + 1) { pressChase.remove(e.id); continue }
                val h = pressChase.getOrPut(e.id) { ArrayDeque() }
                h.addLast(d)
                while (h.size > 3) h.removeFirst()
                if (h.size == 3 && d > 1 && h.last() >= h.first()) {
                    pressGiveUp[e.id] = getTicks() + PRESS_GIVEUP
                    h.clear()
                    if (DEBUG_LOG) println("press t=${getTicks()}: ${e.id} keeps its distance — not pressed for $PRESS_GIVEUP ticks")
                }
            }
        } else pressChase.clear()
        pressGiveUp.entries.removeAll { it.value <= getTicks() }
        if (DEBUG_LOG && pressOn && standoffTicks == PRESS_PATIENCE) println("press t=${getTicks()}: the enemy line has stood at range for $PRESS_PATIENCE ticks under fire — the pack goes in")
        // стрелки впереди (см. USE_RANGED_FRONT) — только против линии, которая СТОИТ: признак прижима и дистанция до центра
        // врага за APPROACH_WINDOW не выросла. Уходящий (кайтер стенда, остаток) — прежний строй с мили впереди: стрелки во
        // главе погони не догоняют никого, а мили за их спиной и подавно (m11 kite: уничтожение на 395-м → лидерство, m28
        // farm+weak красный)
        val enemyRetreating = enemyDistHist.size >= 2 && enemyDistHist.last() > enemyDistHist.first()
        if (blockOn) {
            // расстановка (см. USE_PLAN) — только в СТОЯЧЕМ бою (признак прижима: линия стоит под огнём, его мили не идут);
            // против атаки и в погоне — ряды за передним мили: свободная расстановка рыхлее рядов, и с ней остаток
            // атакующего уходил, а кайтер добивался позже (гейт v43c: block/nine/rush «уничтожение → лидерство» ×10, кайтеры
            // медленнее ×7 при wing ×4, block+flagless ×2 и farm+weak m33 +7561 лучше)
            val standoffNow = pressOn && !enemyRetreating
            // ОТВЕРГНУТО: расстановка и в контакте, пока его мили не идут на нас (!theirMeleeClosing) — ради матча 73 (Coldkimchi:
            // его мили подходили к нашим стрелкам и лекарям вплотную, били по 240 и отходили — 46 ударов против наших 7, а
            // прижим требует «его мили не вплотную», и расстановка была выключена ровно в этом бою): едва атака врага встаёт,
            // бой берёт расстановка, и остаток уходит — 123/125, m28 wing и m31 camp проиграны, против прижима-только 21 хуже /
            // 16 лучше. Прилипший к стрелку мили — дело нашего мили (см. poker в engage), не строя
            // стоячий бой по центрам армий (v47): контакт держится дольше окна терпения, центры вооружённых армий не сближаются,
            // враг не отходит — расстановка; атака (центры сближаются) и погоня (враг отходит) — ряды
            // ...и это ЛИНИЯ, а не рубка (v62): его вооружённый мили не ближе MELEE_HOLD_RANGE + 1 к нашим вооружённым. Матч 150
            // (боевой けろびー, армия стёрта к 180-му, форма матча 140): контакт на 70-м, центры не сближались (его мили среди наших),
            // «стоячий бой» → расстановка ставила стрелков колонной x=81 в 1–3 клетках от его стрелков, к 80-му двое наших стрелков
            // стояли уже за его линией на клетках, равноудалённых от обоих центров (v61 их не режет); ярусы «подальше от его мили» в
            // рубке ведут сквозь его строй. Прижим (standoffNow) это условие и так несёт; стоячий бой по центрам (v47) — нет
            // РУБКА — его мили ВПЛОТНУЮ, не «в трёх» (v64): линия Coldkimchi держит мили в 2–3 от наших и не рубит (матч 153, восьмое
            // поражение: 2:699 и 3:1431 крип-тиков его мили, 61 удар за 700 тиков боя) — по «в трёх» v62 расстановка была выключена
            // весь бой, ряды planBlock ставили стрелков за передним мили, и наш огонь (1611 выстрелов против его 1428) шёл по
            // разным целям: 4+ в одну цель 9 тиков против его 44 при 216 лечения в тик на цели с обеих сторон
            val meleeBrawl = theirMeleeIn
            val standingNow = contact && centreDistHist.size > PRESS_PATIENCE && !armiesClosing && !enemyRetreating && !meleeBrawl
            val planNow = USE_PLAN && (standoffNow || standingNow)
            if (planNow) planFight(mobileArmy, combatEnemies, armedEnemies, enemyCreeps, slotOf, focusTarget)
            else planBlock(mobileArmy, combatEnemies, armedEnemies, slotOf, rangedRow = !(pressOn && USE_PRESS_RING), standoff = standoffNow, focusTarget = focusTarget)
        }
        for (creep in army) {
            val mobile = strikers.any { it.id == creep.id }
            val healer = !hasWeapon(creep) && hasHeal(creep)
            val slot0 = slotOf[creep.id]
            val keeper = creep.id in keeperIds
            // раненый (без оружия и лечения, в армии по решению выше): ходит за ближайшим лекарем, в строй не входит
            val wounded = !healer && !hasWeapon(creep)
            // ротация (см. ROTATE_OUT): с гистерезисом, чтобы боец не дёргался у порога
            val rotating = !healer && hasWeapon(creep) && healersAlive && run {
                val weapons = creep.body.count { it.type == ATTACK || it.type == RANGED_ATTACK }
                val live = creep.body.count { (it.type == ATTACK || it.type == RANGED_ATTACK) && it.hits > 0 }
                val frac = if (weapons == 0) 1.0 else live.toDouble() / weapons
                if (creep.id in rotatingIds) { if (frac >= ROTATE_IN) { rotatingIds.remove(creep.id); false } else true }
                else if (frac < ROTATE_OUT) { rotatingIds.add(creep.id); true } else false
            }
            val support = healer || wounded
            val nearestEnemyRange = combatEnemies.minOfOrNull { getRange(creep, it) } ?: 99
            val localAllies = combatArmy.filter { getRange(creep, it) <= (if (posture == Posture.ANNIHILATE || posture == Posture.FLAG) ENGAGE_RANGE else RANGED_RANGE + 1) }
            val localEnemies = combatEnemies.filter { getRange(creep, it) <= ENGAGE_RANGE + RANGED_RANGE }
            val ratio = if (creep.id in aggressiveIds) LOCAL_ENTER_RATIO else PUSH_RATIO
            val ghost = run {
                val prev = lastHits[creep.id]
                val cell = lastCell[creep.id]
                if (prev == null || cell == null) 0 else {
                    val lost = prev - creep.hits
                    var explained = 0.0
                    val taken = InfluenceMap.takenOf(creep)
                    for (s in prevShooters) {
                        val d = maxOf(abs(s.cell / 100 - cell / 100), abs(s.cell % 100 - cell % 100))
                        if (d <= RANGED_RANGE) explained += s.ranged * taken
                        if (d <= 1) explained += s.melee * taken
                    }
                    if (lost > explained + 1.0) lost else 0
                }
            }
            if (ghost > 0 && DEBUG_LOG && getTicks() - (ghostLogged[creep.id] ?: -100) >= 10) {
                ghostLogged[creep.id] = getTicks()
                val nearest = combatEnemies.minOfOrNull { getRange(creep, it) } ?: -1
                println("ghost damage t=${getTicks()}: ${creep.id} -$ghost at (${creep.x},${creep.y}) hits=${creep.hits} nearestCombat=$nearest — источник не виден")
            }
            // локальный перевес: бойцы, способные стрелять по той же цели через тик-другой, против врагов в их
            // досягаемости; цена боя — по ГРУППЕ (самый большой запас хода), в контакте цена больше не гейт
            val localAggressive = when {
                posture == Posture.RETREAT || posture == Posture.EVADE -> inContact(localEnemies, localAllies) && ourPowerOf(localAllies, localEnemies) >= enemyPowerOf(localEnemies, localAllies) * ratio
                // добивание: армия в целом сильнее (или в контакте без отхода), но ЯВНО слабейшая на месте группа
                // отходит к массе — «всегда агрессивен» посылал четверых на двенадцать (матч 2 на стенде). Вход в
                // бой при 0.9 (при равных силах никто не вступал в бой — рывок врага кончался ничьёй), выход — только
                // при разгроме на месте (ANNIHILATE_HOLD_RATIO): в гуще боя местный счёт скачет, и бойцы по одному
                // «отходили к центру» и гибли поодиночке (стенд rush 7:2 против прежних 0:12)
                // отходить к массе есть смысл, только если масса не здесь: когда рядом больше половины армии, это и
                // есть масса, и «отход к центру» был шагом на месте под ударами (матч 3, t=140–280: армия из
                // семи-восьми «отходила к центру» сто сорок тиков и потеряла всех по одному, не стреляя в ответ)
                posture == Posture.ANNIHILATE -> !USE_LOCAL_ANNIHILATE || localEnemies.isEmpty() || localAllies.size * 2 >= combatArmy.size ||
                    ourPowerOf(localAllies, localEnemies) >= enemyPowerOf(localEnemies, localAllies) * (if (creep.id in aggressiveIds) ANNIHILATE_HOLD_RATIO else LOCAL_ENTER_RATIO)
                localEnemies.isEmpty() -> true
                // без боевого своего в четырёх клетках (раненый один) запаса хода нет: maxOf пустого списка бросал
                // NoSuchElementException КАЖДЫЙ тик до конца матча — армия стояла 1500 тиков после выигранного боя
                // (стенд m19 nine, v30; в v29 то же падало в m8 rush t=115–120 и m28 wing t=1200, стенд этого не считал)
                else -> ourPowerOf(localAllies, localEnemies) >= enemyPowerOf(localEnemies, localAllies) * ratio &&
                    (fightCost(localEnemies, localAllies) <= (localAllies.maxOfOrNull { speedSlack(it) } ?: 0) || inContact(localEnemies, localAllies))
            }
            if (localAggressive) aggressiveIds.add(creep.id) else aggressiveIds.remove(creep.id)
            // бросок — только на врага «с боем» (см. threatening): одинокий лекарь врага в восьми клетках был целью бойца,
            // который ждал по сплочению группу, а группа ждала его как отставшего на пути к флагу — 1500 тиков (m1 rush)
            // бросок — только в строю: построение готово и не меньше двух вооружённых в FORM_RANGE; одиночный мили, ушедший
            // вперёд на стрелков врага, погиб за восемь тиков, пока остальные держали построение (матч 14, t=71–78)
            val inLine = !USE_INLINE || (formationReady && combatArmy.count { it.id != creep.id && hasWeapon(it) && getRange(creep, it) <= FORM_RANGE } >= 2)
            // при бесплодной охоте (см. STALL_TICKS) броска нет: висящие крипы россыпи «ловимы» (не уходят стабильно), и
            // каждый наш крип танцевал со своим соседом вместо марша к флагу-цели (стенд m19 spread, travel=23 четыреста тиков)
            // «держит линию» — про мили В ЛИНИИ, а не про любого мили в бою: без этого условия мили, до которого враг
            // ещё не дошёл, стоял на месте весь бой. Матч 24: двое из четырёх простояли в 4–6 клетках от схватки в полном
            // здравии (M8A8 1600 на 140-м тике), пока двое дрались и армия гибла — 14:1 при равной мощи
            // прижим (см. USE_PRESS): мили в пачке — вплотную к цели фокуса в PRESS_RANGE, иначе к ближайшему ловимому врагу с
            // боем; стрелок — в кольцо ровно в RANGED_RANGE от цели фокуса
            val pack = pressOn && isMelee(creep) && !hasRanged(creep) && hasMelee(creep) && !rotating && localAggressive &&
                (combatArmy.any { it.id != creep.id && isMelee(it) && !hasRanged(it) && hasMelee(it) && getRange(creep, it) <= PRESS_PACK } ||
                    localEnemies.any { getRange(creep, it) <= 1 })
            val pressTarget: Creep? = if (!pack) null else
                focusTarget?.takeIf { getRange(creep, it) <= PRESS_RANGE && catchable(it, chasers) && it.id !in pressGiveUp }
                    ?: localEnemies.filter { getRange(creep, it) <= PRESS_RANGE && catchable(it, chasers) && threatening(it, enemyCreeps) && it.id !in pressGiveUp }.minByOrNull { getRange(creep, it) }
            val pressRanged = USE_PRESS_RING && pressOn && hasRanged(creep) && !rotating && localAggressive
            val holdMelee = isMelee(creep) && !hasRanged(creep) && posture == Posture.ANNIHILATE && !pushing && contact && pressTarget == null &&
                localEnemies.any { getRange(creep, it) <= MELEE_HOLD_RANGE + 1 }
            // прилипший (v43): его вооружённый мили ВПЛОТНУЮ к нашему стрелку, лекарю или раненому — цель ближайшего нашего мили в
            // ENGAGE_RANGE, поверх «держать линию в двух». Матч 73 (Coldkimchi): его мили подходили к нашим стрелкам и лекарям,
            // били по 240 и отходили — 46 ударов (11 тыс. урона) против наших 7, наши мили держали линию в 2–3 от его линии и не
            // доставали; стрельба при трёх лекарях с обеих сторон вылечена целиком, армия потеряна к 240-му при его 16000/16000
            val poker: Creep? = if (isMelee(creep) && !hasRanged(creep) && !support && !rotating && !stalled) combatEnemies.filter { e ->
                InfluenceMap.profileOf(e).melee > 0.0 && getRange(creep, e) <= ENGAGE_RANGE && e.id !in pressGiveUp &&
                    army.any { a -> a.id != creep.id && !(isMelee(a) && !hasRanged(a)) && getRange(e, a) <= 1 }
            }.minByOrNull { getRange(creep, it) } else null
            // прикрытие (v55): мили бросается на цель в ENGAGE_RANGE, только если её достают наши стрелки — не меньше MELEE_COVER
            // стрелков в RANGED_RANGE + 1 от неё — или она вплотную к кому-то из наших. Матч 115 (stachu3478, битый до того
            // девятнадцать раз): его одиночный стрелок подошёл на 2–6 клеток к нашим мили и отступал по клетке в тик; трое мили
            // без врага в трёх (линию не держат) шли за ним на 5–6 клеток впереди своих стрелков в его блок из четырёх мили и
            // четырёх стрелков — 1200 хитов за два тика (t=86–87), трое из четырёх мили мертвы к 100-му при равной силе на 77-м;
            // «под огнём без двух вплотную — назад» срабатывал уже под ударами. В выигранном за пять минут до того матче его
            // мили сами шли в досягаемость наших стрелков и там гибли. Гейт 125/125 при 19 лучше / 24 хуже (правило боя
            // всегда перемешивает 20–30 строк: v52c 29/20, v53 29/30; правки вне боя — 0/0). Два сужения ОТВЕРГНУТЫ стендом:
            // «только цель в блоке» (не меньше двух других вооружённых в RANGED_RANGE от неё) — 124/125, 13 лучше / 24 хуже,
            // m33 farm+weak красная; «только без толчка» (pushing) — 123/125, 10 лучше / 19 хуже, m28 farm+weak и m29 camp
            // красные. Строки «стёрт → лидируем» в rush-сценариях — не это правило: там последний крип (лекарь, равная
            // скорость) уходит от погони при любом варианте, бой окончен на 94-м
            fun covered(e: Creep) = !USE_MELEE_COVER || holdMelee ||
                combatArmy.count { it.id != creep.id && hasRanged(it) && getRange(it, e) <= RANGED_RANGE + 1 } >= MELEE_COVER ||
                army.any { a -> a.id != creep.id && getRange(e, a) <= 1 }
            val engage = if (pressTarget != null) pressTarget else poker ?: if (localAggressive && !support && inLine && !rotating && !stalled) combatEnemies.filter { getRange(creep, it) <= (if (holdMelee) MELEE_HOLD_RANGE else ENGAGE_RANGE) && catchable(it, chasers) && threatening(it, enemyCreeps) && it.id !in pressGiveUp && (!isMelee(creep) || hasRanged(creep) || covered(it)) }.minByOrNull { getRange(creep, it) } else null
            if (engage != null) engagingIds.add(creep.id) else engagingIds.remove(creep.id)
            // поводок (см. LEASH_RANGE): при враге рядом дальше поводка от центра армии — к центру
            val leashed = !support && canMove(creep) && posture != Posture.RETREAT && posture != Posture.EVADE && localEnemies.isNotEmpty() && getRange(creep, armedCentroid) > LEASH_RANGE
            val closeIn = if (localAggressive) CLOSE_STANDOFF else RANGED_RANGE
            val melee = isMelee(creep) && !hasRanged(creep)
            val meleeMate: Creep? = if (melee) combatArmy.filter { it.id != creep.id && isMelee(it) && !hasRanged(it) && hasMelee(it) && canMove(it) }.minByOrNull { getRange(creep, it) } else null
            // мили со слотом стены (см. planBlock) оставляет его ради цели: прижим или враг в досягаемости удара
            val slot = if (melee && engage != null) null else slot0
            val grab = grabberOf[creep.id]?.let { id -> ctx.flags.firstOrNull { it.id == id } }
            // лекарь держится вплотную к самому раненому бойцу РЯДОМ (в дальности лечения плюс шаг), иначе идёт к
            // ближайшему ходячему бойцу — не к самому раненому через полкарты: два лекаря шли к обездвиженному
            // остову за стеной, а строй ждал их у флага (стенд greedy)
            val healMate = if (healer) {
                val fighters = army.filter { it.id != creep.id && hasWeapon(it) }
                // подопечные — вооружённые; вне боя рядом — и раненые (они сами идут к лекарю, см. wounded)
                val patients = army.filter { it.id != creep.id && !(hasHeal(it) && !hasWeapon(it)) }
                val engagedNear = fighters.any { f -> getRange(creep, f) <= HEAL_RANGE + 1 && combatEnemies.any { getRange(f, it) <= RANGED_RANGE + 1 } }
                (if (engagedNear) fighters else patients).filter { getRange(creep, it) <= HEAL_RANGE + 1 }.maxByOrNull { it.hitsMax - it.hits }
                    ?: fighters.filter { canMove(it) }.minByOrNull { getRange(creep, it) }
                    ?: fighters.minByOrNull { getRange(creep, it) }
                    ?: patients.minByOrNull { getRange(creep, it) }
            } else null
            // раненый идёт к ближайшему лекарю (вплотную — лечение 12 за часть против 4 на дистанции)
            val healerNear: Creep? = if (wounded || rotating) army.filter { it.id != creep.id && !hasWeapon(it) && hasHeal(it) }.minByOrNull { getRange(creep, it) } else null
            // под огнём без двух бойцов вплотную — назад к строю, не вперёд: шип в строй врага бьют трое-четверо, а он один
            // вплотную, не «в двух клетках»: со счётом союзников в двух клетках мили под огнём не отходили и ныряли в блоб
            // врага по одному — три мили за восемь тиков при одном убитом (стенд m5 army, v22, t=300–308)
            val aloneInFire = USE_ALONE_FIRE && !support && !wounded && posture == Posture.ANNIHILATE && !pushing && InfluenceMap.damageAt(creep.x, creep.y, combatEnemies) > 0.0 &&
                combatArmy.count { it.id != creep.id && hasWeapon(it) && getRange(creep, it) <= 1 } < 2 && pressTarget == null && !pressRanged
            // вес огня лекаря: подопечный в бою — только разница между клетками (HEALER_W_DAMAGE_FIGHT); место за
            // подопечным и шаг от мили задают HEALER_W_FRONT и HEALER_W_MELEE, а вес 0.05 в бою держал лекаря на кромке
            // огня в 2–3 клетках (лечение 24 вместо 72) и проиграл рубки sleeper на картах 4 и 8
            val healerFireW = if (USE_HEALER_ADJ && healer && healMate != null && combatEnemies.any { getRange(healMate, it) <= RANGED_RANGE + 1 }) HEALER_W_DAMAGE_FIGHT else HEALER_W_DAMAGE
            // сбор: по полю марша (флаг-цель или пост, в обход врагов) авангард — самый продвинутый из ходячих
            // вооружённых (при равном поле — меньший id); кто дальше RALLY_RANGE от авангарда, идёт к нему
            // только на марше к флагу-цели: в HOLD цель — точка, к ней сходятся и так, а в ANNIHILATE ожидание
            // «далёкого» напарника, занятого своим боем, останавливало армию (стенд greedy)
            // ходячий по canMove, не «полноскоростной»: покалеченный участник, не входящий в сбор, но ждущий
            // далёких, замыкал группу в тупик (стенд rush: 10 против 2 до конца матча)
            val groupedPre = USE_RALLY && !support && canMove(creep) && posture == Posture.FLAG
            val marchTarget: Position? = objective?.flag?.pos
            var rallyTo: Position? = null
            if (groupedPre && marchTarget != null) {
                val mf = flowAvoiding(ctx, marchTarget, creep)
                val my = mf[creep.x * 100 + creep.y]
                var van: Creep? = null
                var vanFlow = my
                var vanId = creep.id
                for (m in mobileArmy) {
                    if (m.id == creep.id || !hasWeapon(m)) continue
                    val d = mf[m.x * 100 + m.y]
                    if (d < 0) continue
                    if (vanFlow < 0 || d < vanFlow || (d == vanFlow && m.id < vanId)) { vanFlow = d; vanId = m.id; van = m }
                }
                // с гистерезисом: с клетки «13 от авангарда» крип шёл к нему, со следующей («12») — снова к цели,
                // и два шага туда-обратно длились до конца матча, а авангард ждал (стенд rush)
                val rallyRange = if (creep.id in rallyingIds) RALLY_RANGE / 2 else RALLY_RANGE
                if (van != null && getRange(creep, van) > rallyRange) { rallyTo = InfluenceMap.cell(van.x, van.y); rallyingIds.add(creep.id) }
                else rallyingIds.remove(creep.id)
            } else rallyingIds.remove(creep.id)
            // построение: вне огня и без готовности авангард и собравшиеся у него стоят, остальные идут к нему
            // в контакте построение окончено: авангард — тот, кто уже дерётся, и «собраться у авангарда с дистанцией 1»
            // тянуло стрелков за ним внутрь строя врага, а стреляли они с 4–5 клеток впустую (матч 15, t=68–100)
            val forming = formVan != null && !formationReady && !support && canMove(creep) && posture != Posture.RETREAT && posture != Posture.EVADE &&
                localEnemies.any { threatening(it, enemyCreeps) } && nearestEnemyRange > RANGED_RANGE && !contact
            val formHold = forming && (formVan!!.id == creep.id || getRange(creep, formVan) <= FORM_RANGE)
            val formGo = forming && !formHold
            val target: Position
            val standoff: Int
            var avoid = false
            var nearFlow = false   // цель-крип рядом: поле «вблизи» (см. NEAR_FLOW)
            // в строю (см. USE_BLOCK): мили вплотную к врагу стоит и рубит, остальные — в свой слот
            val slotHold = slot != null && melee && localEnemies.any { getRange(creep, it) <= 1 }
            when {
                keeper -> { target = InfluenceMap.cell(creep.x, creep.y); standoff = 0 }
                slotHold -> { target = InfluenceMap.cell(creep.x, creep.y); standoff = 0 }
                slot != null -> { target = slot; standoff = 0 }
                // лекарь и в отходе идёт за подопечным (лечение — в тот же тик, что и шаг, 216 в тик восстанавливают
                // обломок за шесть тиков): прежде лекари шли к точке отхода сами, а раненые — врассыпную
                healer && healMate != null -> { target = healMate; standoff = 1; nearFlow = true }
                // отход — по обычному полю: поле «в обход» стоящих врагов (а дерущиеся стоят) увело пару в обход
                // стенного блока на другой край карты (матч 4)
                posture == Posture.EVADE && evadeTo != null -> { target = evadeTo; standoff = 1 }
                posture == Posture.RETREAT && retreatTo != null -> { target = retreatTo; standoff = 1 }
                formGo -> { target = InfluenceMap.cell(formVan!!.x, formVan.y); standoff = 1 }
                wounded && healerNear != null -> { target = healerNear; standoff = 1; avoid = true; nearFlow = true }
                rotating && healerNear != null -> { target = healerNear; standoff = 1; avoid = true; nearFlow = true }
                // сбор пачки (см. USE_REGROUP, REGROUP_TICKS): одинокий мили под смертельным огнём — к ближайшему мили-напарнику
                USE_REGROUP && aloneInFire && melee && meleeMate != null && InfluenceMap.damageAt(creep.x, creep.y, combatEnemies) * REGROUP_TICKS >= creep.hits -> { target = meleeMate; standoff = 1; avoid = true; nearFlow = true }
                aloneInFire -> { target = armedCentroid; standoff = CLOSE_STANDOFF; avoid = true; nearFlow = true }
                leashed -> { target = armedCentroid; standoff = CLOSE_STANDOFF; avoid = true; nearFlow = true }
                // прижим стрелка (см. USE_PRESS): кольцо ровно в RANGED_RANGE от цели фокуса, не ряд
                pressRanged && focusTarget != null && getRange(creep, focusTarget) <= ENGAGE_RANGE -> { target = focusTarget; standoff = RANGED_RANGE; nearFlow = true }
                engage != null -> { target = engage; standoff = if (melee) 1 else closeIn; nearFlow = true }
                // мили держит линию (см. MELEE_HOLD_RANGE): что подошло на две клетки — рубит, за экраном не гонится
                holdMelee -> { target = InfluenceMap.cell(creep.x, creep.y); standoff = 0 }
                grab != null -> { target = grab.pos; standoff = 0; avoid = true }
                // добивание без местного перевеса — отход к массе армии, а не бросок на «ближайшую добычу»; без
                // ловимой добычи (кайтеры) — тоже к массе: стоим строем и стреляем в то, что подойдёт
                posture == Posture.ANNIHILATE && !support && (!localAggressive || prey == null) -> { target = armedCentroid; standoff = CLOSE_STANDOFF; avoid = true }
                prey != null -> { target = prey; standoff = if (melee) 1 else closeIn; nearFlow = true }
                rallyTo != null -> { target = rallyTo; standoff = CLOSE_STANDOFF; avoid = true }
                objective != null -> {
                    val capturer = objectiveCapturer == creep.id
                    target = objective.flag.pos
                    standoff = if (capturer) 0 else CLOSE_STANDOFF
                    avoid = true
                }
                threat != null && huntingThreat && mobile -> { target = threat; standoff = if (melee) 1 else closeIn }
                raider != null && mobile && !support -> { target = raider; standoff = if (melee) 1 else RANGED_RANGE }
                // ОТВЕРГНУТО стендом (v42): «держать линию там, где она стоит» (holdLine → armedCentroid вместо поста) — в матче 70
                // пост при враге рядом был точкой в 35 клетках позади, и каждый тик ДЕРЖАТЬ между тиками ДОБИТЬ разворачивал
                // армию к нему. Но возврат к посту делает работу в десятках сценариев (после отбитого рывка остаток добивается у
                // поста): 58 строк хуже / 48 лучше, гейтовая m33 farm+weak и m29 farm красные. Мигание лечится у корня — см.
                // chaseVeto и evasive
                else -> { target = post; standoff = POST_STANDOFF; avoid = true }
            }
            val flow0 = if (slot != null || keeper) NO_FLOW else if (avoid) flowAvoiding(ctx, target, creep, nearFlow) else flowTo(ctx, target, near = nearFlow)
            // за пределом поля «вблизи» — полное поле
            val flow = if (nearFlow && slot == null && !keeper && flow0[creep.x * 100 + creep.y] < 0)
                (if (avoid) flowAvoiding(ctx, target, creep) else flowTo(ctx, target)) else flow0

            val nearbyEnemies = combatEnemies.filter { getRange(creep, it) <= 12 }
            // «в бою», плотность и передний ряд — по врагам С БОЕМ: три безоружных лекаря врага в 4–5 клетках после выигранного
            // боя держали армию в зоне плотности и не давали толкнуть своего — мили, зажатый своими лекарями, и армия
            // простояли тысячу тиков в 20 клетках от флага (стенд m16 nine)
            val inCombat = armedEnemies.any { creep.getRangeTo(it) <= RANGED_RANGE + 2 }
            val localThreats = localEnemies.filter { threatening(it, enemyCreeps) }
            val underFire = InfluenceMap.damageAt(creep.x, creep.y, combatEnemies) > 0.0 || ghost > 0
            // бегство: смертельный урон за два тика; безоружный лекарь — от врага рядом, если рядом нет ни одного
            // вооружённого своего (при нём лекарь стоит и лечит: бегущий лекарь — потерянные 72 в тик, матч 3);
            // невидимый урон
            // вооружённый бежит, только когда его ДОБИВАЮТ: за прошлый тик снято не меньше половины оставшихся хитов и
            // осталось меньше трети. Прежнее «весь возможный огонь по клетке за два тика больше хитов» в бою 12 на 12
            // верно для КАЖДОЙ клетки у вражеского блоба (1260 против 1600), и трое мили с полными хитами
            // разворачивались спиной в первый тик контакта — их резали в спину, строй рассыпался (стенд sleeper,
            // t=550; матчи 4–6 в первом размене теряли 1:5 при равной силе)
            val lostLastTick = lastHits[creep.id]?.let { it - creep.hits } ?: 0
            // лекарь и раненый бегут (врассыпную) только в одиночестве: при своём рядом — отход группой по постуре
            val inReach = (creep.x * 100 + creep.y) in reachNow
            val mustFlee = (support && nearbyEnemies.any { getRange(creep, it) <= RANGED_RANGE + 1 } && army.none { it.id != creep.id && getRange(creep, it) <= HEAL_RANGE }) ||
                (support && inReach) ||
                (lostLastTick * 2 >= creep.hits && creep.hits * 3 < creep.hitsMax) ||
                (ghost > 0 && creep.hits <= ghost)

            // сплочение: авангард ждёт отставших группы (в тиках ИХ хода), пока сам не под огнём и напарник
            // не в бою; при враге в досягаемости зазор тесный — собираемся ДО входа под огонь
            val myFlow = flow[creep.x * 100 + creep.y]
            val grouped = !support && (posture == Posture.ANNIHILATE || posture == Posture.FLAG || (huntingThreat && threat != null && target === threat))
            // напарники строя — ходячие ВООРУЖЁННЫЕ: у лекаря своя цель (подопечный), и взаимное ожидание «лекарь
            // отстал от флага — боец отстал от подопечного лекаря» запирало группу навсегда (стенд greedy)
            val mates = if (grouped) mobileArmy.filter { it.id != creep.id && hasWeapon(it) } else emptyList()
            val mateFighting = mates.any { m -> combatEnemies.any { m.getRangeTo(it) <= RANGED_RANGE + 2 } }
            val gap = if (localEnemies.isEmpty()) COHESION_GAP else ENGAGE_COHESION_TICKS
            // идущий к авангарду (rallyTo) не ждёт никого: четверо шли к авангарду и «ждали» одиночку в 14 клетках,
            // а тот ждал их — взаимное ожидание на 1600 тиков (стенд m2 scouts, v4)
            // подбирающий флаг рядом (grab) не ждёт никого, и его никто не ждёт: он ждал по сплочению группу у своего
            // флага, а группа ждала его как «отставшего» на пути к цели — взаимное ожидание на 1200 тиков при живом
            // враге из двух скаутов на наших флагах (стенд m3 kite, проигрыш по очкам 9128:23661)
            val cohesionHold = grouped && rallyTo == null && grab == null && engage == null && !underFire && !mateFighting && myFlow >= 0 && creep.getRangeTo(target) > standoff + ARRIVED_SLACK && run {
                var lagging = false
                for (m in mates) {
                    if (getRange(creep, m) <= RANGED_RANGE) continue
                    if (grabberOf.containsKey(m.id) || m.id in engagingIds) continue
                    val d = flow[m.x * 100 + m.y]
                    if (d < 0) continue
                    // напарник на другом обходе (только на марше к флагу): далеко и не впереди — ждём его, он идёт
                    // к нам (см. rallyTo)
                    if (USE_RALLY && posture == Posture.FLAG && getRange(creep, m) > RALLY_RANGE && plainPeriod(m) <= RALLY_MAX_PERIOD && (d > myFlow || (d == myFlow && m.id > creep.id))) { lagging = true; break }
                    val lag = (d - myFlow) * plainPeriod(m)
                    if (lag in (gap + 1)..COHESION_GAP_MAX) { lagging = true; break }
                }
                lagging
            }
            // отход строем (см. RETREAT_GAP): передняя половина ждёт отставшего от тела армии, пока сама вне огня
            val retreatHold = (posture == Posture.RETREAT || posture == Posture.EVADE) && !support && canMove(creep) && !underFire && nearestEnemyRange > RANGED_RANGE + 1 && myFlow >= 0 && run {
                val flows = mobileArmy.filter { hasWeapon(it) }.map { flow[it.x * 100 + it.y] }.filter { it >= 0 }.sorted()
                if (flows.isEmpty()) return@run false
                val rear = flows.last()
                val median = flows[flows.size / 2]
                rear - median > RETREAT_GAP && myFlow <= median
            }
            // терпение (см. COHESION_PATIENCE): затянувшееся ожидание снимается до конца отставания
            if (cohesionHold) {
                val since = holdSince.getOrPut(creep.id) { getTicks() }
                if (getTicks() - since >= COHESION_PATIENCE) impatientIds.add(creep.id)
            } else { holdSince.remove(creep.id); impatientIds.remove(creep.id) }
            val hold = (cohesionHold && creep.id !in impatientIds) || formHold || retreatHold

            val step: Position? = when {
                !canMove(creep) -> null
                keeper -> null
                mustFlee -> fleeStep(creep, nearbyEnemies, ctx.dangerMatrix, if (support) RANGED_RANGE + 1 else RANGED_RANGE) ?: pathStep(creep, retreatTo ?: post, 1, ctx.dangerMatrix)
                slot != null -> if (slotHold) null else slotStep(creep, slot, blockedSet, enemyPositions, occupantAt, combatEnemies, if (support && !inReach) reachNow else emptySet())
                hold -> null
                else -> {
                    // клетка флага открыта только назначенному на него (захватчик цели, «подобрать» рядом)
                    val designated = grab?.pos ?: objective?.flag?.pos?.takeIf { objectiveCapturer == creep.id }
                    var myBlocked = if (designated != null) blockedSet - (designated.x * 100 + designated.y) else blockedSet
                    // плотность (см. COMPACT_RANGE): при враге в досягаемости — только на клетки строя
                    // лекарь и раненый — вне правила (их цель — свой в строю); снаружи зоны шаг К центру всегда открыт:
                    // прежде крип вне зоны не мог шагнуть никуда (все соседи тоже вне), и три лекаря простояли весь бой
                    // матча 8 в 4–5 клетках от строя
                    if (!wounded && localThreats.isNotEmpty() && posture != Posture.RETREAT && posture != Posture.EVADE && canMove(creep)) {
                        val armedMates = mobileArmy.filter { it.id != creep.id && hasWeapon(it) }
                        val myRange = getRange(creep, armedCentroid)
                        val loose = HashSet<Int>()
                        for ((dx, dy) in DIRECTIONS) {
                            val x = creep.x + dx; val y = creep.y + dy
                            if (x < 0 || y < 0 || x > 99 || y > 99) continue
                            val c = InfluenceMap.cell(x, y)
                            val r = getRange(c, armedCentroid)
                            // шаг ВПЕРЁД (по потоку к цели) открыт на клетку в COMPACT_RANGE + 1: иначе авангард не мог
                            // выйти из зоны, а центр не сдвигался, пока никто не выходил, — блоб 1200 тиков стоял в
                            // четырёх клетках от последнего лекаря врага и проиграл по очкам (стенд m5 kite); линия
                            // ползёт гусеницей — впереди не дальше трёх от центра, остальные подтягиваются
                            val fd = flow[x * 100 + y]
                            val advancing = myFlow >= 0 && fd in 0 until myFlow
                            val compact = r <= COMPACT_RANGE || (advancing && r <= COMPACT_RANGE + 1) || armedMates.count { getRange(c, it) <= 1 } >= 2 || (USE_COMPACT_CLOSE && r < myRange)
                            if (!compact) loose.add(x * 100 + y)
                        }
                        if (loose.isNotEmpty()) myBlocked = myBlocked + loose
                    }
                    // передний ряд — вооружённым: лекарь и раненый не встают на клетку вплотную к боевому врагу (она
                    // нужна нашему мили; трое лекарей без штрафа за соседей заняли ряд перед своими мили у самого
                    // раненого бойца, и размен шёл без наших ударов — стенд m7 sleeper, 4 убитых врага против 5)
                    // уже вплотную к врагу — блок переднего ряда снят: окружённый лекарь стоял (все соседи «передний
                    // ряд»), а не уходил (матч 10, healer_2 на (14,10) между двумя мили врага)
                    // лекарь и раненый снаружи досягаемости в неё не входят (см. reachCells)
                    // лекарь с РАНЕНЫМ подопечным в дальности лечения принимает дальний огонь ради лечения вплотную (72 за часть
                    // против 24): запреты «не входить в досягаемость» и «не вставать рядом с врагом» держали его в двух-трёх
                    // клетках от того, кого бьют. Матч 34 (бой 57–550): урона получено поровну (42285 против 41684), вылечено
                    // 29275 против их 39420, у них вдвое больше событий «+144» (два лекаря вплотную на одном) — 46 против 22;
                    // наш лекарь стоял вплотную к самому раненому в 13% замеров и дальше трёх клеток — в 32%. Закрытыми
                    // остаются клетки вплотную к вражескому МИЛИ: там лекарь не лечит, а умирает
                    val healingNow = healer && healMate != null && healMate.hits < healMate.hitsMax && getRange(creep, healMate) <= HEAL_RANGE + 1
                    if (support && !inReach && reachNow.isNotEmpty() && !healingNow) myBlocked = myBlocked + reachNow
                    if (support && localThreats.isNotEmpty() && localThreats.none { getRange(creep, it) <= 1 }) {
                        val front = HashSet<Int>()
                        for ((dx, dy) in DIRECTIONS) {
                            if (dx == 0 && dy == 0) continue
                            val x = creep.x + dx; val y = creep.y + dy
                            if (x < 0 || y < 0 || x > 99 || y > 99) continue
                            val c = InfluenceMap.cell(x, y)
                            val byMelee = meleeEnemies.any { getRange(c, it) <= 1 }
                            val byPatient = healingNow && getRange(c, healMate!!) <= 1
                            if (localEnemies.any { getRange(c, it) <= 1 } && (byMelee || !byPatient)) front.add(x * 100 + y)
                        }
                        if (front.isNotEmpty()) myBlocked = myBlocked + front
                    }
                    bestSingleMove(creep, target, flow, standoff, localAggressive, inCombat, enemyCreeps, allies, meleeEnemies, myBlocked, enemyPositions, occupantAt, healerFireW)
                }
            }
            if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
                println("  f${creep.id} (${creep.x},${creep.y}) ${bodySummary(creep)} hits=${creep.hits}/${creep.hitsMax} tgt=(${target.x},${target.y}) so=$standoff flow=$myFlow flee=$mustFlee combat=$inCombat aggr=$localAggressive hold=$hold${if (formHold) "(form)" else if (retreatHold) "(rear)" else ""}${if (leashed) " leash" else ""}${if (wounded) " WOUNDED" else ""}${if (pressTarget != null || pressRanged) " PRESS" else ""} spd=${plainPeriod(creep)} fatigue=${creep.fatigue} step=${step?.let { "(${it.x},${it.y})" } ?: "stay"}${if (TrafficManager.isStuck(creep.id)) " STUCK" else ""}")
            }
            if (step != null) { TrafficManager.request(creep, step, if (wounded) WOUNDED_PRIORITY else FIGHTER_PRIORITY); planCapture(ctx, step) }
            lastHits[creep.id] = creep.hits
            lastCell[creep.id] = creep.x * 100 + creep.y
        }

        prevShooters = combatEnemies.map { val p = InfluenceMap.profileOf(it); Shooter(it.x * 100 + it.y, p.ranged, p.melee) }
        healAndShoot(army + ctx.runners.filter { hasWeapon(it) }, allies, enemyCreeps, focusTarget, focusOrder)
    }

    /** Удар мили: фокус-цель вплотную, иначе самый раненый сосед. */
    private fun strike(creep: Creep, enemyCreeps: List<Creep>, focusTarget: Creep?, focusOrder: List<Creep>) {
        if (!hasMelee(creep)) return
        val adjacent = enemyCreeps.filter { creep.getRangeTo(it) <= 1 }
        val target: Creep? = when {
            focusTarget != null && creep.getRangeTo(focusTarget) <= 1 -> focusTarget
            adjacent.isNotEmpty() -> focusOrder.firstOrNull { creep.getRangeTo(it) <= 1 } ?: adjacent.minByOrNull { it.hits }
            else -> null
        }
        target?.let { creep.attack(it) }
    }

    /** Через сколько тиков боевые враги дойдут до нашего дома — по темпу сближения за APPROACH_WINDOW;
     *  новый враг — по ходу его тела вдоль поля. Заполняет approachingIds/arrivalById (для приоритета угроз). */
    private fun enemyArrivalTicks(ctx: Ctx) {
        val now = getTicks()
        approachHistory.keys.retainAll { id -> ctx.combatEnemies.any { it.id == id } }
        approachingIds.clear()
        arrivalById.clear()
        val enemyApproach = flowTo(ctx, ctx.home)
        for (e in ctx.combatEnemies) {
            val approach = enemyApproach[e.x * 100 + e.y]
            if (approach < 0) continue
            val h = approachHistory.getOrPut(e.id) { ArrayDeque() }
            h.addLast(now to approach)
            while (h.isNotEmpty() && h.first().first < now - APPROACH_WINDOW) h.removeFirst()
            val (t0, a0) = h.first()
            val arrival = if (now - t0 < APPROACH_WINDOW / 2) pathTicks(e, enemyApproach, e.x * 100 + e.y) else {
                val rate = (a0 - approach).toDouble() / (now - t0)
                if (rate > 0.0) (approach / rate).toInt() else Int.MAX_VALUE / 2
            }
            arrivalById[e.id] = arrival
            if (arrival < Int.MAX_VALUE / 2) approachingIds.add(e.id)
        }
    }

    private fun healAndShoot(active: List<Creep>, allies: List<Creep>, enemyCreeps: List<Creep>, focusTarget: Creep?, focusOrder: List<Creep>) {
        shotsAt.clear()
        val healDone = HashMap<String, Int>()
        val incoming = HashMap<String, Int>()
        fun need(target: Creep): Int {
            val deficit = target.hitsMax - target.hits
            val expected = incoming.getOrPut(target.id) { InfluenceMap.damageAt(target.x, target.y, enemyCreeps).toInt() }
            return deficit + expected - (healDone[target.id] ?: 0)
        }
        for (creep in active) {
            strike(creep, enemyCreeps, focusTarget, focusOrder)
            val healParts = creep.body.count { it.type == HEAL && it.hits > 0 }
            if (healParts > 0) {
                val candidates = allies.filter { !it.spawning && need(it) > 0 && creep.getRangeTo(it) <= HEAL_RANGE }
                val closeTarget = candidates.filter { creep.getRangeTo(it) <= 1 }.maxByOrNull { need(it) }
                if (closeTarget != null) {
                    creep.heal(closeTarget)
                    healDone[closeTarget.id] = (healDone[closeTarget.id] ?: 0) + InfluenceMap.modified(creep, EFF_HEAL_MODIFIER, healParts * HEAL_POWER.toDouble()).toInt()
                    shoot(creep, enemyCreeps, focusTarget, focusOrder)
                    continue
                }
                val farTarget = candidates.filter { it.hitsMax - it.hits > 0 }.maxByOrNull { need(it) }
                if (farTarget != null) {
                    creep.rangedHeal(farTarget)
                    healDone[farTarget.id] = (healDone[farTarget.id] ?: 0) + InfluenceMap.modified(creep, EFF_HEAL_MODIFIER, healParts * RANGED_HEAL_POWER.toDouble()).toInt()
                    continue
                }
            }
            shoot(creep, enemyCreeps, focusTarget, focusOrder)
        }
        val most = shotsAt.values.maxOrNull() ?: 0
        if (most > 0) { concSum += most; concTicks++ }
    }

    private fun shoot(creep: Creep, enemyCreeps: List<Creep>, focusTarget: Creep?, focusOrder: List<Creep>) {
        if (!hasRanged(creep)) return
        val creepsInRange = enemyCreeps.filter { creep.getRangeTo(it) <= RANGED_RANGE }
        if (creepsInRange.isEmpty()) return
        val combatInRange = creepsInRange.filter { c -> val p = InfluenceMap.profileOf(c); p.melee + p.ranged + p.heal > 0.0 }
        val massPool = if (combatInRange.isNotEmpty()) combatInRange else creepsInRange
        val massValue = massPool.sumOf { InfluenceMap.rangedRate(creep.getRangeTo(it)) }
        // против армии с лекарями — только фокус: веер размазывает урон по трём-пяти целям, и три лекаря (216 в тик)
        // вылечивают его целиком, пока враг сосредоточенно снимает 540 в тик с одного нашего (стенд sleeper: наш чистый
        // урон 200 в тик против 540). Веер — когда врагу нечем лечить или он даёт не меньше двух с половиной выстрелов
        val enemyHeals = enemyCreeps.any { InfluenceMap.profileOf(it).heal > 0.0 }
        if (massValue > (if (enemyHeals) 2.5 else 1.0)) {
            creep.rangedMassAttack()
        } else {
            // фокус-цель вне дальности — добиваем самого раненого боевого в дальности (безоружных — в последнюю очередь)
            val target = when {
                focusTarget != null && creep.getRangeTo(focusTarget) <= RANGED_RANGE -> focusTarget
                else -> focusOrder.firstOrNull { creep.getRangeTo(it) <= RANGED_RANGE } ?: massPool.minByOrNull { it.hits }
            }
            target?.let { creep.rangedAttack(it); shotsAt[it.id] = (shotsAt[it.id] ?: 0) + 1 }
        }
    }

    private fun sgn(v: Int) = if (v > 0) 1 else if (v < 0) -1 else 0

    /** Хранители флагов (см. KEEP_RANGE): снятие, потом назначение. */
    private fun enemyCreeps(ctx: Ctx): List<Creep> = ctx.enemyCreeps
    private fun updateKeepers(ctx: Ctx, army: List<Creep>) {
        val armedEnemies = ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }
        val iter = keeperIds.entries.iterator()
        while (iter.hasNext()) {
            val e = iter.next()
            val c = army.firstOrNull { it.id == e.key }
            val f = ctx.flags.firstOrNull { it.id == e.value }
            // враг с боем в KEEP_RANGE от флага — хранителя нет: стрелок стоял на R3 весь бой, пока в десяти клетках
            // висели скауты врага, и не стрелял (матч 18)
            val stay = c != null && f != null && f.ours && c.x == f.pos.x && c.y == f.pos.y && c.hits * 2 >= c.hitsMax &&
                enemyCreeps(ctx).any { it.id != c.id && getRange(f.pos, it) <= KEEP_RELEASE } &&
                armedEnemies.count { getRange(f.pos, it) <= KEEP_RANGE } <= KEEP_PICKET
            if (!stay) {
                if (DEBUG_LOG) println("keeper t=${getTicks()}: ${e.key} released from ${e.value}")
                iter.remove()
            }
        }
        for (f in ctx.flags) {
            if (!f.ours) continue
            val occ = f.occupant ?: continue
            if (occ.my != true || army.none { it.id == occ.id } || occ.id in keeperIds) continue
            if (runnerFlag.values.contains(f.id)) continue
            if (enemyCreeps(ctx).none { getRange(f.pos, it) <= KEEP_RANGE }) continue
            if (armedEnemies.count { getRange(f.pos, it) <= KEEP_RANGE } > KEEP_PICKET) continue
            keeperIds[occ.id] = f.id
            if (DEBUG_LOG) println("keeper t=${getTicks()}: ${occ.id} keeps ${f.id} at (${f.pos.x},${f.pos.y})")
        }
    }

    /** План строя (см. USE_BLOCK): фронт — наши мили (без слотов, дерутся по своим правилам), стрелки — в ряду за центром
     *  мили на RANGED_RANGE − d клеток, где d — дистанция фронта до ближайшей угрозы (вплотную — в 2, достают на клетку
     *  за фронт, как стрелки врага за его мили; враг в 3 — в одном ряду с мили, иначе не достают вовсе: матч 17 — линия
     *  врага встала в 3 от наших мили, его мили не лезли, наши стрелки «в 2 за мили» стояли в 5–6 от целей и молчали, а
     *  наш фронт били бесплатно), тыл на клетку дальше. Первая правка делила случаи «есть их мили в 3 / нет» и меняла
     *  местами ряды стрелков и мили — при подходе толпы случай менялся через пару тиков, и строй переворачивался под
     *  ударами (стенд m6 sleeper, армия потеряна). Ряды поперёк оси центр → ближайшая группа врагов с боем; слоты по
     *  порядку SLOT_ORDER от середины ряда, стены и клетки мили пропускаются; крип берёт ближайший свободный слот
     *  своего ряда. */
    private fun planBlock(army: List<Creep>, combatEnemies: List<Creep>, armedEnemies: List<Creep>, slotOf: MutableMap<String, Position>, rangedRow: Boolean = true, standoff: Boolean = false, focusTarget: Creep? = null) {
        val melees = army.filter { hasWeapon(it) && hasMelee(it) && !hasRanged(it) && it.id !in rotatingIds }
        val rangeds = army.filter { hasWeapon(it) && hasRanged(it) && it.id !in rotatingIds }
        val rear = army.filter { c -> melees.none { it.id == c.id } && rangeds.none { it.id == c.id } }
        val armed = melees + rangeds
        if (armed.isEmpty()) return
        val threats = armedEnemies.ifEmpty { combatEnemies }
        // стоячая линия (см. USE_RANGED_FRONT): признак прижима (линия стоит под огнём, их мили не вплотную — см. pressing) и
        // ни одного их мили в MELEE_HOLD_RANGE + 1 — ряд ведут стрелки. Признак «их мили не идут» сам по себе включал этот
        // строй и против убегающего остатка, и мили переставали догонять (71 строка хуже, m28 farm+weak красный)
        val theirMeleeIn = combatEnemies.any { e -> InfluenceMap.profileOf(e).melee > 0.0 && armed.any { getRange(e, it) <= MELEE_HOLD_RANGE + 1 } }
        val standoffLine = USE_RANGED_FRONT && standoff && !theirMeleeIn && rangeds.isNotEmpty()
        val front = if (standoffLine) rangeds else melees.ifEmpty { rangeds }
        // якорь — ПЕРЕДНИЙ боец (ближайший к врагу), не центроид: центроид мили отстаёт от фронта на 1–2 клетки, и ряд
        // стрелков «в 3 − d» от него стоял в 4–5 от линии врага, вставшей в 3 от нашего переднего (матч 18)
        val pair = front.flatMap { f -> threats.map { e -> Triple(f, e, getRange(f, e)) } }.minByOrNull { it.third } ?: return
        val anchor = InfluenceMap.cell(pair.first.x, pair.first.y)
        val nearest = pair.second
        val group = threats.filter { getRange(nearest, it) <= ENGAGE_RANGE }
        val ec = centroidOf(group.map { InfluenceMap.cell(it.x, it.y) }) ?: return
        val dx0 = sgn(ec.x - anchor.x); val dy = sgn(ec.y - anchor.y)
        val dx = if (dx0 == 0 && dy == 0) 1 else dx0
        val px = -dy; val py = dx
        // стена (см. USE_WALL, отвергнута): мили без врага в MELEE_HOLD_RANGE + 1 в ряду анкера; мили с врагом в досягаемости
        // дерётся по своим правилам (см. holdMelee, прижим) и слота не получает
        val wall = if (!USE_WALL) emptyList() else melees.filter { m -> m.id != pair.first.id && combatEnemies.none { getRange(m, it) <= MELEE_HOLD_RANGE + 1 } }
        val taken = HashSet<Int>()
        for (m in melees) if (wall.none { it.id == m.id } && !standoffLine) taken.add(m.x * 100 + m.y)
        fun rowCells(back: Int, n: Int, k0: Int = 0): List<Position> {
            val out = ArrayList<Position>()
            for (k in SLOT_ORDER) {
                if (out.size >= n) break
                val x = anchor.x - back * dx + (k + k0) * px; val y = anchor.y - back * dy + (k + k0) * py
                if (x < 0 || y < 0 || x > 99 || y > 99 || DistanceMap.isTerrainWall(x, y) || (x * 100 + y) in taken) continue
                out.add(InfluenceMap.cell(x, y))
            }
            return out
        }
        fun assign(creeps: List<Creep>, cells: List<Position>) {
            val free = ArrayList(cells)
            // ближайшие к своему ряду первыми: так слоты не пересекаются
            for (c in creeps.sortedBy { c -> cells.minOfOrNull { getRange(c, it) } ?: 0 }) {
                val best = free.minByOrNull { getRange(c, it) } ?: break
                free.remove(best)
                slotOf[c.id] = best
                taken.add(best.x * 100 + best.y)
            }
        }
        val d = pair.third
        if (standoffLine) {
            // ОДИН ряд из стрелков и мили в RANGED_RANGE от ближайшей угрозы (анкер в d: отрицательное back — шаг вперёд):
            // стрелки в середине (ближайшие к своим клеткам), мили на флангах; тыл на клетку позади. Мили вплотную к врагу
            // слота не получает — рубит по своим правилам. Замер оператора по реплею матча 67 (けろびー v2): его девять
            // вооружённых стоят шириной 9,7 клетки поперёк оси на нас, наши — 4,6; по замеру шириной (вооружённые целее 600)
            // у него стрелок с целью в трёх 72 %, у нас 63 %; матч 53 (Coldkimchi) — 5,7 против 4,2, 39 % против 28 %; против
            // атакующего (матч 38, ширина его колонны 2,8) этот строй не включается. Ряд «стрелки впереди, мили позади» (v37)
            // кайтер стенда разоружал первыми — здесь мили в той же линии делят его огонь. Но загораживания замер по всем
            // вооружённым НЕ подтвердил: наши стрелки в 4+ от цели стоят со свободной клеткой впереди 42 раза против 6 за
            // своим — они не заперты, а на ряд дальше (см. USE_RANGED_FRONT, threatOf)
            val backR = (RANGED_RANGE - d).coerceIn(-1, 2)
            assign(rangeds, rowCells(backR, rangeds.size))
            assign(melees.filter { m -> combatEnemies.none { getRange(m, it) <= 1 } }, rowCells(backR, melees.size))
            assign(rear, rowCells(backR + 1, rear.size))
            return
        }
        var back = (RANGED_RANGE - d).coerceIn(0, 2)
        // фокус-огонь (v45): ряд стрелков строится ВОКРУГ цели фокуса — центром на её проекции на ряд (не дальше двух клеток от
        // оси, чтобы ряд не уходил от мили) и на том ряду, где центр ряда стоит в RANGED_RANGE от неё: тогда все пять
        // стрелков достают ОДНУ цель. Ряд поперёк оси на центроид группы ставил каждого стрелка против своего (см. focusTarget)
        var k0 = 0
        val focus = if (!USE_FOCUS_ROW) null else focusTarget?.takeIf { f -> getRange(anchor, f) <= ENGAGE_RANGE }
        if (focus != null) {
            k0 = ((focus.x - anchor.x) * px + (focus.y - anchor.y) * py).coerceIn(-2, 2)
            var bestB = -1
            var bestR = -1
            for (b in 0..2) {
                val cx = anchor.x - b * dx + k0 * px; val cy = anchor.y - b * dy + k0 * py
                if (cx < 0 || cy < 0 || cx > 99 || cy > 99) continue
                val r = getRange(InfluenceMap.cell(cx, cy), focus)
                if (r <= RANGED_RANGE && r > bestR) { bestR = r; bestB = b }
            }
            if (bestB >= 0) back = bestB
        }
        if (wall.isNotEmpty()) assign(wall, rowCells(0, wall.size))
        if (melees.isNotEmpty() && rangedRow) assign(rangeds, rowCells(back, rangeds.size, k0))
        // тыл — всегда сразу за фронтом: ряд «за стрелками» при враге вплотную (back=2) ставил лекарей в трёх клетках
        // от мили, лечение 4 за часть вместо 12 (матч 22, t=110–130: лекари в 2–3 клетках от дерущихся мили)
        assign(rear, rowCells(1, rear.size, k0))
    }

    private class FightCell(val pos: Position, val key: Int, val dmg: Double, val targets: Int, val focusIn: Boolean,
                            val meleeAdj: Int, val meleeNear: Int, val dist: Int)
    private val lastPlan = HashMap<String, Int>()   // крип → клетка прошлого плана (см. planFight: память расстановки)
    private var focusId: String? = null              // липкая цель фокуса (v45, см. focusTarget)
    private val shotsAt = HashMap<String, Int>()     // выстрелы по цели за тик (см. conc в строке t=)
    private var concSum = 0                          // сумма «наибольшее число выстрелов в одну цель за тик» с прошлой строки t=
    private var concTicks = 0                        // тиков с выстрелами с прошлой строки t=

    /** Расстановка боя (см. USE_PLAN): клетки с признаками, роли по порядку признаков, жадное назначение. Выход — slotOf,
     *  движение к слоту — как у строя (slotStep). Мили вплотную к врагу слота не получает (рубит по своим правилам), его
     *  клетка занята. */
    private fun planFight(army: List<Creep>, combatEnemies: List<Creep>, armedEnemies: List<Creep>, enemyCreeps: List<Creep>, slotOf: MutableMap<String, Position>, focusTarget: Creep?) {
        val melees = army.filter { hasWeapon(it) && hasMelee(it) && !hasRanged(it) && it.id !in rotatingIds }
        val rangeds = army.filter { hasWeapon(it) && hasRanged(it) && it.id !in rotatingIds }
        val rear = army.filter { c -> melees.none { it.id == c.id } && rangeds.none { it.id == c.id } }
        if (melees.isEmpty() && rangeds.isEmpty()) return
        val threats = armedEnemies.ifEmpty { combatEnemies }
        if (threats.isEmpty()) return
        val theirMelee = threats.filter { InfluenceMap.profileOf(it).melee > 0.0 }
        // ЦЕЛЬ КЛЕТКИ — ЕГО СТРЕЛОК (v67; как фокус v60): «есть цель в трёх» считало целью и мили-приманку в 2–3, клетка в трёх от
        // неё держалась памятью расстановки, и стрелки стояли в 4 от его стрелков со свободной клеткой впереди 142 крип-тика,
        // стреляя в мили «за неимением» (матч 160, девятое поражение Coldkimchi: 79 выстрелов в мили при его стрелках в 3–4,
        // 3:198 и 4:213 крип-тиков; его 341 выстрел против наших 199, армия стёрта при его 16000/16000). Мили — цель клетки,
        // только когда стрелков у него нет
        val shootAt = threats.filter { InfluenceMap.profileOf(it).ranged > 0.0 }.ifEmpty { threats }
        val enemyAt = enemyCreeps.mapTo(HashSet()) { it.x * 100 + it.y }
        // клетки-кандидаты: в RANGED_RANGE от любого нашего (дальше — марш, не расстановка), проходимые, не под врагом, и НА
        // НАШЕЙ СТОРОНЕ (v61): не дальше от центра наших вооружённых, чем от центра его угроз. Матч 145 (Coldkimchi, седьмое
        // поражение, армия стёрта за сорок тиков при его 16000/16000): его линия стояла в (73–76, 9–13), наш центр в (79,8), и
        // ярусы «цель в трёх → нет его мили вплотную → нет его мили в двух» выбрали стрелкам клетки (76–80, 15–16) — ЗА его
        // линией, где его мили не стоят, — и одиннадцать крипов пошли к ним сквозь его строй по одному (so=0 flow=−1 у всех на
        // 370–380-м): reach 1/3, наш огонь 1,2 в тик против его 4,2
        val ourC = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army })
        val theirC = centroidOf(threats)
        val cells = HashMap<Int, FightCell>()
        for (c in army) for (dx in -RANGED_RANGE..RANGED_RANGE) for (dy in -RANGED_RANGE..RANGED_RANGE) {
            val x = c.x + dx; val y = c.y + dy
            val key = x * 100 + y
            if (key in cells || x < 0 || y < 0 || x > 99 || y > 99 || DistanceMap.isTerrainWall(x, y) || key in enemyAt) continue
            val p = InfluenceMap.cell(x, y)
            if (USE_PLAN_OUR_SIDE && ourC != null && theirC != null && getRange(p, ourC) > getRange(p, theirC)) continue
            cells[key] = FightCell(p, key, InfluenceMap.damageAt(x, y, combatEnemies), shootAt.count { getRange(p, it) <= RANGED_RANGE },
                focusTarget != null && getRange(p, focusTarget) <= RANGED_RANGE,
                theirMelee.count { getRange(p, it) <= 1 }, theirMelee.count { getRange(p, it) <= MELEE_KEEP_RANGE },
                threats.minOf { getRange(p, it) })
        }
        if (cells.isEmpty()) return
        val taken = HashSet<Int>()
        val meleeFree = melees.filter { m -> combatEnemies.none { getRange(m, it) <= 1 } }
        for (m in melees) if (meleeFree.none { it.id == m.id }) taken.add(m.x * 100 + m.y)
        // клетка под своим — только его: без этого стрелкам назначались клетки друг друга (матч 73, t=120: ranged_1 → клетка
        // ranged_3, ranged_3 → клетка ranged_1, ranged_2 → клетка ranged_3), и строй крутился на месте под огнём
        val ownAt = HashMap<Int, String>()
        for (c in army) ownAt[c.x * 100 + c.y] = c.id
        // память расстановки: клетка прошлого тика остаётся, пока держит верхние ярусы своей роли (keep) — без памяти «лучшая»
        // клетка менялась каждый тик (урон, фланги), стрелки блуждали вбок вместо шага за фронтом, и кайтер стенда бил идущих
        // за ним мили при reach=0/5 (m28 kite, армия потеряна); ряд строя двигался вместе с передним мили и потому успевал
        val plan = HashMap<String, Int>()
        fun place(c: Creep, cmp: Comparator<FightCell>, keep: ((FightCell) -> Boolean)?, ok: (FightCell) -> Boolean): FightCell? {
            fun free(cell: FightCell) = cell.key !in taken && (ownAt[cell.key] ?: c.id) == c.id
            val prev = keep?.let { k -> lastPlan[c.id]?.let { cells[it] }?.takeIf { free(it) && k(it) } }
            val best = prev ?: cells.values.filter { free(it) && ok(it) }.maxWithOrNull(cmp) ?: return null
            slotOf[c.id] = best.pos
            taken.add(best.key)
            plan[c.id] = best.key
            return best
        }
        // стрелки: цель в трёх → не вплотную к его мили → не в двух от его мили → цель фокуса в трёх → дистанция до ближайшей
        // угрозы (с целью: 3 лучше 2 лучше 1 — линия стоит на выстреле; БЕЗ цели: ближе к врагу — иначе стрелок вне
        // досягаемости стоял на месте, пока кайтер отходил на клетку в тик и бил идущих за ним мили: m28 kite, reach=0/5 сто
        // тиков, армия потеряна) → меньше урона → ближе к себе
        val rangedCells = HashMap<String, FightCell>()
        fun rangedCmp(c: Creep) = compareBy<FightCell> { if (it.focusIn) 1 else 0 }   // цель фокуса в трёх — первое (v45)
            .thenBy { if (it.targets > 0) 1 else 0 }
            .thenBy { if (it.meleeAdj == 0) 1 else 0 }
            .thenBy { if (it.meleeNear == 0) 1 else 0 }
            .thenBy { if (it.targets > 0) minOf(it.dist, RANGED_RANGE) else -it.dist }
            .thenBy { -it.dmg }
            .thenBy { -getRange(c, it.pos) }
        // СТРЕЛОК НЕ ВПЕРЕДИ МИЛИ (v69): клетка стрелка не ближе к угрозе, чем нынешний фронт мили минус шаг. Матч 169 (stachu3478,
        // третье поражение при 24 победах): его линия отходила по клетке в тик, клетки «его стрелок в трёх» (v67) уходили за ней,
        // стрелки шли вперёд, мили (клетки по памяти) отстали на 8–10 клеток, и его мили (в трёх 41 % тиков) съели стрелков по
        // одному — 19 крип-тиков разоружённых, армия стёрта за сто тиков при его 15435/16000. «Стрелки впереди» отвергнуто ещё
        // v37 — сюда оно вошло через план
        val meleeFrontDist = if (USE_RANGED_BEHIND_MELEE) meleeFree.minOfOrNull { m -> threats.minOf { getRange(m, it) } } else null
        fun behindMelee(cell: FightCell) = meleeFrontDist == null || cell.dist >= meleeFrontDist - 1
        val constrained = rangeds.sortedBy { c -> cells.values.count { it.targets > 0 && it.meleeAdj == 0 && getRange(c, it.pos) <= 1 } }
        for (r in constrained) {
            val cell = place(r, rangedCmp(r), { it.targets > 0 && it.meleeAdj == 0 && it.meleeNear == 0 && behindMelee(it) }) { behindMelee(it) }
                ?: place(r, rangedCmp(r), null) { true } ?: continue
            rangedCells[r.id] = cell
        }
        // мили без врага вплотную — заслон перед стрелком: клетка рядом с клеткой стрелка и ближе к угрозе, чем она; его мили в
        // двух (есть кого встретить) лучше, чем нет; вплотную к двум и больше его мили — хуже; меньше урона; ближе к себе.
        // Нет такой клетки — фланг: клетка на той же дистанции, что и стрелки
        val front = rangedCells.values.toList()
        fun meleeCmp(c: Creep) = compareBy<FightCell> { if (it.meleeAdj <= 1) 1 else 0 }
            .thenBy { if (it.meleeNear > 0) 1 else 0 }
            .thenBy { -it.dist }
            .thenBy { -it.dmg }
            .thenBy { -getRange(c, it.pos) }
        val frontDist = front.minOfOrNull { it.dist } ?: RANGED_RANGE
        fun inFront(cell: FightCell) = front.any { rc -> getRange(cell.pos, rc.pos) <= 1 && cell.dist < rc.dist }
        for (m in meleeFree.sortedBy { c -> front.minOfOrNull { getRange(c, it.pos) } ?: 0 }) {
            place(m, meleeCmp(m), { it.meleeAdj <= 1 && inFront(it) }) { cell -> inFront(cell) }
                ?: place(m, meleeCmp(m), null) { cell -> cell.dist == frontDist && front.any { rc -> getRange(cell.pos, rc.pos) <= 2 } }
                ?: place(m, meleeCmp(m), null) { true }
        }
        // лекари: вплотную к бойцу с наибольшим входящим уроном на ЕГО клетке; сам не в двух от его мили; под меньшим огнём
        val fighterCells = ArrayList(rangedCells.values)
        for (m in meleeFree) slotOf[m.id]?.let { p -> cells[p.x * 100 + p.y]?.let { fighterCells.add(it) } }
        for (m in melees) if (meleeFree.none { it.id == m.id }) cells[m.x * 100 + m.y]?.let { fighterCells.add(it) }
        val healers = rear.filter { hasHeal(it) }
        val wounded = rear.filter { !hasHeal(it) }
        fun needAt(cell: FightCell): Double = fighterCells.filter { getRange(cell.pos, it.pos) <= 1 }.maxOfOrNull { it.dmg } ?: -1.0
        fun healerCmp(c: Creep) = compareBy<FightCell> { if (it.meleeNear == 0) 1 else 0 }
            .thenBy { needAt(it) }
            .thenBy { -it.dmg }
            .thenBy { -getRange(c, it.pos) }
        val healerCells = ArrayList<FightCell>()
        fun byFighter(cell: FightCell) = fighterCells.any { getRange(cell.pos, it.pos) <= 1 }
        for (h in healers.sortedBy { c -> fighterCells.minOfOrNull { getRange(c, it.pos) } ?: 0 }) {
            val cell = place(h, healerCmp(h), { it.meleeNear == 0 && byFighter(it) }) { cell -> byFighter(cell) }
                ?: place(h, healerCmp(h), null) { cell -> fighterCells.any { getRange(cell.pos, it.pos) <= HEAL_RANGE } }
                ?: place(h, healerCmp(h), null) { true }
            if (cell != null) healerCells.add(cell)
        }
        // раненые без оружия: дальше выстрела, рядом с лекарем, под меньшим огнём
        fun woundedCmp(c: Creep) = compareBy<FightCell> { if (it.dist > RANGED_RANGE) 1 else 0 }
            .thenBy { if (healerCells.any { h -> getRange(it.pos, h.pos) <= 1 }) 1 else 0 }
            .thenBy { -it.dmg }
            .thenBy { -getRange(c, it.pos) }
        for (w in wounded) place(w, woundedCmp(w), { it.dist > RANGED_RANGE }) { true }
        lastPlan.clear()
        lastPlan.putAll(plan)
    }

    /** Шаг к слоту строя без поля потока: соседняя проходимая клетка, ближайшая к слоту (при равенстве — под меньшим
     *  огнём); занятая своим — через трафик, если только она ближе; клетки banned (досягаемость для лекаря) закрыты. */
    private fun slotStep(creep: Creep, slot: Position, blockedSet: Set<Int>, enemyPositions: Set<Int>, occupantAt: Map<Int, Creep>, enemies: List<Creep>, banned: Set<Int>): Position? {
        val here = getRange(creep, slot)
        if (here == 0) return null
        var best: Position? = null
        var bestD = here
        var bestFire = Double.MAX_VALUE
        var push: Position? = null
        var pushD = here
        for ((dx, dy) in DIRECTIONS) {
            if (dx == 0 && dy == 0) continue
            val x = creep.x + dx; val y = creep.y + dy
            if (!passable(x, y, blockedSet, enemyPositions) || (x * 100 + y) in banned) continue
            val c = InfluenceMap.cell(x, y)
            val d = getRange(c, slot)
            if (occupantAt[x * 100 + y] != null) { if (d < pushD) { pushD = d; push = c }; continue }
            val fire = InfluenceMap.damageAt(x, y, enemies)
            if (d < bestD || (d == bestD && fire < bestFire)) { bestD = d; bestFire = fire; best = c }
        }
        return best ?: push
    }

    private fun bestSingleMove(
        creep: Creep,
        target: Position,
        flow: IntArray,
        standoff: Int,
        aggressive: Boolean,
        inCombat: Boolean,
        enemyCreeps: List<Creep>,
        allies: List<Creep>,
        meleeEnemies: List<Creep>,
        blockedSet: Set<Int>,
        enemyPositions: Set<Int>,
        occupantAt: Map<Int, Creep>,
        healerFireW: Double = HEALER_W_DAMAGE,
    ): Position? {
        val hereDist = flow[creep.x * 100 + creep.y]
        // своя клетка с форой — только ПРИБЫВ (в зазоре standoff): вне боя не дёргаемся ради мелочи (см.
        // STAY_BIAS); на марше форы нет — вместе со штрафом за соседей она съедала выигрыш шага (матч 2)
        val settled = !inCombat && hereDist in 0..(standoff + ARRIVED_SLACK)
        var bestScore = scoreCell(creep, creep.x, creep.y, target, flow, standoff, aggressive, inCombat, enemyCreeps, allies, meleeEnemies, healerFireW) + (if (settled) STAY_BIAS else 0.0)
        var bx = creep.x; var by = creep.y
        var pushDist = if (hereDist >= 0) hereDist else Int.MAX_VALUE
        var pushX = -1; var pushY = -1
        var blockedByStatic = false
        val stuck = TrafficManager.isStuck(creep.id)
        for ((dx, dy) in DIRECTIONS) {
            if (dx == 0 && dy == 0) continue
            val x = creep.x + dx; val y = creep.y + dy
            if (!passable(x, y, blockedSet, enemyPositions)) continue
            val occ = occupantAt[x * 100 + y]
            if (occ != null) {
                val fd = flow[x * 100 + y]
                val static = TrafficManager.wasStatic(occ.id) || !canMove(occ)
                // лекарь и раненый уступают и в бою (TrafficManager: заявитель приоритетнее стоящего — swap): раненый,
                // «прибывший» к лекарю, стоял на единственной клетке между тремя лекарями в кармане у стены и их
                // подопечным, и лечения не было (стенд m7 sleeper); лекаря толкает только вооружённый
                val yielding = canMove(occ) && !hasWeapon(occ) && !hasHeal(occ) && hasHeal(creep) && !hasWeapon(creep)
                if (yielding && fd in 0 until pushDist) { pushDist = fd; pushX = x; pushY = y }
                else if (fd in 0 until (if (hereDist >= 0) hereDist else Int.MAX_VALUE) && (static || stuck)) blockedByStatic = true
                else if (!inCombat && fd in 0 until pushDist) { pushDist = fd; pushX = x; pushY = y }
                continue
            }
            val s = scoreCell(creep, x, y, target, flow, standoff, aggressive, inCombat, enemyCreeps, allies, meleeEnemies, healerFireW)
            if (s > bestScore) { bestScore = s; bx = x; by = y }
        }
        if (bx != creep.x || by != creep.y) return InfluenceMap.cell(bx, by)
        if (pushX >= 0) return InfluenceMap.cell(pushX, pushY)
        if (blockedByStatic && hereDist >= 0) {
            var dx0 = 0; var dy0 = 0; var best = hereDist + DistanceMap.SWAMP_COST
            for ((dx, dy) in DIRECTIONS) {
                if (dx == 0 && dy == 0) continue
                val x = creep.x + dx; val y = creep.y + dy
                if (!passable(x, y, blockedSet, enemyPositions) || occupantAt.containsKey(x * 100 + y)) continue
                val fd = flow[x * 100 + y]
                if (fd in 0..best && (dx0 == 0 && dy0 == 0 || fd < best)) { best = fd; dx0 = dx; dy0 = dy }
            }
            if (dx0 != 0 || dy0 != 0) return InfluenceMap.cell(creep.x + dx0, creep.y + dy0)
        }
        return null
    }

    /** Оценка клетки: приблизиться на standoff к цели по реальному пути; в бою — исходящий урон, чистый
     *  входящий (с хилом), влияние, штраф за зону мили, за болото (без перевеса) и цена прижатия. */
    private fun scoreCell(creep: Creep, x: Int, y: Int, target: Position, flow: IntArray, standoff: Int, aggressive: Boolean, inCombat: Boolean, enemyCreeps: List<Creep>, allies: List<Creep>, meleeEnemies: List<Creep>, healerFireW: Double = HEALER_W_DAMAGE): Double {
        val flowDist = flow[x * 100 + y]
        val cheb = getRange(InfluenceMap.cell(x, y), target)
        val firePenalty = when {
            cheb <= standoff -> (standoff - cheb) * 0.5
            flowDist < 0 -> 1000.0
            flowDist > standoff -> (flowDist - standoff).toDouble()
            else -> (standoff - flowDist) * 0.5
        }
        val separation = allies.count { !it.spawning && (it.x != x || it.y != y) && getRange(InfluenceMap.cell(x, y), it) <= SEPARATION_RADIUS } * PAIR_W_SPREAD
        // на марше (вне боя и дальше зазора прибытия) соседи не штрафуются: в колонне клетка впереди почти всегда
        // соседствует с двумя союзниками (−8), и штраф вместе с форой своей клетки (+5) съедал выигрыш шага (10) —
        // двенадцать бойцов простояли 1800 тиков в 12 клетках от цели (матч 2); разрежение нужно на месте и в бою
        // лекарь и раненый без штрафа за соседей: их место — вплотную к своему (штраф 4 за соседа в зоне прибытия
        // против выигрыша шага 10 держал лекаря в 3–4 клетках от подопечного, матч 8)
        if (!inCombat) return -firePenalty * PAIR_W_DIST - (if ((USE_HEALER_ADJ && !hasWeapon(creep)) || flowDist > standoff + ARRIVED_SLACK) 0.0 else separation)

        val damage = InfluenceMap.netDamageAt(x, y, enemyCreeps, allies)
        // лекарь: вплотную к подопечному (поле), из клеток равной близости — под меньшим ФАКТИЧЕСКИМ огнём (fireAt:
        // без шага сближения мили — иначе клетка рядом с бойцом, который рубится вплотную, «стоит» 720 и лекарь
        // стоит в трёх клетках; от мили, что действительно подошёл, лекарь отойдёт следующим тиком)
        if (!hasWeapon(creep)) {
            val fire = InfluenceMap.fireAt(x, y, enemyCreeps)
            val pinnedHealer = (periodAt(creep, x, y) - 1) * fire * PAIR_W_DAMAGE
            // вплотную к мили врага — прочь (см. HEALER_W_MELEE): штраф в 2 клетках бил по всем клеткам у подопечного, когда
            // мили стоял по другую его сторону, и лекарь уходил на 4 (вне даже дистанционного лечения) — стенд m2 rush
            val meleeReach = meleeEnemies.count { getRange(InfluenceMap.cell(x, y), it) <= 1 } * HEALER_W_MELEE
            return -firePenalty * PAIR_W_DIST - fire * healerFireW - meleeReach - (if (USE_HEALER_ADJ) 0.0 else separation) - pinnedHealer
        }
        val meleeSelf = isMelee(creep) && !hasRanged(creep)
        val meleeWeight = if (aggressive) PAIR_W_MELEE * AGGRO_MELEE_FACTOR else PAIR_W_MELEE
        val meleeThreat = if (meleeSelf) 0.0 else meleeEnemies.count { getRange(InfluenceMap.cell(x, y), it) <= MELEE_KEEP_RANGE } * meleeWeight
        val swampPenalty = if (!aggressive && DistanceMap.isSwamp(x, y)) PAIR_W_SWAMP else 0.0
        val influence = if (meleeSelf && aggressive) 0.0 else InfluenceMap.influenceAt(x, y, allies, enemyCreeps)
        val outgoing = if (!aggressive && damage > 0.0) 0.0 else if (meleeSelf) (if (enemyCreeps.any { getRange(InfluenceMap.cell(x, y), it) <= 1 }) 1.0 else 0.0) else if (hasRanged(creep)) outgoingValue(x, y, enemyCreeps) else 0.0
        val damageTerm = if (aggressive) 0.0 else damage * PAIR_W_DAMAGE
        val pinned = (periodAt(creep, x, y) - 1) * InfluenceMap.fireAt(x, y, enemyCreeps) * PAIR_W_DAMAGE
        return -firePenalty * PAIR_W_DIST - damageTerm + influence * PAIR_W_INFLUENCE +
            outgoing * PAIR_W_OUTGOING - meleeThreat - separation - swampPenalty - pinned
    }

    private fun outgoingValue(x: Int, y: Int, enemyCreeps: List<Creep>): Double {
        var massValue = 0.0
        var anyInRange = false
        for (enemy in enemyCreeps) {
            val d = getRange(InfluenceMap.cell(x, y), enemy)
            if (d <= RANGED_RANGE) { anyInRange = true; massValue += InfluenceMap.rangedRate(d) }
        }
        if (!anyInRange) return 0.0
        return maxOf(massValue, 1.0)
    }

    private fun passable(x: Int, y: Int, blockedSet: Set<Int>, enemyPositions: Set<Int>): Boolean {
        if (x < 0 || y < 0 || x > 99 || y > 99) return false
        val key = x * 100 + y
        if (key in blockedSet || key in enemyPositions) return false
        return !DistanceMap.isTerrainWall(x, y)
    }

    // ==================== тело, скорость, мощь ====================

    private fun canMove(creep: Creep) = creep.body.any { it.type == MOVE && it.hits > 0 }
    private fun hasMelee(creep: Creep) = creep.body.any { it.type == ATTACK && it.hits > 0 }
    private fun isMelee(creep: Creep) = creep.body.any { it.type == ATTACK }
    private fun hasRanged(creep: Creep) = creep.body.any { it.type == RANGED_ATTACK && it.hits > 0 }
    private fun hasHeal(creep: Creep) = creep.body.any { it.type == HEAL && it.hits > 0 }
    private fun hasWeapon(creep: Creep) = hasRanged(creep) || hasMelee(creep)

    /** Сводка тела: T10M4R3H1 (только живые части). */
    private fun bodySummary(creep: Creep): String {
        val order = listOf(TOUGH to 'T', MOVE to 'M', RANGED_ATTACK to 'R', ATTACK to 'A', HEAL to 'H', CARRY to 'C', WORK to 'W')
        val sb = StringBuilder()
        for ((type, ch) in order) {
            val n = creep.body.count { it.type == type && it.hits > 0 }
            if (n > 0) sb.append(ch).append(n)
        }
        return sb.toString()
    }

    /** Вес тела для усталости: части не-MOVE и не-CARRY ПО ТИПУ (мёртвые весят — movement.js:237)
     *  плюс гружёные CARRY. */
    private fun bodyWeight(creep: Creep): Int {
        val parts = creep.body.count { it.type != MOVE && it.type != CARRY }
        val carried = creep.store[RESOURCE_ENERGY] ?: 0
        return parts + (carried + CARRY_CAPACITY - 1) / CARRY_CAPACITY
    }

    private fun liveMoves(creep: Creep) = creep.body.count { it.type == MOVE && it.hits > 0 }

    /** Период хода (тиков на клетку): после шага fatigue = вес × цена местности − 2 × живые MOVE, дальше
     *  −2×MOVE в тик, следующий ход при нуле (tick.js:105, movement.js:237). */
    private fun periodOn(weight: Int, moves: Int, rate: Int): Int {
        if (moves <= 0) return Int.MAX_VALUE / 4
        val left = weight * rate - 2 * moves
        return if (left <= 0) 1 else 1 + (left + 2 * moves - 1) / (2 * moves)
    }

    private fun plainPeriod(creep: Creep) = periodOn(bodyWeight(creep), liveMoves(creep), 2)
    private fun periodAt(creep: Creep, x: Int, y: Int) =
        periodOn(bodyWeight(creep), liveMoves(creep), if (DistanceMap.isSwamp(x, y)) 10 else 2)
    private fun swampPeriod(creep: Creep) = periodOn(bodyWeight(creep), liveMoves(creep), 10)
    private fun fullSpeed(creep: Creep) = plainPeriod(creep) == 1

    /** Сколько урона крип ещё выдержит, не теряя скорости (части умирают спереди). */
    private fun speedSlack(creep: Creep): Int {
        val weight = bodyWeight(creep)
        if (weight == 0) return creep.hits // тела без веса (чистый MOVE) скорости не теряют
        var moves = liveMoves(creep)
        var slack = 0
        for (part in creep.body) {
            if (part.hits <= 0) continue
            if (moves < weight) break
            slack += part.hits
            if (part.type == MOVE) moves--
        }
        return slack
    }

    /** Цена боя: хиты, которые снимут с нас, пока враги умирают по одному под нашим огнём (лекари первыми,
     *  их лечение вычитается); урон врага — с НАШИМ множителем входящего, наш — с ЕГО. */
    private fun fightCost(enemies: List<Creep>, ours: List<Creep>): Double {
        val ourDps = ours.sumOf { effectiveDps(it, enemies) }
        if (ourDps <= 0.0) return Double.MAX_VALUE
        val order = enemies.sortedWith(compareByDescending<Creep> { InfluenceMap.profileOf(it).heal }.thenBy { it.hits })
        val ourTaken = ours.maxOfOrNull { InfluenceMap.takenOf(it) } ?: 1.0
        var remaining = enemies.sumOf { effectiveDps(it, ours) } * ourTaken
        var heal = enemies.sumOf { InfluenceMap.profileOf(it).heal }
        var damage = 0.0
        for (e in order) {
            val net = ourDps * InfluenceMap.takenOf(e) - heal
            if (net <= 0.0) return Double.MAX_VALUE
            damage += remaining * e.hits / net
            remaining -= effectiveDps(e, ours) * ourTaken
            heal -= InfluenceMap.profileOf(e).heal
        }
        return damage
    }

    private fun lanchester(dps: Double, enemyHeal: Double, hits: Double): Double =
        sqrt(maxOf(0.0, dps - enemyHeal) * maxOf(0.0, hits))

    /** Доля удара мили, которая ДОЙДЁТ: кайт-дисконт, только если противники сплошь стрелки, никто не
     *  прижат вплотную и мили медленнее каждого из них на болоте. */
    private fun meleeFactor(unit: Creep, opponents: List<Creep>): Double {
        if (opponents.any { hasMelee(it) || getRange(unit, it) <= MELEE_KEEP_RANGE }) return 1.0
        val ranged = opponents.filter { hasRanged(it) }
        if (ranged.isEmpty()) return 1.0
        val mine = swampPeriod(unit)
        return if (ranged.any { swampPeriod(it) > mine }) 1.0 else MELEE_KITE_DISCOUNT
    }

    /** Действенный урон крипа в тик против группы (с его эффектами): стрельба целиком, мили — по meleeFactor. */
    private fun effectiveDps(unit: Creep, opponents: List<Creep>, rangedK: Double = 1.0, meleeK: Double = 1.0): Double {
        val p = InfluenceMap.profileOf(unit)
        return p.ranged * rangedK + p.melee * meleeK * meleeFactor(unit, opponents)
    }

    /** Хиты в счёте мощи: по доле удара, которая дойдёт (кайтимая мили в бою не участвует; лекарь и
     *  безоружный — полностью), с поправкой на множитель входящего урона (флаг уязвимости). */
    private fun weightedHits(unit: Creep, opponents: List<Creep>, hitsK: Double = 1.0): Double {
        val p = InfluenceMap.profileOf(unit)
        val raw = p.ranged + p.melee
        val taken = InfluenceMap.takenOf(unit).coerceAtLeast(0.01)
        // раненый (оружие или лечение в теле мертво) хитов в счёт не даёт: он не в строю и огня на себя не берёт
        if (raw <= 0.0 && p.heal <= 0.0 && unit.body.any { it.type == ATTACK || it.type == RANGED_ATTACK || it.type == HEAL }) return 0.0
        val share = if (raw <= 0.0) 1.0 else effectiveDps(unit, opponents) / raw
        return unit.hits * share * hitsK / taken
    }

    /** Гипотетические множители стороны сверх текущих эффектов (маргинальная цена флага, см. powerAfter). */
    private class HypoMods(val ranged: Double = 1.0, val melee: Double = 1.0, val heal: Double = 1.0, val hits: Double = 1.0)
    private val NO_MODS = HypoMods()
    private fun hypoMods(type: String, k: Double) = HypoMods(
        ranged = if (type == EFF_RANGED_ATTACK_MODIFIER) k else 1.0,
        melee = if (type == EFF_ATTACK_MODIFIER) k else 1.0,
        heal = if (type == EFF_HEAL_MODIFIER) k else 1.0,
        hits = if (type == EFF_DAMAGE_TAKEN_MODIFIER) 1.0 / k else 1.0,
    )

    /** Мощь стороны по Ланчестеру против группы противника: √(её урон − его лечение) × её хиты; mods — её
     *  гипотетические множители, oppMods — множитель лечения противника. */
    private fun powerOf(side: List<Creep>, opp: List<Creep>, mods: HypoMods, oppMods: HypoMods): Double {
        val dps = side.sumOf { effectiveDps(it, opp, mods.ranged, mods.melee) }
        val heal = opp.sumOf { InfluenceMap.profileOf(it).heal } * oppMods.heal
        return lanchester(dps, heal, side.sumOf { weightedHits(it, opp, mods.hits) })
    }

    /** НАША мощь против группы врага (текущие эффекты). */
    private fun ourPowerOf(ours: List<Creep>, theirs: List<Creep>): Double = powerOf(ours, theirs, NO_MODS, NO_MODS)

    /** Мощь врага против нашей группы (текущие эффекты). */
    private fun enemyPowerOf(theirs: List<Creep>, ours: List<Creep>): Double = powerOf(theirs, ours, NO_MODS, NO_MODS)

    /** Тики хода крипа по спуску вдоль поля потока от клетки до цели — по его телу и местности (periodAt). */
    private fun pathTicks(creep: Creep, flow: IntArray, startCell: Int): Int {
        var cell = startCell
        if (cell < 0 || flow[cell] < 0) return Int.MAX_VALUE / 2
        var ticks = 0
        var steps = 0
        while (flow[cell] > 0 && steps < 400) {
            val cx = cell / 100
            val cy = cell % 100
            var best = -1
            var bestFlow = flow[cell]
            for (dx in -1..1) for (dy in -1..1) {
                val nx = cx + dx
                val ny = cy + dy
                if (nx < 0 || ny < 0 || nx > 99 || ny > 99) continue
                val f = flow[nx * 100 + ny]
                if (f in 0 until bestFlow) { bestFlow = f; best = nx * 100 + ny }
            }
            if (best < 0) break
            cell = best
            steps++
            ticks += periodAt(creep, cell / 100, cell % 100)
        }
        return ticks
    }

    private fun inContact(enemies: List<Creep>, ours: List<Creep>): Boolean =
        enemies.any { e -> ours.any { getRange(e, it) <= RANGED_RANGE + 1 } }

    /** Матрица пути захватчика: опасность + свои крипы дороже + не наши флаги стены, кроме allowCell (его флаг). */
    private fun crowdMatrixOf(ctx: Ctx, allowCell: Int): CostMatrix {
        val crowdMatrix = ctx.rawDanger.clone()
        for (ally in ctx.active) {
            val current = crowdMatrix.get(ally.x, ally.y)
            if (current < 255) crowdMatrix.set(ally.x, ally.y, minOf(254, current + CROWD_COST))
        }
        for (c in ctx.flagCells) if (c != allowCell) crowdMatrix.set(c / 100, c % 100, 255)
        return crowdMatrix
    }

    /** Жадный шаг бегства: свободная соседняя клетка (не стена, не чужой флаг, не занята) с наибольшей
     *  дальностью до ближайшего врага, при равной — под меньшим огнём; null — некуда. */
    private fun greedyFlee(ctx: Ctx, creep: Creep, enemies: List<Creep>, force: Boolean = false): Position? {
        val occupied = (ctx.myCreeps + ctx.enemyCreeps).filter { !it.spawning }.mapTo(HashSet()) { it.x * 100 + it.y }
        var best: Position? = null
        // force: лучшая из соседних, даже если она не лучше своей клетки (см. SCOUT_FLEE_TRIGGER)
        var bestRange = if (force) -1 else (enemies.minOfOrNull { getRange(creep, it) } ?: 0)
        var bestFire = if (force) Double.MAX_VALUE else InfluenceMap.fireAt(creep.x, creep.y, enemies)
        for ((dx, dy) in DIRECTIONS) {
            if (dx == 0 && dy == 0) continue
            val x = creep.x + dx; val y = creep.y + dy
            if (x < 0 || y < 0 || x > 99 || y > 99) continue
            val key = x * 100 + y
            if (key in occupied || key in ctx.flagCells || DistanceMap.isWall(x, y) || ctx.blocked.any { it.x == x && it.y == y }) continue
            val pos = InfluenceMap.cell(x, y)
            val range = enemies.minOfOrNull { getRange(pos, it) } ?: 0
            val fire = InfluenceMap.fireAt(x, y, enemies)
            if (range > bestRange || (range == bestRange && fire < bestFire)) { best = pos; bestRange = range; bestFire = fire }
        }
        return best
    }

    private fun pathStep(creep: Creep, target: Position, range: Int, dangerMatrix: CostMatrix): Position? {
        val goal = SearchGoal(pos = target, range = range)
        val result = searchPath(creep, goal, SearchPathOptions(costMatrix = dangerMatrix))
        return result.path.firstOrNull()
    }

    private fun fleeStep(creep: Creep, enemies: List<Creep>, dangerMatrix: CostMatrix, range: Int = RANGED_RANGE): Position? {
        if (enemies.isEmpty()) return null
        val goals = enemies.map { e -> SearchGoal(pos = InfluenceMap.cell(e.x, e.y), range = range) }.toTypedArray()
        val result = searchPath(creep, goals, SearchPathOptions(flee = true, costMatrix = dangerMatrix))
        return result.path.firstOrNull()
    }

    private fun centroidOf(points: List<Position>): Position? {
        if (points.isEmpty()) return null
        return InfluenceMap.cell(points.sumOf { it.x } / points.size, points.sumOf { it.y } / points.size)
    }

    // ==================== диагностика ====================

    private fun logStuck(active: List<Creep>, enemyCreeps: List<Creep>) {
        for (c in active) {
            if (TrafficManager.stuckFor(c.id) != TrafficManager.STUCK_TICKS) continue
            val want = TrafficManager.lastDesiredOf(c.id)
            val occ = want?.let { w -> (active + enemyCreeps).firstOrNull { it.x * 100 + it.y == w } }
            val occWant = occ?.let { TrafficManager.lastDesiredOf(it.id) }
            println("stuck ${c.id} at (${c.x},${c.y}) fatigue=${c.fatigue} wants=${want?.let { "(${it / 100},${it % 100})" }} " +
                "occ=${occ?.let { "${it.id} my=${it.my} fatigue=${it.fatigue} ${bodySummary(it)} wants=${occWant?.let { w -> "(${w / 100},${w % 100})" } ?: "-"}" } ?: "free"}")
        }
    }

    /** ASCII-карта один раз: '#' стена, '~' болото, '.' равнина, 'F' флаг, 'm' наш крип, 'e' вражеский. */
    private fun captureMapMarks(flags: List<FlagInfo>, myCreeps: List<Creep>, enemyCreeps: List<Creep>) {
        val m = HashMap<Int, Char>()
        fun mark(x: Int, y: Int, c: Char) { m[x * 100 + y] = c }
        getObjectsByPrototype(StructureWall::class).forEach { mark(it.x, it.y, '#') }
        getObjectsByPrototype(StructureRampart::class).forEach { mark(it.x, it.y, 'R') }
        getObjectsByPrototype(StructureSpawn::class).forEach { mark(it.x, it.y, if (it.my == true) 'M' else 'E') }
        enemyCreeps.forEach { mark(it.x, it.y, 'e') }
        myCreeps.forEach { mark(it.x, it.y, 'm') }
        flags.forEach { mark(it.pos.x, it.pos.y, 'F') }
        mapMarks = m
    }

    /** Дамп карты — четырьмя частями по 25 строк на тиках 3–6, одной строкой каждая: сто println на холодном первом
     *  тике упирались в лимит (матч 17), а весь дамп вторым тиком — в бюджет 100 мс (матч 18). Метки крипов сняты на
     *  первом тике (см. captureMapMarks), чтобы стенд получал стартовые клетки. */
    private fun logMap(fromRow: Int) {
        val marks = mapMarks ?: return
        val out = StringBuilder(if (fromRow == 0) "=== MAP (rows y=0..99, cols x=0..99) ===" else "")
        for (y in fromRow until minOf(fromRow + 25, 100)) {
            val row = StringBuilder()
            for (x in 0..99) {
                val isWall = DistanceMap.isTerrainWall(x, y)
                val isSwamp = !isWall && DistanceMap.isSwamp(x, y)
                val structure = marks[x * 100 + y]
                row.append(
                    when {
                        structure != null -> structure
                        isWall -> '#'
                        isSwamp -> '~'
                        else -> '.'
                    }
                )
            }
            if (out.isNotEmpty()) out.append('\n')
            out.append(y.toString().padStart(2, '0')).append(':').append(row)
        }
        println(out.toString())
        if (fromRow + 25 >= 100) {
            var swamp = 0
            var wall = 0
            for (y in 0..99) for (x in 0..99) { if (DistanceMap.isTerrainWall(x, y)) wall++ else if (DistanceMap.isSwamp(x, y)) swamp++ }
            println("=== END MAP swamp=$swamp wall=$wall plain=${10000 - swamp - wall} ===")
        }
    }
}
